window.CONTENT=window.CONTENT||{};window.CONTENT.ict=window.CONTENT.ict||{};
window.CONTENT.ict[10]=[{"t":"1-dars. Ma‘lumot, axborot va bilimlar bazasi. Ma‘lumot manbasi. Bevosita va bilvosita manbalardan ma‘lumot to‘plashning afzallik hamda kamchiliklari. Axborotning sifati","lesson":"<p><b>Ma’lumot</b> — qayta ishlanmagan xom faktlar, raqamlar va belgilar. <b>Axborot</b> — ma’lumotlar qayta ishlanib, ma’no va kontekst berilganda hosil bo‘ladi. <b>Bilim</b> — axborotni tushunish, tajriba bilan bog‘lash va qaror qabul qilishda qo‘llash.</p>\n<div class=\"ex\"><b>Misol.</b> “35, 40, 28” — ma’lumot. “Sinfdagi o‘quvchilarning bo‘yi: 35 ta qiz, 40 ta o‘g‘il…” — kontekst bilan axborot bo‘ladi.</div>\n<h4>Ma’lumot manbalari</h4>\n<ul><li><b>Bevosita (birlamchi) manba</b> — ma’lumotni o‘zimiz to‘playmiz: so‘rovnoma, intervyu, kuzatish, tajriba. Afzalligi: aynan maqsadga mos va yangi; kamchiligi: ko‘p vaqt va mablag‘ketadi.</li>\n<li><b>Bilvosita (ikkilamchi) manba</b> — boshqalar to‘plagan tayyor ma’lumot: kitob, internet, statistika. Afzalligi: tez va arzon; kamchiligi: eskirgan yoki noaniq bo‘lishi mumkin.</li></ul>\n<h4>Axborot sifati</h4>\n<p>Sifatli axborot <b>aniq, to‘liq, dolzarb, ishonchli, o‘z vaqtida va maqsadga mos</b> bo‘ladi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Bilimlar bazasi — tartibga solingan bilimlar to‘plami.</li><li>Manbani tanlashda ishonchlilik va yangilik muhim.</li></ul>","quiz":[{"q":"Qayta ishlanmagan xom faktlar va raqamlar nima deb ataladi?","o":["Bilim","Bilimlar bazasi","Ma’lumot","Axborot sifati"],"a":2,"e":"Ma’lumot — hali qayta ishlanmagan, ma’nosi aniqlanmagan faktlar."},{"q":"Ma’lumotlar qayta ishlanib, ma’no va kontekst olganda nima hosil bo‘ladi?","o":["Axborot","Xom ma’lumot","Kod","Shifr"],"a":0,"e":"Kontekst bilan boyitilgan ma’lumot axborot deyiladi."},{"q":"Quyidagilardan qaysi biri bevosita manbadan ma’lumot to‘plash usuli?","o":["Internetdan tayyor jadval yuklash","Ensiklopediyadan o‘qish","Eski gazetadan nusxa olish","Sinfdoshlar orasida so‘rovnoma o‘tkazish"],"a":3,"e":"So‘rovnoma ma’lumotni bevosita o‘zimiz to‘plashimizni bildiradi."},{"q":"Bilvosita manbadan foydalanishning asosiy afzalligi qaysi?","o":["Ma’lumot faqat bizga tegishli bo‘lishi","Ma’lumotni tekshirish shart emasligi","Ma’lumotga tez va arzon yetib borish","Ma’lumot albatta eng yangi bo‘lishi"],"a":2,"e":"Tayyor ma’lumot tez topiladi, ammo uning ishonchliligini tekshirish kerak."},{"q":"Bevosita manbaning kamchiligi qaysi?","o":["Ma’lumotni boshqa odam to‘plagani","Ma’lumotning hech qachon yangi bo‘lmasligi","Ma’lumotning maqsadga mos kelmasligi","Ko‘p vaqt va mablag‘ talab qilishi"],"a":3,"e":"Birlamchi ma’lumot to‘plash odatda ko‘p vaqt oladi."},{"q":"Axborot sifatining ko‘rsatkichi bo‘lmagan xususiyat qaysi?","o":["Dolzarblik","Ishonchlilik","Hajmining juda kattaligi","Aniqlik"],"a":2,"e":"Hajm sifat ko‘rsatkichi emas; muhimi aniqlik, dolzarblik, ishonchlilik."},{"q":"Bir yil oldingi ob-havo ma’lumoti bugungi sayohatni rejalashtirishda qaysi sifat bo‘yicha yaroqsiz?","o":["Dolzarblik","Hajm","To‘liqlik","Aniqlik"],"a":0,"e":"Eskirgan axborot dolzarb emas."},{"q":"Bilimlar bazasi nima?","o":["Tartibga solingan bilimlar to‘plami","Antivirus dasturi","Faqat raqamlar jadvali","Tarmoq qurilmasi"],"a":0,"e":"Bilimlar bazasida bilimlar tizimli saqlanadi."},{"q":"“Axborot to‘liq” degani nimani bildiradi?","o":["U faqat rasmlardan iborat","U juda qisqa","Qaror qabul qilish uchun zarur hamma ma’lumot mavjud","U faqat internetda joylashgan"],"a":2,"e":"To‘liq axborotda zarur ma’lumotlar yetishmovchiligi yo‘q."},{"q":"Quyidagilardan qaysi biri bilvosita manba hisoblanadi?","o":["O‘tkazilgan intervyu","O‘z tajribangiz natijasi","Shaxsiy kuzatuv daftari","Kutubxonadagi darslik"],"a":3,"e":"Darslik — boshqalar tayyorlagan ikkilamchi manba."}]},{"t":"2-dars. Kod berish, kodlash va shifrlash. Ma‘lumotlarni kodlashning afzallik va kamchiliklari. Simmetrik va asimmetrik shifrlash usullari.","lesson":"<p><b>Kod berish</b> — ma’lumotni boshqa ko‘rinishda belgilash (masalan, harfni raqamga almashtirish). <b>Kodlash</b> — ma’lumotni kompyuter tushunadigan ko‘rinishga o‘tkazish. <b>Shifrlash</b> — ma’lumotni ruxsatsiz shaxslardan yashirish maqsadida o‘qib bo‘lmaydigan ko‘rinishga keltirish.</p>\n<h4>Kodlashning afzalliklari va kamchiliklari</h4>\n<ul><li>Afzalligi: ma’lumot ixcham saqlanadi, tez uzatiladi.</li><li>Kamchiligi: kodlash jadvalini bilmagan odam tushunmaydi, kodlash va tiklash vaqt oladi.</li></ul>\n<h4>Shifrlash usullari</h4>\n<ul><li><b>Simmetrik</b> — shifrlash va ochish uchun <b>bitta umumiy kalit</b> ishlatiladi. Tez ishlaydi, lekin kalitni xavfsiz yetkazish qiyin.</li>\n<li><b>Asimmetrik</b> — <b>ikkita kalit</b>: ochiq (shifrlash uchun) va yopiq (ochish uchun). Kalit almashish xavfsizroq, lekin sekinroq.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Sezar shifrida har bir harf alifbodagi 3 o‘rin keyingi harfga almashtiriladi — bu simmetrik shifrning oddiy ko‘rinishi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Simmetrik: bitta kalit.</li><li>Asimmetrik: ochiq va yopiq kalit juftligi.</li></ul>","quiz":[{"q":"Ma’lumotni ruxsatsiz shaxslardan yashirish uchun o‘qib bo‘lmaydigan ko‘rinishga keltirish nima deyiladi?","o":["Kodlash jadvali","Arxivlash","Shifrlash","Formatlash"],"a":2,"e":"Shifrlash maxfiylikni ta’minlaydi."},{"q":"Simmetrik shifrlashda nechta kalit ishlatiladi?","o":["Har bir harf uchun yangi kalit va parol","Ikkita turli kalit","Kalit ishlatilmaydi","Shifrlash va ochish uchun bitta umumiy kalit"],"a":3,"e":"Simmetrik usulda ikkala amalga ham bir xil kalit xizmat qiladi."},{"q":"Asimmetrik shifrlashda qaysi kalitlar ishlatiladi?","o":["Faqat parol","Faqat ochiq kalit","Faqat yopiq kalit","Ochiq va yopiq kalit"],"a":3,"e":"Ochiq kalit shifrlaydi, yopiq kalit ochadi."},{"q":"Simmetrik shifrlashning asosiy kamchiligi qaysi?","o":["Faqat matnni shifrlashi","Umumiy kalitni xavfsiz yetkazish qiyinligi","Kalit yo‘qligi","Juda sekin ishlashi"],"a":1,"e":"Kalit qo‘lga tushsa, hammasi ochiladi, shuning uchun uni yetkazish xavfli."},{"q":"Asimmetrik usulning afzalligi nima?","o":["Maxfiy kalitni uzatish shart emas","Eng tez ishlashi","Faqat kichik fayllarga mosligi","Hech qanday kalit kerak emasligi"],"a":0,"e":"Ochiq kalitni hamma bilishi mumkin, yopiq kalit egasida qoladi."},{"q":"Sezar shifri qaysi turga kiradi?","o":["Antivirus turiga","Asimmetrik shifrga","Simmetrik shifrga","Kodlash jadvaliga emas, tarmoq protokoliga"],"a":2,"e":"Sezar shifrida shifrlash va ochish uchun bir xil siljish (kalit) ishlatiladi."},{"q":"Ma’lumotni kodlashning afzalligi qaysi?","o":["Albatta maxfiylik kafolati","Kalit kerak emasligi","Ma’lumot hajmi doim ortishi","Ixcham saqlash va tez uzatish"],"a":3,"e":"Kodlash ma’lumotni qulay ko‘rinishga keltiradi, lekin maxfiylikni kafolatlamaydi."},{"q":"Kodlash va shifrlash orasidagi asosiy farq nima?","o":["Shifrlash faqat rasmlarga qo‘llanadi","Ularda hech qanday farq yo‘q","Kodlash doim kalit talab qiladi","Shifrlashdan maqsad ma’lumotni yashirish"],"a":3,"e":"Kodlash ko‘rinishni o‘zgartiradi, shifrlash esa maxfiylikni ta’minlaydi."},{"q":"Ochiq kalit qanday vazifani bajaradi?","o":["Faylni arxivlaydi","Ma’lumotni ochish uchun faqat egasida qoladi","Ma’lumotni shifrlash uchun beriladi","Virusni topadi"],"a":2,"e":"Ochiq kalit hammaga beriladi va shifrlash uchun ishlatiladi."},{"q":"Kalitni bilmagan odam shifrlangan xabarni o‘qiy olmasligi nimani ta’minlaydi?","o":["Tezlikni","Rasm sifatini","Maxfiylikni","Saqlash hajmini"],"a":2,"e":"Shifrlashning asosiy maqsadi — maxfiylik."}]},{"t":"3-dars. Ma‘lumotlarning to‘g‘riligini tekshirish.","lesson":"<p>Ma’lumotlar kiritilganda yoki uzatilganda xato bo‘lishi mumkin. Ularni kamaytirish uchun <b>ma’lumotlarning to‘g‘riligini tekshirish</b> usullari qo‘llaniladi. Bu yerda ikki tushuncha farqlanadi: <b>verifikatsiya</b> (kiritilgan ma’lumot manbaga mosligini tekshirish) va <b>validatsiya</b> (ma’lumot qabul qilinadigan qoidalarga mosligini tekshirish).</p>\n<h4>Validatsiya turlari</h4>\n<ul><li><b>Diapazon tekshiruvi</b> — qiymat belgilangan oraliqda bo‘lishi (masalan, baho 2 dan 5 gacha).</li>\n<li><b>Tur tekshiruvi</b> — kerakli turdagi ma’lumot kiritilishi (yoshga raqam).</li>\n<li><b>Uzunlik tekshiruvi</b> — belgilar soni mos bo‘lishi.</li>\n<li><b>Mavjudlik tekshiruvi</b> — majburiy maydon bo‘sh qolmasligi.</li>\n<li><b>Format tekshiruvi</b> — sana yoki telefon raqami shablonga mos kelishi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Sinf jurnaliga baho sifatida “7” kiritilsa, diapazon tekshiruvi uni rad etadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Validatsiya ma’lumotning <b>mantiqan to‘g‘ri</b> ekanini tekshiradi, lekin <b>haqiqatan to‘g‘ri</b> ekanini kafolatlamaydi.</li></ul>","quiz":[{"q":"Qiymatning belgilangan oraliqda bo‘lishini tekshirish qaysi tekshiruv?","o":["Mavjudlik tekshiruvi","Tur tekshiruvi","Diapazon tekshiruvi","Uzunlik tekshiruvi"],"a":2,"e":"Diapazon tekshiruvi qiymat chegaralardan chiqmasligini nazorat qiladi."},{"q":"Majburiy maydon bo‘sh qolmasligini tekshirish qanday ataladi?","o":["Mavjudlik tekshiruvi","Format tekshiruvi","Tur tekshiruvi","Diapazon tekshiruvi"],"a":0,"e":"Mavjudlik tekshiruvi bo‘sh maydonlarni rad etadi."},{"q":"Yosh maydoniga harf kiritilishini to‘xtatadigan tekshiruv qaysi?","o":["Tur tekshiruvi","Nusxa tekshiruvi","Uzunlik tekshiruvi","Diapazon tekshiruvi"],"a":0,"e":"Tur tekshiruvi ma’lumot turi mosligini tekshiradi."},{"q":"Parol kamida 8 belgidan iborat bo‘lishini talab qiluvchi tekshiruv qaysi?","o":["Mavjudlik tekshiruvi","Tur tekshiruvi","Uzunlik tekshiruvi","Diapazon tekshiruvi"],"a":2,"e":"Belgilar sonini nazorat qilish uzunlik tekshiruvidir."},{"q":"Telefon raqami shablonga mosligini tekshirish qaysi tekshiruv?","o":["Mavjudlik tekshiruvi","Diapazon tekshiruvi","Uzunlik tekshiruvi emas, balki kodlash","Format tekshiruvi"],"a":3,"e":"Format tekshiruvi ma’lumotning belgilangan ko‘rinishda ekanini aniqlaydi."},{"q":"Baho maydoniga 2 dan 5 gacha son kiritish talabi qaysi tekshiruvga misol?","o":["Uzunlik tekshiruvi","Diapazon tekshiruvi","Format tekshiruvi","Mavjudlik tekshiruvi"],"a":1,"e":"Qiymat 2 dan 5 gacha oraliqda bo‘lishi kerak."},{"q":"Validatsiya nimani kafolatlamaydi?","o":["Ma’lumot haqiqatan to‘g‘ri ekanini","Ma’lumot qoidaga mosligini","Raqam kiritilganini","Maydon to‘ldirilganini"],"a":0,"e":"Qoidaga mos ma’lumot ham noto‘g‘ri bo‘lishi mumkin (masalan, ism xato yozilgan)."},{"q":"Validatsiya nimani tekshiradi?","o":["Ma’lumot qabul qilinadigan qoidalarga mosligini","Faqat qurilma tezligini","Faqat fayl hajmini","Faqat tarmoq xavfsizligini"],"a":0,"e":"Validatsiya kiritilgan ma’lumotning ma’qulligini tekshiradi."},{"q":"Foydalanuvchi tug‘ilgan yilga 3050 kiritsa, qaysi tekshiruv uni rad etishi mumkin?","o":["Mavjudlik tekshiruvi","Tur tekshiruvi emas, shifrlash","Arxivlash","Diapazon tekshiruvi"],"a":3,"e":"Mantiqsiz yil oraliqdan tashqarida."},{"q":"Ma’lumotlarni tekshirishdan asosiy maqsad nima?","o":["Ma’lumot hajmini oshirish","Tarmoq tezligini oshirish","Ma’lumotni shifrlash","Xatolarni kamaytirish va sifatni oshirish"],"a":3,"e":"Tekshiruv xatolarning oldini oladi."}]},{"t":"4-dars. Vizual tekshirish va ma‘lumotlanri ikki marta kiritish.","lesson":"<p>Ma’lumotlar kiritilganda xato qilish oson: harf tushib qolishi, raqamlar o‘rni almashishi mumkin. Shuning uchun kiritilgan ma’lumotni tekshirishning ikki oddiy usuli bor.</p>\n<h4>Vizual tekshirish</h4>\n<p>Kiritilgan ma’lumot ekranda asl manba (qog‘oz hujjat, ro‘yxat) bilan ko‘z orqali solishtiriladi. Bu usul tez va qo‘shimcha dastur talab qilmaydi.</p>\n<ul><li>Afzalligi: oddiy, tez, arzon.</li><li>Kamchiligi: inson e’tiborsizligiga bog‘liq, uzun ro‘yxatlarda charchoq tufayli xato o‘tib ketadi.</li></ul>\n<h4>Ikki marta kiritish</h4>\n<p>Bir xil ma’lumot ikki marta kiritiladi (ba’zan ikki xodim tomonidan) va dastur ikkala kiritishni solishtiradi. Farq topilsa, xato borligi aniqlanadi.</p>\n<ul><li>Afzalligi: tasodifiy xatolar ishonchli topiladi (masalan, parol yaratishda “parolni takrorlang” maydoni).</li><li>Kamchiligi: vaqt va mehnat ikki baravar ko‘p sarflanadi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Telefon raqami 901234567 o‘rniga 901243567 kiritildi. Vizual tekshirishda e’tibor bermasa, xato o‘tadi; ikki marta kiritishda esa ikki qiymat mos kelmaydi va dastur xabar beradi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Vizual tekshirish — ko‘z bilan solishtirish.</li><li>Ikki marta kiritishda ikki kiritish dastur bilan solishtiriladi.</li><li>Ikkala usul ham faqat kiritish xatolarini topadi, ma’lumot haqiqiyligini kafolatlamaydi.</li></ul>","quiz":[{"q":"Vizual tekshirish nima?","o":["Ma’lumotni avtomatik shifrlash","Ekrandagi ma’lumotni asl manba bilan ko‘z orqali solishtirish","Ma’lumotni ikki marta saqlash","Virusga qarshi dastur bilan skanerlash"],"a":1,"e":"Vizual tekshirishda inson ko‘zi bilan solishtiriladi."},{"q":"Ikki marta kiritish usulida nima qilinadi?","o":["Bir xil ma’lumot ikki marta kiritilib, ikkalasi solishtiriladi","Ma’lumot bir marta kiritilib, nusxa olinadi","Ma’lumot arxivlanadi","Ma’lumot faqat qog‘ozda yoziladi"],"a":0,"e":"Mos kelmaslik xato borligini bildiradi."},{"q":"Parol yaratishda “parolni takrorlang” maydoni qaysi usulga misol?","o":["Vizual tekshirishga","Arxivlashga","Shifrlashga","Ikki marta kiritishga"],"a":3,"e":"Ikkala kiritilgan parol solishtiriladi."},{"q":"Vizual tekshirishning kamchiligi qaysi?","o":["Ma’lumot yo‘qolishi","Faqat raqamlar bilan ishlashi","Inson e’tiborsizligi tufayli xato o‘tib ketishi mumkin","Maxsus qimmat dastur talab qilinishi"],"a":2,"e":"Charchoq va e’tiborsizlik xatoga sabab bo‘ladi."},{"q":"Ikki marta kiritishning kamchiligi qaysi?","o":["Xatolarni umuman topa olmaydi","Vaqt va mehnat ko‘proq sarflanadi","Kompyuter talab qilinmaydi","Faqat matn bilan ishlaydi"],"a":1,"e":"Ma’lumotni ikki marta kiritish ishni cho‘zadi."},{"q":"Telefon raqami 901234567 o‘rniga 901243567 kiritilgan. Qaysi usul xatoni ishonchliroq topadi?","o":["Ekran yorqinligini oshirish","Ikki marta kiritish","Faylni arxivlash","Faqat fayl nomini o‘zgartirish"],"a":1,"e":"Ikki kiritish mos kelmaydi, dastur xabar beradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Ikkala usul kiritish xatolarini kamaytiradi","Ular virusdan himoya qiladi","Ular ma’lumot haqiqiyligini 100 foiz kafolatlaydi","Ular faqat rasmlarga qo‘llanadi"],"a":0,"e":"Ular tasodifiy kiritish xatolarini topadi, lekin manbaning o‘zi noto‘g‘ri bo‘lsa, buni sezmaydi."},{"q":"Uzun ro‘yxatni tekshirishda vizual usul nega ishonchsiz bo‘lishi mumkin?","o":["Ekran juda kichik bo‘ladi","Inson charchaydi va e’tibor pasayadi","Ro‘yxat shifrlangan bo‘ladi","Kompyuter sekin ishlaydi"],"a":1,"e":"Inson omili asosiy muammo."},{"q":"Ikki xodim bir xil ma’lumotni alohida kiritib, natijalar solishtirilsa, bu qaysi usul?","o":["Kodlash","Vizual tekshirish","Simmetrik shifrlash","Ikki marta kiritish"],"a":3,"e":"Ikki mustaqil kiritishni solishtirish."},{"q":"Ikki kiritish natijasi mos kelmasa, nimani anglatadi?","o":["Kamida bitta kiritishda xato bor","Kompyuter virus yuqtirgan","Ma’lumot albatta to‘g‘ri","Fayl shikastlangan"],"a":0,"e":"Farq xato mavjudligini ko‘rsatadi."}]},{"t":"5-dars. Apparat ta‘minot. Ichki va tashqi qurilmalar","lesson":"<p><b>Apparat ta’minot</b> (hardware) — kompyuterning qo‘l bilan ushlab ko‘rsa bo‘ladigan jismoniy qismlari. Ular ichki va tashqi qurilmalarga bo‘linadi.</p>\n<h4>Ichki qurilmalar</h4>\n<p>Tizim blokining ichida joylashadi:</p>\n<ul><li><b>Protsessor (CPU)</b> — buyruqlarni bajaradi, hisoblashlarni olib boradi;</li><li><b>Operativ xotira (RAM)</b> — ishlayotgan dastur va ma’lumotlar vaqtincha turadi;</li><li><b>Ona plata</b> — barcha qurilmalarni bir-biriga bog‘laydi;</li><li><b>Doimiy xotira (qattiq disk, SSD)</b> — ma’lumotlar uzoq saqlanadi;</li><li><b>Videokarta, tovush kartasi, ta’minot bloki</b>.</li></ul>\n<h4>Tashqi qurilmalar</h4>\n<p>Kompyuterga tashqaridan ulanadi:</p>\n<ul><li><b>Kiritish qurilmalari:</b> klaviatura, sichqoncha, skaner, mikrofon;</li><li><b>Chiqarish qurilmalari:</b> monitor, printer, karnay;</li><li><b>Kiritish va chiqarish:</b> sensorli ekran, tashqi disk.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Hujjat chop etilganda ma’lumot protsessor orqali ishlanadi, so‘ng printerga (tashqi chiqarish qurilmasiga) uzatiladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Apparat ta’minot — kompyuterning jismoniy qismi.</li><li>Protsessor kompyuterning “miyasi”, RAM esa vaqtinchalik xotira.</li><li>Tashqi qurilmalar kiritish va chiqarish vazifasini bajaradi.</li></ul>","quiz":[{"q":"Apparat ta’minot nima?","o":["Foydalanuvchi parollari","Kompyuterda o‘rnatilgan dasturlar","Kompyuterning jismoniy qurilmalari majmui","Internet tarmog‘i"],"a":2,"e":"Hardware kompyuterning moddiy qismi."},{"q":"Quyidagilardan qaysi biri ichki qurilma?","o":["Monitor","Ona plata","Printer","Skaner"],"a":1,"e":"Ona plata tizim blokining ichida joylashadi."},{"q":"Buyruqlarni bajaradigan va hisoblashlarni olib boradigan qurilma qaysi?","o":["Klaviatura","Protsessor","Printer","Karnay"],"a":1,"e":"Protsessor kompyuterning asosiy hisoblash qurilmasi."},{"q":"Quyidagilardan qaysi biri kiritish qurilmasi?","o":["Printer","Monitor","Skaner","Karnay"],"a":2,"e":"Skaner tasvirni kompyuterga kiritadi."},{"q":"Quyidagilardan qaysi biri chiqarish qurilmasi?","o":["Sichqoncha","Mikrofon","Monitor","Klaviatura"],"a":2,"e":"Monitor axborotni ekranga chiqaradi."},{"q":"Operativ xotira (RAM) haqida qaysi fikr to‘g‘ri?","o":["Ishlayotgan dastur va ma’lumotlar vaqtincha saqlanadi","Kompyuter o‘chirilganda ham ma’lumotlar saqlanadi","Qurilmalarni elektr bilan ta’minlaydi","Faqat tovushni chiqaradi"],"a":0,"e":"RAM uchun xos xususiyat: vaqtinchalik xotira."},{"q":"Barcha ichki qurilmalarni o‘zaro bog‘laydigan asosiy plata qaysi?","o":["Videokarta","Ona plata","Ta’minot bloki","Tovush kartasi"],"a":1,"e":"Ona plata (motherboard) aloqani ta’minlaydi."},{"q":"Mikrofon qaysi guruhga kiradi?","o":["Ichki chiqarish qurilmalari","Dasturiy ta’minot","Tashqi kiritish qurilmalari","Xotira qurilmalari"],"a":2,"e":"Mikrofon tashqaridan tovushni kiritadi."},{"q":"Sensorli ekran qanday qurilma?","o":["Faqat chiqarish qurilmasi","Ham kiritish, ham chiqarish qurilmasi","Faqat ichki qurilma","Faqat xotira qurilmasi"],"a":1,"e":"U tasvir ko‘rsatadi va teginishni qabul qiladi."},{"q":"Hujjatni qog‘ozga chop etish uchun qaysi tashqi qurilma ishlatiladi?","o":["Sichqoncha","Printer","Mikrofon","Skaner"],"a":1,"e":"Printer chiqarish qurilmasi."}]},{"t":"6-dars. Xotira qurilmalari. Tizimli dasturiy ta‘minot. Drayverlar.","lesson":"<p><b>Xotira qurilmalari</b> ma’lumotni saqlash uchun xizmat qiladi. Ular ikki asosiy guruhga bo‘linadi.</p>\n<ul><li><b>Ichki (asosiy) xotira:</b> operativ xotira (RAM) — tez, lekin o‘chganda ma’lumot yo‘qoladi; doimiy xotira (ROM) — kompyuter yoqilganda kerak bo‘ladigan dastlabki ma’lumotlarni saqlaydi.</li>\n<li><b>Tashqi (doimiy) xotira:</b> qattiq disk (HDD), SSD, flesh-xotira, optik disklar (CD, DVD). Ma’lumot kompyuter o‘chirilsa ham saqlanadi.</li></ul>\n<p>SSD qattiq diskka qaraganda odatda tezroq ishlaydi, chunki unda harakatlanuvchi qismlar yo‘q.</p>\n<h4>Tizimli dasturiy ta’minot</h4>\n<p>Kompyuter ishini boshqaradigan dasturlar: <b>operatsion tizim</b> (Windows, Linux va boshqalar), utilitlar va drayverlar.</p>\n<h4>Drayverlar</h4>\n<p><b>Drayver</b> — operatsion tizim va qurilma o‘rtasida bog‘lovchi maxsus dastur. U qurilmani qanday boshqarishni tizimga “o‘rgatadi”.</p>\n<div class=\"ex\"><b>Misol.</b> Yangi printer ulangach, u ishlamasa, uning drayverini o‘rnatish yoki yangilash kerak.</div>\n<h4>Eslab qoling</h4>\n<ul><li>RAM vaqtinchalik, qattiq disk va flesh-xotira doimiy saqlaydi.</li><li>Operatsion tizim tizimli dasturiy ta’minotga kiradi.</li><li>Drayver qurilma bilan tizim o‘rtasida vositachi.</li></ul>","quiz":[{"q":"Kompyuter o‘chirilganda ma’lumotlari yo‘qoladigan xotira qaysi?","o":["SSD","Flesh-xotira","Operativ xotira (RAM)","Qattiq disk"],"a":2,"e":"RAM vaqtinchalik xotira."},{"q":"Quyidagilardan qaysi biri doimiy saqlash qurilmasi?","o":["Videokarta","Protsessor","Qattiq disk","RAM"],"a":2,"e":"Qattiq diskda ma’lumot uzoq saqlanadi."},{"q":"Drayver nima?","o":["Tashqi xotira turi","Antivirus dasturi","Qurilma va operatsion tizim o‘rtasidagi bog‘lovchi dastur","Matn muharriri"],"a":2,"e":"Drayver qurilmani boshqarishni ta’minlaydi."},{"q":"Yangi ulangan printer ishlamayapti. Birinchi navbatda nima qilish kerak?","o":["RAMni tozalash","Monitorni almashtirish","Uning drayverini o‘rnatish yoki yangilash","Operatsion tizimni o‘chirish"],"a":2,"e":"Drayver bo‘lmasa, tizim qurilmani tanimaydi."},{"q":"Quyidagilardan qaysi biri tizimli dasturiy ta’minotga kiradi?","o":["Video o‘yin","Operatsion tizim","Elektron jadval","Matn muharriri"],"a":1,"e":"Operatsion tizim kompyuter ishini boshqaradi."},{"q":"SSD haqida qaysi fikr to‘g‘ri?","o":["U faqat vaqtincha saqlaydi","Unda harakatlanuvchi qismlar yo‘q","U dasturiy ta’minotdir","U kiritish qurilmasi"],"a":1,"e":"SSD flesh-xotira asosida ishlaydi."},{"q":"Flesh-xotira qaysi guruhga kiradi?","o":["Kiritish qurilmasi","Operativ xotira","Drayver","Tashqi doimiy xotira"],"a":3,"e":"Flesh-xotira ma’lumotni uzoq saqlaydi va ko‘chirib olib yuriladi."},{"q":"Ishlayotgan dastur vaqtincha qayerda joylashadi?","o":["Skanerda","Monitorda","Operativ xotirada","Printerda"],"a":2,"e":"Dastur bajarilishi uchun RAMga yuklanadi."},{"q":"Quyidagi juftliklardan qaysi biri to‘g‘ri moslangan?","o":["Windows — operatsion tizim","SSD — dastur","RAM — doimiy saqlash","Drayver — kiritish qurilmasi"],"a":0,"e":"Windows operatsion tizimdir."},{"q":"Drayver o‘rnatilmagan qurilma qanday ishlaydi?","o":["Doim to‘liq ishlaydi","Tizim uni to‘g‘ri tanimasligi mumkin","Virusga aylanadi","Albatta tezroq ishlaydi"],"a":1,"e":"Drayversiz qurilma boshqarilmaydi."}]},{"t":"7-dars. Amaliy dasturiy ta‘minot. Fotosuratni tahrirlash dasturiy ta‘minoti","lesson":"<p><b>Amaliy dasturiy ta’minot</b> — foydalanuvchi o‘z maqsadidagi aniq vazifalarni bajarishi uchun mo‘ljallangan dasturlar. Ular tizimli dasturlardan farqli o‘laroq, kompyuterning o‘zini emas, foydalanuvchi ishini bajaradi.</p>\n<ul><li>matn muharrirlari (hujjat yozish);</li><li>elektron jadvallar (hisob-kitob);</li><li>taqdimot dasturlari;</li><li>grafik va video muharrirlar;</li><li>ma’lumotlar bazasi dasturlari.</li></ul>\n<h4>Fotosuratni tahrirlash dasturlari</h4>\n<p>Ular rasmni o‘zgartirish va yaxshilash uchun ishlatiladi. Asosiy imkoniyatlar:</p>\n<ul><li>kesish va o‘lchamini o‘zgartirish;</li><li>yorqinlik, kontrast va ranglarni sozlash;</li><li>qatlamlar bilan ishlash;</li><li>filtrlar qo‘llash, nuqsonlarni retush qilish;</li><li>turli formatda (JPEG, PNG) saqlash.</li></ul>\n<div class=\"ex\"><b>Amaliy qadamlar.</b> 1) Rasmni dasturda oching. 2) Keraksiz joyini kesing. 3) Yorqinlik va kontrastni sozlang. 4) Natijani yangi nom bilan saqlang, asl nusxa o‘zgarmasin.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Amaliy dastur foydalanuvchi vazifasini bajaradi.</li><li>Fotosuratni tahrirlash dasturida kesish, rang sozlash, qatlamlar va filtrlar bor.</li><li>Tahrirlangan rasmni yangi nom bilan saqlash asl nusxani asraydi.</li></ul>","quiz":[{"q":"Amaliy dasturiy ta’minot nima uchun mo‘ljallangan?","o":["Faqat tarmoqqa ulanish uchun","Foydalanuvchining aniq vazifalarini bajarish uchun","Kompyuter qurilmalarini boshqarish uchun","Faqat virusdan himoyalanish uchun"],"a":1,"e":"Amaliy dasturlar foydalanuvchi ishini bajaradi."},{"q":"Quyidagilardan qaysi biri amaliy dastur?","o":["Matn muharriri","Operatsion tizim","Ona plata","Drayver"],"a":0,"e":"Matn muharriri hujjat yozish uchun xizmat qiladi."},{"q":"Fotosuratni tahrirlash dasturi nima uchun kerak?","o":["Fayllarni arxivlash uchun","Rasmni o‘zgartirish va yaxshilash uchun","Hisob-kitob qilish uchun","Tarmoqni sozlash uchun"],"a":1,"e":"Bunday dasturlar rasm bilan ishlaydi."},{"q":"Fotomuharrirda rasmning keraksiz qismini olib tashlash qanday amal?","o":["Nusxalash","Kesish","Arxivlash","Shifrlash"],"a":1,"e":"Kesish rasm chegarasini o‘zgartiradi."},{"q":"Fotomuharrirda “qatlamlar” nima uchun kerak?","o":["Faylni arxivlash uchun","Ekran o‘lchamini o‘zgartirish uchun","Parol o‘rnatish uchun","Rasm elementlarini alohida tahrirlash uchun"],"a":3,"e":"Qatlamlar elementlarni bir-biriga ta’sir qilmasdan tahrirlash imkonini beradi."},{"q":"Rasm saqlashda asl nusxani yo‘qotmaslik uchun nima qilgan ma’qul?","o":["Eski faylni ustiga yozish","Faylni o‘chirish","Faylni shifrlash","Yangi nom bilan saqlash"],"a":3,"e":"Yangi nom asl nusxani saqlab qoladi."},{"q":"Quyidagilardan qaysi biri rasm formatiga misol?","o":["JPEG","XLSX","DOCX","MP3"],"a":0,"e":"JPEG tasvir formatidir."},{"q":"Rasmning yorqinligi va kontrastini sozlash qanday amal?","o":["Faylni siqish","Rangni tuzatish","Tarmoqqa ulash","Ma’lumotni kodlash"],"a":1,"e":"Bu rang va yorug‘likni tuzatish."},{"q":"Amaliy va tizimli dasturlar farqi haqida qaysi mulohaza to‘g‘ri?","o":["Tizimli dastur kompyuter ishini, amaliy dastur foydalanuvchi vazifasini ta’minlaydi","Amaliy dasturlar faqat o‘yinlardir","Amaliy dastur kompyuterni boshqaradi, tizimli dastur esa hujjat yozadi","Ikkalasi ham bir xil vazifani bajaradi"],"a":0,"e":"Tizimli dasturlar kompyuter ishini boshqaradi."},{"q":"Retush nima?","o":["Rasmni shifrlash","Rasmni tarmoqqa yuborish","Rasmdagi nuqsonlarni tuzatish","Rasmni o‘chirish"],"a":2,"e":"Retush surat sifatini yaxshilashdir."}]},{"t":"8-dars. Video tahrirlash dasturiy ta‘minoti. Veb sahifa ishlab chiqish dasturiy ta‘minoti","lesson":"<p><b>Video tahrirlash dasturlari</b> video lavhalarni kesish, birlashtirish va ularga tovush, matn, effekt qo‘shish uchun ishlatiladi.</p>\n<h4>Asosiy tushunchalar</h4>\n<ul><li><b>Vaqt chizig‘i (timeline)</b> — lavhalar ketma-ketligi joylashtiriladigan ish maydoni;</li><li><b>Kesish va bo‘lish</b> — keraksiz qismni olib tashlash;</li><li><b>O‘tish effektlari</b> — ikki lavha orasidagi silliq almashinuv;</li><li><b>Titr va tovush</b> — yozuv va musiqa qo‘shish;</li><li><b>Eksport</b> — tayyor videoni umumiy formatda (masalan, MP4) saqlash.</li></ul>\n<div class=\"ex\"><b>Qadamlar.</b> 1) Lavhalarni loyihaga qo‘shing. 2) Vaqt chizig‘iga tartib bilan joylashtiring. 3) Keraksiz joylarini kesing. 4) Tovush va titr qo‘shing. 5) Videoni eksport qiling.</div>\n<h4>Veb sahifa ishlab chiqish dasturlari</h4>\n<p>Veb sahifalar <b>HTML</b> tilida yoziladi, ko‘rinishi <b>CSS</b> yordamida bezatiladi. Buning uchun oddiy matn muharriri, maxsus kod muharrirlari yoki vizual veb-konstruktorlardan foydalanish mumkin. Tayyor sahifa brauzerda ochib tekshiriladi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Video montaj vaqt chizig‘ida bajariladi.</li><li>HTML — sahifa tuzilmasi, CSS — bezash.</li><li>Natija brauzerda tekshiriladi.</li></ul>","quiz":[{"q":"Video tahrirlash dasturida lavhalar joylashtiriladigan ish maydoni nima deyiladi?","o":["Vaqt chizig‘i (timeline)","Drayver","Katak","Ona plata"],"a":0,"e":"Timeline lavhalar ketma-ketligini ko‘rsatadi."},{"q":"Ikki lavha orasidagi silliq almashinuv nima deyiladi?","o":["O‘tish effekti","Arxivlash","Retush","Kodlash"],"a":0,"e":"O‘tish effekti sahnalarni bog‘laydi."},{"q":"Tayyor videoni umumiy formatda saqlash amali qanday ataladi?","o":["Import","Shifrlash","Formatlash","Eksport"],"a":3,"e":"Eksportda loyiha video fayliga aylanadi."},{"q":"Veb sahifa tuzilmasi qaysi tilda yoziladi?","o":["HTML","MP4","XLSX","JPEG"],"a":0,"e":"HTML sahifa tuzilmasini belgilaydi."},{"q":"Veb sahifaning ko‘rinishini bezash uchun nima ishlatiladi?","o":["RAM","Drayver","SSD","CSS"],"a":3,"e":"CSS ranglar va joylashuvni boshqaradi."},{"q":"Video montajning to‘g‘ri tartibini tanlang.","o":["Tovush, eksport, lavha qo‘shish, kesish","Lavhalarni qo‘shish, joylashtirish, kesish, tovush qo‘shish, eksport","Eksport, kesish, lavha qo‘shish, tovush","Kesish, eksport, joylashtirish, lavha qo‘shish"],"a":1,"e":"Avval material, oxirida eksport."},{"q":"Tayyor veb sahifani qayerda tekshirish mumkin?","o":["Mikrofonda","Printerda","Brauzerda","Skanerda"],"a":2,"e":"Veb sahifa brauzerda ochiladi."},{"q":"Videoga yozuv (titr) qo‘shish qaysi maqsadga xizmat qiladi?","o":["Faylni siqish","Rasmni retush qilish","Tarmoqni sozlash","Matnli izoh yoki sarlavha berish"],"a":3,"e":"Titr matnni ko‘rsatadi."},{"q":"Video tahrirlashda keraksiz qismni olib tashlash qanday amal?","o":["Drayver o‘rnatish","Kodlash","Kesish","Ikki marta kiritish"],"a":2,"e":"Kesish keraksiz parchani chiqarib tashlaydi."},{"q":"Quyidagilardan qaysi biri to‘g‘ri?","o":["Timeline veb sahifa tilidir","CSS videoni eksport qiladi","MP4 sahifa bezash tilidir","HTML sahifa mazmuni va tuzilmasini belgilaydi"],"a":3,"e":"HTML — tuzilma tili."}]},{"t":"9-dars. Foydalanuvchi interfeysi dizaynidagi boshqaruv elementlari. Utilit dasturlar. Buyurtma yoki tayyor dasturiy ta‘minot.","lesson":"<p><b>Foydalanuvchi interfeysi</b> — foydalanuvchi dastur bilan muloqot qiladigan qism. Uning qulayligi boshqaruv elementlariga bog‘liq.</p>\n<h4>Boshqaruv elementlari</h4>\n<ul><li><b>Tugma</b> — amalni bajarish uchun bosiladi;</li><li><b>Matn maydoni</b> — matn kiritiladi;</li><li><b>Belgilash katagi (checkbox)</b> — bir nechta variantdan bir nechtasini tanlash;</li><li><b>Radio tugma</b> — variantlardan faqat bittasini tanlash;</li><li><b>Ochiladigan ro‘yxat</b> — tayyor qiymatlardan tanlash;</li><li><b>Menyu</b> — buyruqlar guruhi.</li></ul>\n<h4>Utilit dasturlar</h4>\n<p><b>Utilitlar</b> — kompyuterga xizmat ko‘rsatuvchi yordamchi dasturlar: antivirus, arxivator, diskni tozalash va defragmentatsiya, zaxira nusxa olish dasturlari.</p>\n<h4>Buyurtma yoki tayyor dasturiy ta’minot</h4>\n<ul><li><b>Tayyor dastur:</b> arzonroq, darhol foydalanish mumkin, lekin barcha ehtiyojga mos kelmasligi mumkin.</li><li><b>Buyurtma dastur:</b> aynan tashkilot talabiga moslab yoziladi, lekin qimmat va uzoq vaqt talab qiladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab o‘z jurnalini yuritish uchun maxsus dastur buyurtma qilsa, bu buyurtma dastur; matn muharririni sotib olsa, tayyor dastur.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Checkbox — bir nechta, radio tugma — faqat bitta tanlov.</li><li>Utilit — xizmat dasturi.</li><li>Buyurtma dastur moslashuvchan, ammo qimmat.</li></ul>","quiz":[{"q":"Bir nechta variantdan faqat bittasini tanlashga imkon beradigan element qaysi?","o":["Menyu satri","Belgilash katagi","Radio tugma","Matn maydoni"],"a":2,"e":"Radio tugma yagona tanlovni ta’minlaydi."},{"q":"Bir nechta variantdan bir nechtasini tanlash uchun qaysi element qulay?","o":["Tugma","Radio tugma","Sarlavha","Belgilash katagi (checkbox)"],"a":3,"e":"Checkboxda bir vaqtda bir nechta belgilash mumkin."},{"q":"Utilit dasturlar nima?","o":["Kompyuterga xizmat ko‘rsatuvchi yordamchi dasturlar","Faqat veb sahifalar","Faqat o‘yin dasturlari","Apparat qurilmalar"],"a":0,"e":"Antivirus va arxivator utilitlarga misol."},{"q":"Quyidagilardan qaysi biri utilit?","o":["Rasm muharriri","Taqdimot dasturi","Elektron jadval","Arxivator"],"a":3,"e":"Arxivator fayllarni siqadi."},{"q":"Buyurtma dasturiy ta’minotning afzalligi nima?","o":["Eng arzon bo‘ladi","Tashkilot talablariga aynan moslab yoziladi","Hech qanday sinov talab qilmaydi","Darhol tayyor bo‘ladi"],"a":1,"e":"Moslashuvchanlik buyurtma dastur kuchi."},{"q":"Tayyor dasturiy ta’minotning kamchiligi nima?","o":["Juda qimmat va uzoq yaratiladi","Ishga tushirib bo‘lmaydi","Barcha ehtiyojga to‘liq mos kelmasligi mumkin","Foydalanuvchi uchun murakkab bo‘lishi shart"],"a":2,"e":"Tayyor dastur umumiy talablar uchun yoziladi."},{"q":"Tayyor tanlovlar ro‘yxatidan qiymat tanlash uchun qaysi element ishlatiladi?","o":["Radio tugma emas, rasm","Sarlavha","Ochiladigan ro‘yxat","Matn maydoni"],"a":2,"e":"Ochiladigan ro‘yxatda tayyor qiymatlar bo‘ladi."},{"q":"Maktab o‘ziga xos jurnal dasturini ishlab chiqaruvchidan yozdirdi. Bu qanday dastur?","o":["Drayver","Tayyor dastur","Buyurtma dastur","Utilit"],"a":2,"e":"Aynan buyurtmachi uchun yaratilgan."},{"q":"Ismni kiritish uchun qaysi boshqaruv elementi mos?","o":["Matn maydoni","Checkbox","Progress satri","Radio tugma"],"a":0,"e":"Matn maydoniga matn yoziladi."},{"q":"Diskni tozalash va zaxira nusxa olish dasturlari qaysi turga kiradi?","o":["Veb sahifalarga","Apparat ta’minotga","Amaliy o‘yinlarga","Utilit dasturlarga"],"a":3,"e":"Ular kompyuterga xizmat ko‘rsatadi."}]},{"t":"10-dars. Loyiha (amaliy) ishi","lesson":"<p><b>Loyiha ishi</b> — o‘quvchi mustaqil bajaradigan, aniq natijaga ega amaliy ish. Bu darsda birinchi chorakda o‘rganilgan bilimlarni (ma’lumotlar, kodlash, apparat va dasturiy ta’minot) birlashtirib, kichik loyiha tayyorlanadi.</p>\n<h4>Loyiha mavzusi (misol)</h4>\n<p>“Kompyuter tanlash bo‘yicha tavsiyalar”: tayyor yoki buyurtma dasturlar va qurilmalarni solishtirib, taqdimot yoki hujjat tayyorlash.</p>\n<div class=\"ex\"><b>Bajarish bosqichlari.</b>\n<ol><li>Mavzuni tanlang va maqsadni bir gapda yozing.</li><li>Ishonchli manbalardan ma’lumot to‘plang, manbalarni yozib qo‘ying.</li><li>Ma’lumotlarni tekshiring: haqiqiyligi va sifatiga e’tibor bering.</li><li>Tanlangan dastur (matn muharriri, taqdimot yoki jadval) yordamida natijani rasmiylashtiring.</li><li>Kiritilgan ma’lumotlarni vizual tekshiring.</li><li>Natijani sinfda taqdim eting.</li></ol></div>\n<h4>Nazorat savollari</h4>\n<ul><li>Ma’lumot manbasini qanday tanladingiz?</li><li>Qaysi dasturdan foydalandingiz va nega?</li><li>Ish davomida qanday xatolarni topdingiz?</li></ul>\n<h4>Eslab qoling</h4>\n<ul><li>Loyiha reja, bajarish, tekshirish va taqdimot bosqichlaridan iborat.</li><li>Manbalarni ko‘rsatish va ma’lumotni tekshirish zarur.</li></ul>","quiz":[{"q":"Loyiha ishi nima?","o":["Tasodifiy dastur ishga tushirish","Faqat nazariy savollarga javob","Aniq natijaga yo‘naltirilgan mustaqil amaliy ish","Faqat daftarga ko‘chirish"],"a":2,"e":"Loyiha aniq natijaga ega."},{"q":"Loyihani bajarishda birinchi qadam nima?","o":["Manbalarsiz xulosa chiqarish","Mavzu va maqsadni aniqlash","Natijani taqdim etish","Faylni o‘chirish"],"a":1,"e":"Reja avval maqsaddan boshlanadi."},{"q":"Ma’lumot to‘plashda nimaga e’tibor berish kerak?","o":["Faqat birinchi chiqqan sahifaga","Manbaning ishonchliligiga","Eng uzun matnga","Eng rangli sahifaga"],"a":1,"e":"Ishonchli manba sifatli ma’lumot beradi."},{"q":"Loyihada manbalarni yozib borish nega kerak?","o":["Rasm sifatini yaxshilash uchun","Fayl hajmini oshirish uchun","Kompyuterni tezlashtirish uchun","Ma’lumot qayerdan olinganini ko‘rsatish va tekshirish uchun"],"a":3,"e":"Manba ma’lumotni tekshirish imkonini beradi."},{"q":"Tayyor loyiha matnidagi kiritish xatolarini topish usuli qaysi?","o":["Drayver o‘rnatish","Defragmentatsiya","Shifrlash","Vizual tekshirish"],"a":3,"e":"Matnni ko‘z bilan solishtirish."},{"q":"Loyihaning to‘g‘ri bosqichlari tartibini tanlang.","o":["Taqdimot, maqsad, tekshirish, ma’lumot","Maqsad, ma’lumot to‘plash, tekshirish, rasmiylashtirish, taqdimot","Rasmiylashtirish, taqdimot, maqsad, tekshirish","Tekshirish, taqdimot, maqsad, ma’lumot"],"a":1,"e":"Taqdimot oxirida bo‘ladi."},{"q":"Taqdimot tayyorlash qaysi turdagi dasturda bajariladi?","o":["Amaliy dasturda","Apparat ta’minotda","Utilitda emas, ona platada","Drayverda"],"a":0,"e":"Taqdimot dasturi amaliy dastur."},{"q":"Loyiha tugagach nima qilinadi?","o":["Natija taqdim etilib, muhokama qilinadi","Barcha fayllar o‘chiriladi","Kompyuter qayta yig‘iladi","Manbalar yashiriladi"],"a":0,"e":"Taqdimot va muhokama yakuniy bosqich."},{"q":"Qaysi mulohaza to‘g‘ri?","o":["Faqat bitta manba yetarli va yetarli emas deb bo‘lmaydi","Loyihada olingan ma’lumotni tekshirish zarur","Internetdagi har bir ma’lumot to‘g‘ri","Tekshirish loyihada keraksiz"],"a":1,"e":"Ma’lumot sifati tekshiruv talab qiladi."},{"q":"Loyiha ishida nechta dasturdan foydalanish mumkin?","o":["Hech qaysisi","Vazifaga mos bir nechta","Faqat o‘yinlar","Faqat bitta"],"a":1,"e":"Vazifaga qarab dastur tanlanadi."}]},{"t":"11-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 1</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ma‘lumot, axborot va bilimlar bazasi. Ma‘lumot manbasi. Bevosita va bilvosita manbalardan ma‘lumot to‘plashning afzallik hamda kamchiliklari. Axborotning sifati</li><li>Kod berish, kodlash va shifrlash. Ma‘lumotlarni kodlashning afzallik va kamchiliklari. Simmetrik va asimmetrik shifrlash usullari.</li><li>Ma‘lumotlarning to‘g‘riligini tekshirish.</li><li>Vizual tekshirish va ma‘lumotlanri ikki marta kiritish.</li><li>Apparat ta‘minot. Ichki va tashqi qurilmalar</li><li>Xotira qurilmalari. Tizimli dasturiy ta‘minot. Drayverlar.</li><li>Amaliy dasturiy ta‘minot. Fotosuratni tahrirlash dasturiy ta‘minoti</li><li>Video tahrirlash dasturiy ta‘minoti. Veb sahifa ishlab chiqish dasturiy ta‘minoti</li><li>Foydalanuvchi interfeysi dizaynidagi boshqaruv elementlari. Utilit dasturlar. Buyurtma yoki tayyor dasturiy ta‘minot.</li><li>Loyiha (amaliy) ishi</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Video tahrirlashda keraksiz qismni olib tashlash qanday amal?","o":["Drayver o‘rnatish","Kodlash","Kesish","Ikki marta kiritish"],"a":2,"e":"Kesish keraksiz parchani chiqarib tashlaydi."},{"q":"Bilvosita manbadan foydalanishning asosiy afzalligi qaysi?","o":["Ma’lumot faqat bizga tegishli bo‘lishi","Ma’lumotni tekshirish shart emasligi","Ma’lumotga tez va arzon yetib borish","Ma’lumot albatta eng yangi bo‘lishi"],"a":2,"e":"Tayyor ma’lumot tez topiladi, ammo uning ishonchliligini tekshirish kerak."},{"q":"Flesh-xotira qaysi guruhga kiradi?","o":["Kiritish qurilmasi","Operativ xotira","Drayver","Tashqi doimiy xotira"],"a":3,"e":"Flesh-xotira ma’lumotni uzoq saqlaydi va ko‘chirib olib yuriladi."},{"q":"Loyihani bajarishda birinchi qadam nima?","o":["Manbalarsiz xulosa chiqarish","Mavzu va maqsadni aniqlash","Natijani taqdim etish","Faylni o‘chirish"],"a":1,"e":"Reja avval maqsaddan boshlanadi."},{"q":"Quyidagilardan qaysi biri kiritish qurilmasi?","o":["Printer","Monitor","Skaner","Karnay"],"a":2,"e":"Skaner tasvirni kompyuterga kiritadi."},{"q":"Ma’lumotlar qayta ishlanib, ma’no va kontekst olganda nima hosil bo‘ladi?","o":["Axborot","Xom ma’lumot","Kod","Shifr"],"a":0,"e":"Kontekst bilan boyitilgan ma’lumot axborot deyiladi."},{"q":"Drayver nima?","o":["Tashqi xotira turi","Antivirus dasturi","Qurilma va operatsion tizim o‘rtasidagi bog‘lovchi dastur","Matn muharriri"],"a":2,"e":"Drayver qurilmani boshqarishni ta’minlaydi."},{"q":"Loyihaning to‘g‘ri bosqichlari tartibini tanlang.","o":["Taqdimot, maqsad, tekshirish, ma’lumot","Maqsad, ma’lumot to‘plash, tekshirish, rasmiylashtirish, taqdimot","Rasmiylashtirish, taqdimot, maqsad, tekshirish","Tekshirish, taqdimot, maqsad, ma’lumot"],"a":1,"e":"Taqdimot oxirida bo‘ladi."},{"q":"Parol yaratishda “parolni takrorlang” maydoni qaysi usulga misol?","o":["Vizual tekshirishga","Arxivlashga","Shifrlashga","Ikki marta kiritishga"],"a":3,"e":"Ikkala kiritilgan parol solishtiriladi."},{"q":"Tayyor tanlovlar ro‘yxatidan qiymat tanlash uchun qaysi element ishlatiladi?","o":["Radio tugma emas, rasm","Sarlavha","Ochiladigan ro‘yxat","Matn maydoni"],"a":2,"e":"Ochiladigan ro‘yxatda tayyor qiymatlar bo‘ladi."},{"q":"Fotomuharrirda “qatlamlar” nima uchun kerak?","o":["Faylni arxivlash uchun","Ekran o‘lchamini o‘zgartirish uchun","Parol o‘rnatish uchun","Rasm elementlarini alohida tahrirlash uchun"],"a":3,"e":"Qatlamlar elementlarni bir-biriga ta’sir qilmasdan tahrirlash imkonini beradi."},{"q":"Majburiy maydon bo‘sh qolmasligini tekshirish qanday ataladi?","o":["Mavjudlik tekshiruvi","Format tekshiruvi","Tur tekshiruvi","Diapazon tekshiruvi"],"a":0,"e":"Mavjudlik tekshiruvi bo‘sh maydonlarni rad etadi."},{"q":"Asimmetrik shifrlashda qaysi kalitlar ishlatiladi?","o":["Faqat parol","Faqat ochiq kalit","Faqat yopiq kalit","Ochiq va yopiq kalit"],"a":3,"e":"Ochiq kalit shifrlaydi, yopiq kalit ochadi."},{"q":"Baho maydoniga 2 dan 5 gacha son kiritish talabi qaysi tekshiruvga misol?","o":["Uzunlik tekshiruvi","Diapazon tekshiruvi","Format tekshiruvi","Mavjudlik tekshiruvi"],"a":1,"e":"Qiymat 2 dan 5 gacha oraliqda bo‘lishi kerak."},{"q":"Ikki kiritish natijasi mos kelmasa, nimani anglatadi?","o":["Kamida bitta kiritishda xato bor","Kompyuter virus yuqtirgan","Ma’lumot albatta to‘g‘ri","Fayl shikastlangan"],"a":0,"e":"Farq xato mavjudligini ko‘rsatadi."},{"q":"Ikki lavha orasidagi silliq almashinuv nima deyiladi?","o":["O‘tish effekti","Arxivlash","Retush","Kodlash"],"a":0,"e":"O‘tish effekti sahnalarni bog‘laydi."},{"q":"Fotomuharrirda rasmning keraksiz qismini olib tashlash qanday amal?","o":["Nusxalash","Kesish","Arxivlash","Shifrlash"],"a":1,"e":"Kesish rasm chegarasini o‘zgartiradi."},{"q":"Simmetrik shifrlashda nechta kalit ishlatiladi?","o":["Har bir harf uchun yangi kalit va parol","Ikkita turli kalit","Kalit ishlatilmaydi","Shifrlash va ochish uchun bitta umumiy kalit"],"a":3,"e":"Simmetrik usulda ikkala amalga ham bir xil kalit xizmat qiladi."},{"q":"Quyidagilardan qaysi biri chiqarish qurilmasi?","o":["Sichqoncha","Mikrofon","Monitor","Klaviatura"],"a":2,"e":"Monitor axborotni ekranga chiqaradi."},{"q":"Quyidagilardan qaysi biri utilit?","o":["Rasm muharriri","Taqdimot dasturi","Elektron jadval","Arxivator"],"a":3,"e":"Arxivator fayllarni siqadi."}]},{"t":"12-dars. Sensorlar. Harakat va bosim sensorlari, Namlik, harorat va yorug‘lik sensorlari","lesson":"<p><b>Sensor</b> (datchik) — fizik kattalikni (harakat, bosim, harorat, yorug‘lik) o‘lchab, elektr signaliga aylantiruvchi qurilma. Sensorlar kompyuter, telefon va avtomatik tizimlarda qo‘llanadi.</p>\n<h4>Sensor turlari</h4>\n<ul><li><b>Harakat sensori</b> — yaqin atrofdagi harakatni sezadi. Eshik avtomatik ochilishi, xavfsizlik signalizatsiyasi va ko‘cha chiroqlarini yoqishda ishlatiladi.</li>\n<li><b>Bosim sensori</b> — bosim kuchini o‘lchaydi. Shinadagi havo bosimini nazorat qilishda, sensorli tugmalarda ishlatiladi.</li>\n<li><b>Namlik sensori</b> — havo yoki tuproq namligini o‘lchaydi. Issiqxonada sug‘orishni boshqarishda qo‘llanadi.</li>\n<li><b>Harorat sensori</b> — haroratni o‘lchaydi. Konditsioner va termometrlarda bor.</li>\n<li><b>Yorug‘lik sensori</b> — yorug‘lik darajasini sezadi. Telefon ekranining yorqinligi avtomatik o‘zgarishi shunga asoslangan.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Do‘kon eshigi oldiga kelsangiz, harakat sensori signal beradi va eshik o‘zi ochiladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Sensor tashqi kattalikni signalga aylantiradi.</li><li>Har bir sensor muayyan kattalikni o‘lchaydi.</li><li>Sensorlar avtomatlashtirishda keng ishlatiladi.</li></ul>","quiz":[{"q":"Sensor nima?","o":["Ma’lumotlarni shifrlash usuli","Fizik kattalikni o‘lchab, signalga aylantiruvchi qurilma","Dasturlash tili","Xotira turi"],"a":1,"e":"Sensor tashqi ta’sirni signalga aylantiradi."},{"q":"Eshik oldiga kelganda avtomatik ochilishi qaysi sensorga asoslangan?","o":["Namlik sensori","Bosim sensori","Harorat sensori","Harakat sensori"],"a":3,"e":"Harakat sensori yaqinlashishni seza oladi."},{"q":"Issiqxonada tuproq namligini o‘lchash uchun qaysi sensor kerak?","o":["Harakat sensori","Tovush kartasi","Yorug‘lik sensori","Namlik sensori"],"a":3,"e":"Namlik sensori namlikni o‘lchaydi."},{"q":"Konditsioner xona haroratini qaysi sensor orqali biladi?","o":["Harorat sensori","Harakat sensori","Yorug‘lik sensori","Bosim sensori"],"a":0,"e":"Harorat sensori issiqlik darajasini o‘lchaydi."},{"q":"Telefon ekrani yorqinligining avtomatik o‘zgarishi qaysi sensorga bog‘liq?","o":["Harorat sensori","Yorug‘lik sensori","Namlik sensori","Bosim sensori"],"a":1,"e":"Atrof yorug‘ligiga qarab yorqinlik moslanadi."},{"q":"Shinadagi havo bosimini nazorat qilish uchun qaysi sensor kerak?","o":["Harakat sensori","Namlik sensori","Bosim sensori","Yorug‘lik sensori"],"a":2,"e":"Bosim sensori bosim kuchini o‘lchaydi."},{"q":"Quyidagilardan qaysi biri to‘g‘ri?","o":["Har bir sensor muayyan kattalikni o‘lchaydi","Sensor faqat kompyuterda ishlaydi","Sensor dasturiy ta’minotdir","Bitta sensor hamma kattalikni o‘lchaydi"],"a":0,"e":"Sensorlar mutaxassislashgan."},{"q":"Ko‘cha chirog‘i yaqinlashgan odamga yonishi qaysi sensor hisobiga?","o":["Harakat sensori","Harorat sensori","Namlik sensori","Bosim sensori"],"a":0,"e":"Harakatni sezish uchun harakat sensori."},{"q":"Sensorlar qaysi sohada keng qo‘llanadi?","o":["Avtomatlashtirish va xavfsizlik tizimlarida","Faqat matn yozishda","Faqat chop etishda","Faqat arxivlashda"],"a":0,"e":"Ular avtomatik boshqaruvda ishlatiladi."},{"q":"Sensor qanday signal chiqaradi?","o":["Elektr signali","Dasturiy kod fayli","Faqat qog‘ozdagi yozuv","Parol"],"a":0,"e":"Sensor o‘lchovni elektr signaliga aylantiradi."}]},{"t":"13-dars. Elektron xavfsizlik tushunchasi.","lesson":"<p><b>Elektron xavfsizlik</b> — kompyuter, tarmoq va ularda saqlanadigan ma’lumotlarni ruxsatsiz kirish, o‘g‘irlash va buzishdan himoya qilish.</p>\n<h4>Xavfsizlikning uch asosiy tamoyili</h4>\n<ul><li><b>Maxfiylik</b> — ma’lumotni faqat ruxsati borlar ko‘ra oladi;</li><li><b>Butunlik</b> — ma’lumot ruxsatsiz o‘zgartirilmaydi;</li><li><b>Mavjudlik</b> — kerak paytda ma’lumotdan foydalanish mumkin.</li></ul>\n<h4>Asosiy himoya choralari</h4>\n<ul><li>Murakkab va takrorlanmaydigan parollar;</li><li>Antivirus va operatsion tizimni yangilab turish;</li><li>Zaxira nusxa olish;</li><li>Ma’lumotni shifrlash;</li><li>Noma’lum havola va fayllarni ochmaslik;</li><li>Brandmauer (firewall) dan foydalanish.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Kuchli parol harflar, raqamlar va belgilardan iborat bo‘ladi va tug‘ilgan kun kabi oson topiladigan ma’lumotni o‘z ichiga olmaydi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Xavfsizlik: maxfiylik, butunlik, mavjudlik.</li><li>Parolni hech kimga bermang.</li><li>Zaxira nusxa ma’lumot yo‘qolishidan asraydi.</li></ul>","quiz":[{"q":"Elektron xavfsizlik nima?","o":["Internet tezligini oshirish","Ma’lumot va tizimlarni ruxsatsiz kirish va buzilishdan himoya qilish","Kompyuterni tezlashtirish","Rasmlarni tahrirlash"],"a":1,"e":"Bu himoya majmuasi."},{"q":"“Maxfiylik” tamoyili nimani anglatadi?","o":["Ma’lumot hech qachon o‘zgarmaydi","Ma’lumot hammaga ochiq bo‘ladi","Ma’lumotni faqat ruxsati borlar ko‘ra oladi","Ma’lumot faqat qog‘ozda saqlanadi"],"a":2,"e":"Maxfiylik ruxsatsiz ko‘rishni oldini oladi."},{"q":"“Butunlik” tamoyili nimani anglatadi?","o":["Ma’lumot ruxsatsiz o‘zgartirilmaydi","Ma’lumot yashirinadi","Ma’lumot tez uzatiladi","Ma’lumot siqiladi"],"a":0,"e":"Butunlik o‘zgarishdan himoya."},{"q":"Quyidagilardan qaysi parol kuchliroq?","o":["tug‘ilgan kuningiz","K7#mP2x!qL9","12345678","parol"],"a":1,"e":"Murakkab belgilar kombinatsiyasi kuchli."},{"q":"Zaxira nusxa olish nima uchun kerak?","o":["Ma’lumot yo‘qolsa, uni tiklash uchun","Kompyuterni sovutish uchun","Rasm sifatini oshirish uchun","Parolni yashirish uchun"],"a":0,"e":"Zaxira ma’lumotni tiklash imkonini beradi."},{"q":"Noma’lum jo‘natuvchidan kelgan havolani bosishdan oldin nima qilish kerak?","o":["Parolni yozib berish","Hammaga yuborish","Darhol bosish","Ehtiyot bo‘lib, ochmaslik yoki tekshirish"],"a":3,"e":"Noma’lum havola xavfli bo‘lishi mumkin."},{"q":"Brandmauer (firewall) nima vazifani bajaradi?","o":["Rasmni tahrirlaydi","Matnni chop etadi","Xotirani kengaytiradi","Tarmoq orqali ruxsatsiz kirishni cheklaydi"],"a":3,"e":"Firewall tarmoq trafigini nazorat qiladi."},{"q":"Bitta parolni barcha saytlarda ishlatish haqida qaysi fikr to‘g‘ri?","o":["Parol ahamiyatsiz","Faqat bolalar uchun xavfli","Xavfli, bittasi buzilsa hammasi xavf ostida qoladi","Eng xavfsiz usul"],"a":2,"e":"Takroriy parol zanjirli xavf tug‘diradi."},{"q":"“Mavjudlik” tamoyili nimani anglatadi?","o":["Ma’lumotning o‘chirilishi","Kerak paytda ma’lumotdan foydalanish mumkin bo‘lishi","Ma’lumotning doim shifrlanishi","Faqat bitta nusxada saqlanishi"],"a":1,"e":"Mavjudlik ma’lumotga kirish imkonini kafolatlaydi."},{"q":"Antivirus va tizimni yangilab turish nima uchun muhim?","o":["Faqat tezlik uchun emas, dizayn uchun","Parolni o‘chirish uchun","Yangi tahdidlardan himoya qilish uchun","Kompyuter rangini o‘zgartirish uchun"],"a":2,"e":"Yangilanishlar zaifliklarni yopadi."}]},{"t":"14-dars. Phishing, Pharming, Vishing, Troyan, Worm, Spyware, Rootkit, Adware, Ransomware tushunchalari va xavfsizlikni ta‘minlash.","lesson":"<p>Zararli dasturlar va firibgarlik usullari ma’lumotlaringizga zarar yetkazishi mumkin. Asosiy tushunchalar:</p>\n<ul><li><b>Phishing</b> — soxta xat yoki sayt orqali foydalanuvchining parol va karta ma’lumotlarini aldab olish;</li>\n<li><b>Pharming</b> — foydalanuvchini to‘g‘ri manzil kiritganda ham soxta saytga yo‘naltirish;</li>\n<li><b>Vishing</b> — telefon qo‘ng‘irog‘i orqali aldab ma’lumot olish;</li>\n<li><b>Troyan</b> — foydali dastur qiyofasidagi zararli dastur;</li>\n<li><b>Worm (qurt)</b> — tarmoq orqali o‘zi tarqaladigan zararli dastur;</li>\n<li><b>Spyware</b> — foydalanuvchi ustidan yashirincha josuslik qiladi;</li>\n<li><b>Rootkit</b> — zararli dastur izlarini tizimda yashiradi;</li>\n<li><b>Adware</b> — majburan reklama ko‘rsatadi;</li>\n<li><b>Ransomware</b> — ma’lumotlarni shifrlab, qaytarish uchun to‘lov talab qiladi.</li></ul>\n<h4>Himoyalanish</h4>\n<ul><li>Antivirus va yangilanishlarni o‘rnatish;</li><li>Noma’lum xat va havolalarni ochmaslik;</li><li>Rasmiy manbalardan dastur yuklash;</li><li>Zaxira nusxa saqlash;</li><li>Telefonda parol va kodni aytmaslik.</li></ul>\n<h4>Eslab qoling</h4>\n<ul><li>Troyan o‘zini foydali dastur qilib ko‘rsatadi, worm o‘zi tarqaladi.</li><li>Ransomware ma’lumotni garovga oladi.</li></ul>","quiz":[{"q":"Soxta xat yoki sayt orqali parol va karta ma’lumotlarini aldab olish nima deyiladi?","o":["Rootkit","Adware","Phishing","Worm"],"a":2,"e":"Phishing aldash orqali ma’lumot olishdir."},{"q":"Telefon qo‘ng‘irog‘i orqali aldab ma’lumot olish nima deyiladi?","o":["Spyware","Vishing","Ransomware","Pharming"],"a":1,"e":"Vishing — ovoz orqali phishing."},{"q":"To‘g‘ri manzil kiritilsa ham foydalanuvchini soxta saytga yo‘naltirish nima?","o":["Adware","Pharming","Worm","Troyan"],"a":1,"e":"Pharming manzilni yo‘naltirishga asoslangan."},{"q":"Foydali dastur qiyofasidagi zararli dastur qaysi?","o":["Rootkit","Troyan","Adware","Worm"],"a":1,"e":"Troyan o‘zini yaxshi dastur qilib ko‘rsatadi."},{"q":"Tarmoq orqali o‘zi tarqaladigan zararli dastur qaysi?","o":["Troyan","Worm","Spyware","Adware"],"a":1,"e":"Worm foydalanuvchi ishtirokisiz tarqaladi."},{"q":"Foydalanuvchi ustidan yashirincha josuslik qiladigan dastur qaysi?","o":["Spyware","Adware","Ransomware","Worm"],"a":0,"e":"Spyware ma’lumot yig‘adi."},{"q":"Ma’lumotni shifrlab, qaytarish uchun to‘lov talab qiladigan dastur qaysi?","o":["Phishing","Ransomware","Spyware","Adware"],"a":1,"e":"Ransomware ma’lumotni garovga oladi."},{"q":"Majburan reklama ko‘rsatadigan dastur qaysi?","o":["Pharming","Vishing","Rootkit","Adware"],"a":3,"e":"Adware reklama chiqaradi."},{"q":"Bank xodimi deb tanishtirgan notanish odam telefonda karta kodini so‘radi. Nima qilish kerak?","o":["Kodni SMS orqali yuborish","Kartani do‘stiga berish","Kodni aytish","Kodni aytmay, qo‘ng‘iroqni tugatib, bankka o‘zi murojaat qilish"],"a":3,"e":"Bu vishing belgisi."},{"q":"Ransomware bilan zarar ko‘rmaslikning eng yaxshi choralaridan biri qaysi?","o":["Parolni oshkor qilish","Zaxira nusxa saqlash","Antivirusni o‘chirish","Barcha xatlarni ochish"],"a":1,"e":"Zaxira bo‘lsa, ma’lumot tiklanadi."}]},{"t":"15-dars. Salomatlik va xavfsizlik.","lesson":"<p>Kompyuterda uzoq ishlash salomatlikka ta’sir qilishi mumkin: ko‘z charchaydi, bo‘yin va bel og‘riydi, qo‘llar zo‘riqadi. Xavfsiz ish joyini to‘g‘ri tashkil qilish va ish tartibiga amal qilish bu muammolarning oldini oladi.</p>\n<h4>Salomatlik xavflari</h4>\n<ul><li>Ko‘zning charchashi va quruqlashishi.</li><li>Bo‘yin, bel va yelkadagi og‘riqlar noto‘g‘ri o‘tirishdan kelib chiqadi.</li><li>Qo‘l panjalarining zo‘riqishi klaviatura va sichqoncha bilan uzoq ishlashdan paydo bo‘ladi.</li><li>Harakatsizlik ortiqcha vazn va umumiy holsizlikka olib keladi.</li></ul>\n<h4>Xavfsizlik choralari</h4>\n<ul><li>Monitor ko‘z balandligida, ko‘zdan taxminan qo‘l uzunligicha masofada bo‘lsin.</li><li>Muntazam tanaffus qilib, ko‘z va tana mashqlarini bajaring.</li><li>Simlar yo‘lga yoyilmasin, rozetkalar ortiqcha yuklanmasin.</li><li>Elektr jihozlarini nam qo‘l bilan ushlamang.</li><li>Xona yaxshi yoritilgan va shamollatilgan bo‘lsin.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab kompyuter xonasida o‘quvchi har 30-40 daqiqada ekrandan ko‘zini uzib, uzoqqa qaraydi va qisqa mashq qiladi. Bu ko‘z va tananing charchashini kamaytiradi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Kompyuter oldida to‘g‘ri o‘tirish muhim.</li><li>Ish davomida tanaffus qilish kerak.</li><li>Elektr xavfsizligi qoidalariga amal qilish shart.</li></ul>","quiz":[{"q":"Kompyuterda uzoq ishlashdan ko‘z uchun qanday xavf bor?","o":["Ko‘rishning birdan yaxshilanishi","Hech qanday ta’sir yo‘q","Ko‘zning charchashi","Ko‘zning ranglari o‘zgarishi"],"a":2,"e":"Uzoq ekranga qarash ko‘zni charchatadi."},{"q":"Monitor qanday joylashtirilishi kerak?","o":["Ko‘zdan juda yaqin va yuqorida","Yon tomonda, burchak ostida","Ko‘z balandligida, mos masofada","Pastda, stol ostida"],"a":2,"e":"To‘g‘ri joylashuv bo‘yin va ko‘zni asraydi."},{"q":"Bel va bo‘yin og‘rig‘ining asosiy sababi nima?","o":["Ekran rangi","Noto‘g‘ri o‘tirish holati","Internet tezligi","Klaviatura tovushi"],"a":1,"e":"Noto‘g‘ri o‘tirish umurtqa va mushaklarga yuk beradi."},{"q":"Tanaffus nima uchun kerak?","o":["Dasturni yangilash uchun","Kompyuterni sovutish uchun","Fayllarni arxivlash uchun","Ko‘z va tanani dam oldirish uchun"],"a":3,"e":"Muntazam tanaffus charchoqni kamaytiradi."},{"q":"Elektr xavfsizligi qoidasi qaysi?","o":["Simlarni yo‘lga yoyib qo‘yish","Buzilgan simdan foydalanish","Rozetkaga ko‘p jihozni ulash","Elektr jihozlarini nam qo‘l bilan ushlamaslik"],"a":3,"e":"Nam qo‘l bilan ushlash tok urishiga olib kelishi mumkin."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Tanaffussiz ishlash ma’qul","Simlar yo‘lda tursa, hech narsa bo‘lmaydi","Xona yaxshi yoritilgan bo‘lishi kerak","Qorong‘i xonada ishlash ko‘z uchun foydali"],"a":2,"e":"Yoritilish ko‘z zo‘riqishini kamaytiradi."},{"q":"Vaziyat: qo‘lingiz panjasi uzoq yozishdan charchadi. Nima qilasiz?","o":["Klaviaturani almashtirmay, hech narsa qilmayman","Tezroq yozishda davom etaman","Ekran yorqinligini oshiraman","Tanaffus qilib, qo‘l mashqlarini bajaraman"],"a":3,"e":"Dam va mashq zo‘riqishning oldini oladi."},{"q":"Harakatsizlik nimaga olib kelishi mumkin?","o":["Holsizlik va ortiqcha vaznga","Xotira hajmi oshishiga","Ko‘rish kuchi oshishiga","Internet tezlashishiga"],"a":0,"e":"Kam harakat qilish salomatlikka zarar."},{"q":"Xonaning shamollatilishi nima uchun muhim?","o":["Toza havo charchoqni kamaytiradi","Kompyuter nomi o‘zgarishi uchun","Tarmoq ishlashi uchun","Fayllar o‘chmasligi uchun"],"a":0,"e":"Toza havo diqqat va holatga yaxshi ta’sir qiladi."},{"q":"Ko‘z charchoqini kamaytirish uchun nima tavsiya etiladi?","o":["Ekrandan uzilib, uzoqqa qarash","Yorqinlikni maksimumga qo‘yish","Ekranga yaqinroq qarash","Ko‘zni yumib, uzoq ishlash"],"a":0,"e":"Uzoqqa qarash ko‘z mushaklarini bo‘shashtiradi."}]},{"t":"16-dars. Raqamli tengsizlik tushunchasi va sabablari, Sanoati rivojlangan va rivojlanmagan hududlar, Ijtimoiy-iqtisodiy guruhlar.","lesson":"<p>Raqamli tengsizlik — axborot-kommunikatsiya texnologiyalaridan foydalanish imkoniyatlaridagi farqdir. Ba’zi odamlar va hududlar kompyuter, internet va raqamli ko‘nikmalarga ega, boshqalari esa ega emas.</p>\n<h4>Raqamli tengsizlik sabablari</h4>\n<ul><li>Iqtisodiy: qurilma va internet narxi yuqoriligi.</li><li>Infratuzilma: tarmoq qamrovining yetarli emasligi, ayniqsa chekka hududlarda.</li><li>Ta’lim: raqamli savodxonlikning pastligi.</li><li>Yosh, nogironlik va til to‘siqlari ham ta’sir qiladi.</li><li>Bu omillar birgalikda odamlarning bilim va daromadiga ham ta’sir ko‘rsatadi.</li></ul>\n<h4>Hududlar va guruhlar</h4>\n<ul><li>Sanoati rivojlangan davlatlarda internet va texnologiya keng tarqalgan.</li><li>Rivojlanayotgan hududlarda foydalanish imkoniyati cheklangan.</li><li>Shahar va qishloq o‘rtasida ham farq bor.</li><li>Ijtimoiy-iqtisodiy guruhlar daromadi, ta’lim darajasi va kasbiga ko‘ra ajratiladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Qishloq maktabida internet sekin yoki umuman yo‘q bo‘lsa, o‘quvchilar onlayn ta’lim resurslaridan foydalana olmaydi. Bu raqamli tengsizlikka misol.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Raqamli tengsizlik imkoniyatlar farqidir.</li><li>Sabablari iqtisodiy, infratuzilma va ta’lim bilan bog‘liq.</li><li>Farqni kamaytirish uchun tarmoq va savodxonlikni rivojlantirish kerak.</li></ul>","quiz":[{"q":"Raqamli tengsizlik nima?","o":["Faqat dastur narxi","Texnologiyadan foydalanish imkoniyatidagi farq","Kompyuterlar sonining kamayishi","Internet tezligi birligi"],"a":1,"e":"Bu tengsizlik imkoniyatlar bilan bog‘liq."},{"q":"Raqamli tengsizlik sababi qaysi?","o":["Klaviatura tugmalari soni","Ekran rangining qora bo‘lishi","Fayl kengaytmasi","Internet va qurilmalar narxining yuqoriligi"],"a":3,"e":"Iqtisodiy imkoniyat muhim sababdir."},{"q":"Infratuzilma yetishmasligi nimani anglatadi?","o":["Dasturlarning ko‘pligini","Ekranlarning kattaligini","Tarmoq va aloqa vositalarining yetarli emasligini","Kompyuterlarning haddan ortiq tezligini"],"a":2,"e":"Infratuzilma aloqa tarmoqlarini o‘z ichiga oladi."},{"q":"Raqamli savodxonlik nima?","o":["Faqat dastur yozish","Faqat qurilma sotib olish","Faqat rasm chizish","Raqamli vositalardan foydalana olish ko‘nikmasi"],"a":3,"e":"Bu texnologiyadan samarali foydalanish qobiliyati."},{"q":"Qaysi misol raqamli tengsizlikka kiradi?","o":["Chekka qishloqda internetning yo‘qligi","Yangi dastur chiqishi","Faylning arxivlanishi","Kompyuterning yangilanishi"],"a":0,"e":"Imkoniyat yo‘qligi tengsizlikni ko‘rsatadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Shahar va qishloq o‘rtasida ham raqamli farq bo‘lishi mumkin","Tengsizlik faqat davlatlar orasida bo‘ladi","Tengsizlik bo‘lmaydi","Tengsizlik faqat yoshga bog‘liq"],"a":0,"e":"Farq turli darajada mavjud."},{"q":"Ijtimoiy-iqtisodiy guruhlar nimaga qarab ajratiladi?","o":["Soch rangiga qarab","Fayl hajmiga qarab","Daromad, ta’lim va kasbga qarab","Ekran o‘lchamiga qarab"],"a":2,"e":"Ijtimoiy-iqtisodiy holat shu ko‘rsatkichlarga bog‘liq."},{"q":"Vaziyat: ba’zi oilalar kompyuter sotib ololmaydi. Bu nimaga misol?","o":["Iqtisodiy sababli raqamli tengsizlikka","Fayl formatiga","Dastur xatosiga","Tarmoq jarayoniga"],"a":0,"e":"Qurilmaga erisha olmaslik iqtisodiy sabab."},{"q":"Tengsizlikni kamaytirishning yo‘li qaysi?","o":["Tarmoq qamrovini va raqamli savodxonlikni oshirish","Ta’limni qisqartirish","Internetni cheklash","Qurilmalar narxini oshirish"],"a":0,"e":"Imkoniyatni kengaytirish farqni kamaytiradi."},{"q":"Sanoati rivojlangan davlatlarda holat odatda qanday?","o":["Hech narsa farq qilmaydi","Kompyuterlar taqiqlangan","Texnologiyadan foydalanish keng tarqalgan","Internet umuman yo‘q"],"a":2,"e":"Rivojlangan davlatlarda foydalanish darajasi yuqoriroq."}]},{"t":"17-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 2</b> quyidagi darslarni qamrab oladi:</p><ul><li>Sensorlar. Harakat va bosim sensorlari, Namlik, harorat va yorug‘lik sensorlari</li><li>Elektron xavfsizlik tushunchasi.</li><li>Phishing, Pharming, Vishing, Troyan, Worm, Spyware, Rootkit, Adware, Ransomware tushunchalari va xavfsizlikni ta‘minlash.</li><li>Salomatlik va xavfsizlik.</li><li>Raqamli tengsizlik tushunchasi va sabablari, Sanoati rivojlangan va rivojlanmagan hududlar, Ijtimoiy-iqtisodiy guruhlar.</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Elektr xavfsizligi qoidasi qaysi?","o":["Simlarni yo‘lga yoyib qo‘yish","Buzilgan simdan foydalanish","Rozetkaga ko‘p jihozni ulash","Elektr jihozlarini nam qo‘l bilan ushlamaslik"],"a":3,"e":"Nam qo‘l bilan ushlash tok urishiga olib kelishi mumkin."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Tanaffussiz ishlash ma’qul","Simlar yo‘lda tursa, hech narsa bo‘lmaydi","Xona yaxshi yoritilgan bo‘lishi kerak","Qorong‘i xonada ishlash ko‘z uchun foydali"],"a":2,"e":"Yoritilish ko‘z zo‘riqishini kamaytiradi."},{"q":"Sensor qanday signal chiqaradi?","o":["Elektr signali","Dasturiy kod fayli","Faqat qog‘ozdagi yozuv","Parol"],"a":0,"e":"Sensor o‘lchovni elektr signaliga aylantiradi."},{"q":"Tengsizlikni kamaytirishning yo‘li qaysi?","o":["Tarmoq qamrovini va raqamli savodxonlikni oshirish","Ta’limni qisqartirish","Internetni cheklash","Qurilmalar narxini oshirish"],"a":0,"e":"Imkoniyatni kengaytirish farqni kamaytiradi."},{"q":"To‘g‘ri manzil kiritilsa ham foydalanuvchini soxta saytga yo‘naltirish nima?","o":["Adware","Pharming","Worm","Troyan"],"a":1,"e":"Pharming manzilni yo‘naltirishga asoslangan."},{"q":"Eshik oldiga kelganda avtomatik ochilishi qaysi sensorga asoslangan?","o":["Namlik sensori","Bosim sensori","Harorat sensori","Harakat sensori"],"a":3,"e":"Harakat sensori yaqinlashishni seza oladi."},{"q":"“Butunlik” tamoyili nimani anglatadi?","o":["Ma’lumot ruxsatsiz o‘zgartirilmaydi","Ma’lumot yashirinadi","Ma’lumot tez uzatiladi","Ma’lumot siqiladi"],"a":0,"e":"Butunlik o‘zgarishdan himoya."},{"q":"Shinadagi havo bosimini nazorat qilish uchun qaysi sensor kerak?","o":["Harakat sensori","Namlik sensori","Bosim sensori","Yorug‘lik sensori"],"a":2,"e":"Bosim sensori bosim kuchini o‘lchaydi."},{"q":"Bitta parolni barcha saytlarda ishlatish haqida qaysi fikr to‘g‘ri?","o":["Parol ahamiyatsiz","Faqat bolalar uchun xavfli","Xavfli, bittasi buzilsa hammasi xavf ostida qoladi","Eng xavfsiz usul"],"a":2,"e":"Takroriy parol zanjirli xavf tug‘diradi."},{"q":"Ma’lumotni shifrlab, qaytarish uchun to‘lov talab qiladigan dastur qaysi?","o":["Phishing","Ransomware","Spyware","Adware"],"a":1,"e":"Ransomware ma’lumotni garovga oladi."},{"q":"Ransomware bilan zarar ko‘rmaslikning eng yaxshi choralaridan biri qaysi?","o":["Parolni oshkor qilish","Zaxira nusxa saqlash","Antivirusni o‘chirish","Barcha xatlarni ochish"],"a":1,"e":"Zaxira bo‘lsa, ma’lumot tiklanadi."},{"q":"Infratuzilma yetishmasligi nimani anglatadi?","o":["Dasturlarning ko‘pligini","Ekranlarning kattaligini","Tarmoq va aloqa vositalarining yetarli emasligini","Kompyuterlarning haddan ortiq tezligini"],"a":2,"e":"Infratuzilma aloqa tarmoqlarini o‘z ichiga oladi."},{"q":"Majburan reklama ko‘rsatadigan dastur qaysi?","o":["Pharming","Vishing","Rootkit","Adware"],"a":3,"e":"Adware reklama chiqaradi."},{"q":"Elektron xavfsizlik nima?","o":["Internet tezligini oshirish","Ma’lumot va tizimlarni ruxsatsiz kirish va buzilishdan himoya qilish","Kompyuterni tezlashtirish","Rasmlarni tahrirlash"],"a":1,"e":"Bu himoya majmuasi."},{"q":"Raqamli tengsizlik nima?","o":["Faqat dastur narxi","Texnologiyadan foydalanish imkoniyatidagi farq","Kompyuterlar sonining kamayishi","Internet tezligi birligi"],"a":1,"e":"Bu tengsizlik imkoniyatlar bilan bog‘liq."},{"q":"Monitor qanday joylashtirilishi kerak?","o":["Ko‘zdan juda yaqin va yuqorida","Yon tomonda, burchak ostida","Ko‘z balandligida, mos masofada","Pastda, stol ostida"],"a":2,"e":"To‘g‘ri joylashuv bo‘yin va ko‘zni asraydi."},{"q":"Konditsioner xona haroratini qaysi sensor orqali biladi?","o":["Harorat sensori","Harakat sensori","Yorug‘lik sensori","Bosim sensori"],"a":0,"e":"Harorat sensori issiqlik darajasini o‘lchaydi."},{"q":"Kompyuterda uzoq ishlashdan ko‘z uchun qanday xavf bor?","o":["Ko‘rishning birdan yaxshilanishi","Hech qanday ta’sir yo‘q","Ko‘zning charchashi","Ko‘zning ranglari o‘zgarishi"],"a":2,"e":"Uzoq ekranga qarash ko‘zni charchatadi."},{"q":"Quyidagilardan qaysi parol kuchliroq?","o":["tug‘ilgan kuningiz","K7#mP2x!qL9","12345678","parol"],"a":1,"e":"Murakkab belgilar kombinatsiyasi kuchli."},{"q":"Ijtimoiy-iqtisodiy guruhlar nimaga qarab ajratiladi?","o":["Soch rangiga qarab","Fayl hajmiga qarab","Daromad, ta’lim va kasbga qarab","Ekran o‘lchamiga qarab"],"a":2,"e":"Ijtimoiy-iqtisodiy holat shu ko‘rsatkichlarga bog‘liq."}]},{"t":"18-dars. Samarasi yuqori va past bo‘lgan texnologiyalar. Turli davlatlardagi holatlarni o‘rganish","lesson":"<p>Texnologiyalar samaradorligi turlicha bo‘lishi mumkin. Samarasi yuqori texnologiya kam resurs bilan ko‘p foyda beradi, past samarali texnologiya esa ko‘p xarajat qilib, kam natija beradi yoki yaxshi o‘zlashtirilmaydi.</p>\n<h4>Samaradorlikka ta’sir etuvchi omillar</h4>\n<ul><li>Texnologiyaning ehtiyojga mosligi.</li><li>Foydalanuvchilarning tayyorgarligi va o‘qitilishi.</li><li>Infratuzilma: elektr va internet mavjudligi.</li><li>Narx, ta’mirlash va qo‘llab-quvvatlash imkoniyati.</li></ul>\n<h4>Turli davlatlardagi holatlar</h4>\n<ul><li>Ba’zi davlatlarda raqamli xizmatlar davlat xizmatlarini tezlashtiradi.</li><li>Boshqa joylarda qurilmalar olingan, lekin o‘qitish yo‘qligi sabab foydalanilmaydi.</li><li>Natija texnologiyaning o‘ziga emas, uni joriy etish usuliga ham bog‘liq.</li><li>Yaxshi reja, mablag‘ va doimiy baholash texnologiya samarasini oshiradi.</li><li>Samarasiz texnologiyani o‘z vaqtida aniqlab, o‘zgartirish kerak.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktabga kompyuterlar keltirilgan, ammo o‘qituvchilar o‘qitilmagan va internet yo‘q. Texnologiya mavjud, lekin samarasi past bo‘ladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Samaradorlik joriy etish sifatiga bog‘liq.</li><li>Texnologiya ehtiyojga mos bo‘lishi kerak.</li><li>Foydalanuvchini o‘qitish muhim.</li></ul>","quiz":[{"q":"Samarasi yuqori texnologiya qanday bo‘ladi?","o":["Faqat qimmat bo‘ladi","Faqat murakkab bo‘ladi","Kam resurs bilan ko‘p foyda beradi","Ko‘p xarajat qilib, kam foyda beradi"],"a":2,"e":"Samaradorlik natijaning sarfga nisbatidir."},{"q":"Samaradorlikka qaysi omil ta’sir qiladi?","o":["Fayl sanasi","Foydalanuvchilarning tayyorgarligi","Papka nomi","Ekran rangi nomi"],"a":1,"e":"O‘qitilmagan foydalanuvchi texnologiyadan yaxshi foydalana olmaydi."},{"q":"Infratuzilma nimani o‘z ichiga oladi?","o":["Faqat rasmlarni","Faqat dastur nomlarini","Faqat ekran saqlagichni","Elektr va aloqa tarmog‘ini"],"a":3,"e":"Elektr va internet texnologiya ishlashi uchun kerak."},{"q":"Vaziyat: maktabga kompyuterlar berildi, lekin elektr yo‘q. Natija qanday bo‘ladi?","o":["Texnologiya samarasiz qoladi","Hech narsa o‘zgarmaydi, ishlayveradi","Samara juda yuqori bo‘ladi","Kompyuterlar o‘zi ishlaydi"],"a":0,"e":"Elektrsiz qurilma ishlamaydi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Texnologiyani o‘qitmasdan joriy qilish yaxshi","Texnologiya ehtiyojga mos bo‘lsa, samara oshadi","Qimmat texnologiya har doim samarali","Infratuzilma ahamiyatsiz"],"a":1,"e":"Moslik samarani oshiradi."},{"q":"Samarasi past texnologiyaga misol qaysi?","o":["Tez ishlaydigan xizmat","Ehtiyojga mos dastur","Yaxshi o‘qitilgan jamoa","Foydalanilmay turgan qurilmalar"],"a":3,"e":"Foydalanilmasa, samara bermaydi."},{"q":"Davlat xizmatlarini raqamlashtirish nimaga olib kelishi mumkin?","o":["Xizmatlarning to‘xtashiga","Faqat xarajat oshishiga","Aholining kamayishiga","Xizmatlarning tezlashishiga"],"a":3,"e":"Samarali joriy etish xizmatni tezlashtiradi."},{"q":"Texnologiyani qo‘llab-quvvatlash nimani bildiradi?","o":["Ta’mirlash va yordam ko‘rsatishni","Narxni oshirishni","Texnologiyani yo‘q qilishni","Faqat reklama qilishni"],"a":0,"e":"Qo‘llab-quvvatlash ishlashda davomiylikni beradi."},{"q":"Texnologiya samarasi nimaga bog‘liq?","o":["Faqat sotuvchiga","Faqat qurilma rangiga","Faqat nomiga","Joriy etish usuliga ham"],"a":3,"e":"Natija joriy etishga bog‘liq."},{"q":"Texnologiyani tanlashda birinchi nimaga e’tibor beriladi?","o":["Faqat nomiga","Ehtiyojga mosligiga","Faqat reklamasiga","Faqat tashqi ko‘rinishiga"],"a":1,"e":"Ehtiyojga mos texnologiya tanlanadi."}]},{"t":"19-dars. Tarmoq kompyuterlari. Lokal hududiy (Local area networks) va global hududiy tarmoq (Wide area networks).","lesson":"<p>Kompyuter tarmog‘i — o‘zaro ma’lumot almashish uchun bog‘langan kompyuterlar va qurilmalar to‘plami. Tarmoq resurslarni (printer, fayl, internet) birgalikda ishlatish imkonini beradi.</p>\n<h4>Tarmoq turlari</h4>\n<ul><li><b>LAN</b> (Local Area Network) — lokal tarmoq: xona, bino yoki maktab doirasida.</li><li><b>WAN</b> (Wide Area Network) — global hududiy tarmoq: shaharlar va davlatlarni bog‘laydi.</li><li>Eng katta WAN — Internet.</li></ul>\n<h4>Tarmoq afzalliklari</h4>\n<ul><li>Resurslarni (printer, fayl) birgalikda ishlatish.</li><li>Ma’lumotlarni tez almashish.</li><li>Markazlashtirilgan zaxiralash va boshqarish.</li></ul>\n<h4>Tarmoq qurilmalari</h4>\n<ul><li>Tarmoq kartasi — kompyuterni tarmoqqa ulaydi.</li><li>Svitch va router — qurilmalar o‘rtasida ma’lumotni yo‘naltiradi.</li><li>Simli (Ethernet) yoki simsiz (Wi-Fi) ulanish ishlatiladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab kompyuter xonasidagi kompyuterlar bitta printerdan foydalanadi — bu LAN. Turli shaharlardagi filiallarni bog‘laydigan tarmoq esa WAN bo‘ladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>LAN kichik hudud, WAN keng hudud tarmog‘i.</li><li>Internet — eng yirik WAN.</li><li>Tarmoq resurslarni birgalikda ishlatishga yordam beradi.</li></ul>","quiz":[{"q":"LAN nima?","o":["Faqat simsiz klaviatura","Lokal hududiy tarmoq","Global hududiy tarmoq","Bulutli xotira"],"a":1,"e":"LAN — kichik hududdagi tarmoq."},{"q":"WAN nima?","o":["Dastur nomi","Keng hududlarni qamrab oluvchi global tarmoq","Faqat printer","Bitta xonadagi tarmoq"],"a":1,"e":"WAN katta masofalarni birlashtiradi."},{"q":"Eng katta WAN qaysi?","o":["USB","Maktab LANi","Bluetooth","Internet"],"a":3,"e":"Internet butun dunyo tarmoqlarini bog‘laydi."},{"q":"Maktab kompyuter xonasidagi tarmoq qaysi turga kiradi?","o":["VPN","WAN","Bulutli xotira","LAN"],"a":3,"e":"Kichik hududdagi tarmoq LAN."},{"q":"Tarmoq kartasi nima uchun kerak?","o":["Kompyuterni tarmoqqa ulash uchun","Faylni arxivlash uchun","Ekranni sovutish uchun","Tovushni kuchaytirish uchun"],"a":0,"e":"Tarmoqqa ulanish tarmoq kartasi orqali."},{"q":"Tarmoq afzalligi qaysi?","o":["Resurslarni birgalikda ishlatish","Faqat bitta kompyuterda ishlash","Kompyuter tezligini kamaytirish","Printerlarni olib tashlash"],"a":0,"e":"Printer va fayllar umumiy bo‘ladi."},{"q":"Vaziyat: 10 ta kompyuter bitta printerdan foydalanishi kerak. Nima ishlatiladi?","o":["Tarmoq","Ekran saqlagich","Faqat flesh xotira har safar","Faqat CD disk"],"a":0,"e":"Tarmoq printerni umumiy qiladi."},{"q":"Simsiz ulanishga qaysi misol?","o":["Koaksial kabel","Optik tola kabeli","Wi-Fi","Ethernet kabeli"],"a":2,"e":"Wi-Fi simsiz."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Internet LAN hisoblanadi","Maktab tarmog‘i WAN deyiladi","Turli shaharlarni bog‘lovchi tarmoq WAN bo‘ladi","LAN butun dunyoni qamraydi"],"a":2,"e":"WAN keng hududni qamraydi."},{"q":"Router nima qiladi?","o":["Tovushni yozadi","Rasmni skanerlaydi","Matnni chop etadi","Tarmoqlar o‘rtasida ma’lumotni yo‘naltiradi"],"a":3,"e":"Router paketlarni yo‘naltiradi."}]},{"t":"20-dars. Kliyent-server va peer-to-peer tarmoqlari.","lesson":"<p>Tarmoqda kompyuterlarning o‘zaro munosabati turlicha bo‘lishi mumkin. Ikki asosiy model: kliyent-server va peer-to-peer (teng huquqli) tarmoq.</p>\n<h4>Kliyent-server tarmog‘i</h4>\n<ul><li><b>Server</b> — resurs va xizmat taqdim etadigan kuchli kompyuter.</li><li><b>Kliyent</b> — serverdan xizmat so‘raydigan kompyuter.</li><li>Ma’lumotlar markazda saqlanadi, boshqaruv va xavfsizlik oson.</li><li>Server buzilsa, butun tarmoq ishlashi buzilishi mumkin.</li><li>Serverga ko‘p kliyent bir vaqtda murojaat qilishi mumkin.</li></ul>\n<h4>Peer-to-peer (P2P) tarmog‘i</h4>\n<ul><li>Barcha kompyuterlar teng huquqli: ham so‘raydi, ham xizmat beradi.</li><li>Markaziy server shart emas, tarmoq arzon va oddiy.</li><li>Kichik tarmoqlarga mos, ammo xavfsizlik va boshqaruv qiyinroq.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab serverida o‘quvchilarning fayllari saqlanadi va barcha kompyuterlar unga murojaat qiladi — bu kliyent-server. Ikki do‘st kompyuterlarini to‘g‘ridan-to‘g‘ri ulab, fayl almashsa — bu P2P.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Kliyent-serverda markaziy server bor.</li><li>P2Pda barcha kompyuterlar teng.</li><li>Katta tarmoqlarga kliyent-server mos.</li></ul>","quiz":[{"q":"Server nima?","o":["Faqat printer","Faqat foydalanuvchi kompyuteri","Faqat monitor","Xizmat va resurs taqdim etuvchi kompyuter"],"a":3,"e":"Server boshqalarga xizmat ko‘rsatadi."},{"q":"Kliyent nima?","o":["Antivirus","Serverdan xizmat so‘raydigan kompyuter","Tarmoq kabeli","Ma’lumotlar saqlanadigan markaz"],"a":1,"e":"Kliyent so‘rov yuboradi."},{"q":"P2P tarmog‘ida qanday?","o":["Faqat bitta markaziy server bor","Faqat server ishlaydi","Barcha kompyuterlar teng huquqli","Kompyuterlar o‘zaro bog‘lanmaydi"],"a":2,"e":"P2P teng huquqli kompyuterlardan iborat."},{"q":"Qaysi tarmoq kichik va arzon?","o":["Kliyent-server tarmog‘i yirik korxona darajasida","Maxsus ma’lumotlar markazi","Peer-to-peer","Global bulut"],"a":2,"e":"P2P soddaligi bilan kichik tarmoqqa mos."},{"q":"Kliyent-server tarmog‘ining afzalligi qaysi?","o":["Markazlashgan boshqaruv va xavfsizlik","Server talab qilinmaydi","Arzonligi har doim","Har kompyuter alohida sozlanadi"],"a":0,"e":"Markaziy boshqaruv xavfsizlikni osonlashtiradi."},{"q":"Kliyent-server tarmog‘ining kamchiligi qaysi?","o":["Ma’lumot saqlanmaydi","Xavfsizlik umuman yo‘q","Kompyuterlar o‘zaro ulanmaydi","Server buzilsa, tarmoq ishi buziladi"],"a":3,"e":"Server markaziy nuqta bo‘ladi."},{"q":"Vaziyat: katta maktabda yuzlab kompyuter bor. Qaysi tarmoq mos?","o":["Faqat P2P","Hech qaysi","Faqat bitta kompyuter","Kliyent-server"],"a":3,"e":"Katta tarmoqda markaziy boshqaruv qulay."},{"q":"Ikki do‘st to‘g‘ridan-to‘g‘ri fayl almashmoqda. Bu qaysi model?","o":["Mobil tarmoq","WAN","Kliyent-server","P2P"],"a":3,"e":"To‘g‘ridan-to‘g‘ri almashish P2P."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Kliyent-serverda server yo‘q","P2P faqat serverli tarmoq","P2Pda markaziy server shart emas","P2P eng xavfsiz tarmoq"],"a":2,"e":"P2Pda server talab qilinmaydi."},{"q":"Ma’lumotlar markazlashgan holda qaysi tarmoqda saqlanadi?","o":["P2P","Faqat Bluetooth","Kliyent-server","Hech qaysida"],"a":2,"e":"Ma’lumotlar serverda saqlanadi."}]},{"t":"21-dars. Virtual shaxsiy tarmoq (VPN)","lesson":"<p>VPN (Virtual Private Network) — virtual shaxsiy tarmoq. U internet orqali xavfsiz, shifrlangan ulanish yaratadi va foydalanuvchi ma’lumotlarini begona ko‘zdan himoya qiladi.</p>\n<h4>VPN qanday ishlaydi</h4>\n<ul><li>Kompyuter va VPN serveri o‘rtasida shifrlangan \"tunnel\" hosil bo‘ladi.</li><li>Trafik shu tunnel orqali o‘tadi, uni uchinchi shaxs o‘qiy olmaydi.</li><li>Foydalanuvchining IP manzili VPN serverining manzili bilan almashadi.</li></ul>\n<h4>Qo‘llanilishi</h4>\n<ul><li>Xodimlar uzoqdan kompaniya tarmog‘iga xavfsiz ulanadi.</li><li>Ochiq Wi-Fi tarmoqlarida ma’lumotlarni himoyalash.</li><li>Filiallarni bitta virtual tarmoqqa birlashtirish.</li></ul>\n<h4>Cheklovlar</h4>\n<ul><li>VPN tezlikni biroz pasaytirishi mumkin.</li><li>Barcha ma’lumot ham VPN orqali o‘tishi uchun ulanish tezligi provayderga bog‘liq.</li><li>Ishonchsiz VPN xizmati ma’lumotlarni o‘zi to‘plashi mumkin, shuning uchun ishonchli provayder tanlang.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Kompaniya xodimi uydan VPN orqali ulanadi va ichki hujjatlarga xuddi ofisdagidek xavfsiz kiradi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>VPN ulanishni shifrlaydi.</li><li>VPN uzoqdan xavfsiz ishlashga yordam beradi.</li><li>Ishonchli VPN provayderini tanlash kerak.</li></ul>","quiz":[{"q":"VPN nima?","o":["Video protokol turi","Virtual shaxsiy tarmoq","Printer drayveri","Bulutli xotira"],"a":1,"e":"VPN — Virtual Private Network."},{"q":"VPN asosiy nimani ta’minlaydi?","o":["Ekran yorqinligini","Faqat internet tezligini oshirishni","Rasm sifatini yaxshilashni","Shifrlangan xavfsiz ulanishni"],"a":3,"e":"VPN ulanishni himoyalaydi."},{"q":"Tunnel nima?","o":["Brauzer oynasi","Jismoniy yer osti kabeli","Papka turi","Kompyuter va VPN serveri orasidagi shifrlangan yo‘l"],"a":3,"e":"Tunnel shifrlangan ulanishdir."},{"q":"VPN ishlatilganda IP manzil nima bo‘ladi?","o":["Butunlay yo‘qoladi","VPN serverining manzili ko‘rinadi","Faqat kabelga yoziladi","Hech qachon o‘zgarmaydi"],"a":1,"e":"Tashqarida server manzili ko‘rinadi."},{"q":"VPN qayerda ayniqsa foydali?","o":["Ochiq Wi-Fi tarmoqlarida","Printer ishlatishda","Rasm chizishda","Matn yozishda"],"a":0,"e":"Ochiq tarmoqda himoya muhim."},{"q":"Vaziyat: xodim uydan ofis tarmog‘iga xavfsiz ulanishi kerak. Nima ishlatadi?","o":["Faqat flesh xotira","Bluetooth","VPN","Ekran saqlagich"],"a":2,"e":"VPN uzoqdan xavfsiz ulanish beradi."},{"q":"VPNning mumkin bo‘lgan kamchiligi qaysi?","o":["Kompyuterning portlashi","Faylning o‘chishi","Tezlikning biroz pasayishi","Ma’lumotlarning yo‘qolishi har doim"],"a":2,"e":"Shifrlash tezlikka ta’sir qilishi mumkin."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Har qanday VPN bir xil xavfsiz","Ishonchli VPN provayderini tanlash kerak","VPN antivirus o‘rnini bosadi","VPN internetsiz ishlaydi"],"a":1,"e":"Provayder ishonchli bo‘lishi shart."},{"q":"VPN yordamida filiallarni nima qilish mumkin?","o":["Monitorni almashtirish","Dasturlarni o‘chirish","Rasmlarni kichraytirish","Bitta virtual tarmoqqa birlashtirish"],"a":3,"e":"VPN uzoq filiallarni ulaydi."},{"q":"Shifrlash nima uchun kerak?","o":["Tarmoqni o‘chirish uchun","Fayl hajmini oshirish uchun","Trafikni begona shaxs o‘qiy olmasligi uchun","Ekranni tozalash uchun"],"a":2,"e":"Shifrlangan ma’lumotni faqat egasi o‘qiydi."}]},{"t":"22-dars. Intranet va ekstranet. Internet va uning xususiyatlari","lesson":"<p>Tashkilotlar o‘z ehtiyojlariga qarab turli tarmoqlardan foydalanadi. Intranet — tashkilot ichidagi yopiq tarmoq, ekstranet — tashqi hamkorlarga cheklangan kirish beradigan tarmoq, Internet esa hamma uchun ochiq global tarmoqdir.</p>\n<h4>Tarmoq turlari</h4>\n<ul><li><b>Intranet</b> — faqat tashkilot xodimlari foydalanadigan ichki tarmoq; internet texnologiyalaridan foydalanadi.</li><li><b>Ekstranet</b> — intranetning tanlangan tashqi foydalanuvchilarga (hamkor, mijoz) ochilgan qismi.</li><li><b>Internet</b> — butun dunyo tarmoqlarini birlashtiruvchi ochiq global tarmoq.</li></ul>\n<h4>Internet xususiyatlari</h4>\n<ul><li>Hech kimga to‘liq tegishli emas, ko‘plab tarmoqlardan tashkil topgan.</li><li>Umumiy qoidalar — protokollar (masalan, TCP/IP) asosida ishlaydi.</li><li>Xizmatlari: veb, elektron pochta, fayl uzatish, video aloqa.</li><li>Har bir qurilma o‘ziga xos IP manzilga ega bo‘ladi.</li></ul>\n<h4>Farqi</h4>\n<ul><li>Intranetga kirish parol bilan cheklangan.</li><li>Internetga kirish hamma uchun ochiq, ammo ayrim saytlar cheklangan bo‘lishi mumkin.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktabning ichki hujjatlar saytiga faqat o‘qituvchilar kiradi — bu intranet. Maktab bilan hamkor tashkilot ma’lum sahifalarni ko‘rsa — ekstranet. Hammaga ochiq maktab veb-sayti esa internetda joylashadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Intranet — ichki yopiq tarmoq.</li><li>Ekstranet — tanlangan tashqi foydalanuvchilar uchun.</li><li>Internet — ochiq global tarmoq.</li></ul>","quiz":[{"q":"Intranet nima?","o":["Tashkilot ichidagi yopiq tarmoq","Hammaga ochiq global tarmoq","Faqat printer turi","Antivirus dasturi"],"a":0,"e":"Intranet faqat tashkilot xodimlari uchun."},{"q":"Ekstranet kimlar uchun ochiladi?","o":["Tanlangan tashqi hamkorlar va mijozlar","Faqat bitta kompyuter foydalanuvchisi","Hech kim uchun","Hamma, hech qanday cheklovsiz"],"a":0,"e":"Ekstranet cheklangan tashqi kirish beradi."},{"q":"Internet qanday tarmoq?","o":["Faqat bitta kompaniya tarmog‘i","Faqat simsiz klaviatura tarmog‘i","Faqat bitta xonadagi tarmoq","Ko‘plab tarmoqlarni birlashtiruvchi global tarmoq"],"a":3,"e":"Internet — tarmoqlar tarmog‘i."},{"q":"Internet ishlashi uchun qaysi protokollar to‘plami asos bo‘ladi?","o":["TCP/IP","JPEG/PNG","BIOS/UEFI","HTML/CSS"],"a":0,"e":"TCP/IP internetning asosiy protokollari."},{"q":"Qaysi xizmat internetga kiradi?","o":["Sichqoncha tugmasi","Elektron pochta","Quvvat adapteri","Matn muharriri ichidagi shrift"],"a":1,"e":"Pochta internet xizmatidir."},{"q":"Vaziyat: korxonaning ichki hisobotlari faqat xodimlarga ko‘rinishi kerak. Nima mos?","o":["Ijtimoiy tarmoq e’lon","Ochiq internet sayti","Intranet","Hech qaysi"],"a":2,"e":"Ichki ma’lumot uchun intranet mos."},{"q":"Har bir qurilmani internetda qaysi manzil ajratadi?","o":["Shrift nomi","Fayl kengaytmasi","IP manzil","Papka nomi"],"a":2,"e":"IP manzil qurilmani aniqlaydi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Intranetga kirish odatda parol bilan cheklanadi","Internetga faqat bitta tashkilot egalik qiladi","Ekstranet internetdan oldin yaratilgan","Intranet butun dunyoga ochiq"],"a":0,"e":"Intranet yopiq tarmoqdir."},{"q":"Hamkor kompaniya sizning tarmog‘ingizning ma’lum qismini ko‘ra oladi. Bu nima?","o":["Ekran saqlagich","Ekstranet","Bluetooth","Intranet"],"a":1,"e":"Tashqi hamkorlarga cheklangan kirish — ekstranet."},{"q":"Internet kimga to‘liq tegishli?","o":["Faqat bitta davlatga","Faqat bitta kompaniyaga","Birorta ham tashkilotga to‘liq tegishli emas","Faqat provayderga"],"a":2,"e":"Internet markazsiz, ko‘plab tarmoqdan tashkil topgan."}]},{"t":"23-dars. Internetda muloqot qilish. Mobil tarmoqlar","lesson":"<p>Internet orqali odamlar bir-biri bilan tez va qulay muloqot qiladi: xabar yozish, ovozli va video qo‘ng‘iroq qilish, fayl almashish mumkin. Mobil tarmoqlar esa qurilmalarni simsiz aloqaga ulaydi.</p>\n<h4>Internetda muloqot vositalari</h4>\n<ul><li>Elektron pochta — rasmiy va uzun xabarlar uchun.</li><li>Messenjerlar — tezkor matnli va ovozli xabarlar.</li><li>Video qo‘ng‘iroq — tasvir va ovoz bilan jonli aloqa.</li><li>Ijtimoiy tarmoqlar va forumlar — jamoalar bilan muloqot.</li></ul>\n<h4>Muloqot madaniyati</h4>\n<ul><li>Hurmat bilan va aniq yozing.</li><li>Shaxsiy ma’lumotlarni notanishlarga bermang.</li><li>Boshqalarni haqorat qilmang, ishonchsiz xabarlarni tarqatmang.</li></ul>\n<h4>Mobil tarmoqlar</h4>\n<ul><li>Mobil aloqa hududlarga bo‘lingan yacheykalar (hujayralar) va tayanch stansiyalar orqali ishlaydi.</li><li>Avlodlar: 2G, 3G, 4G, 5G — har keyingisi tezroq ma’lumot uzatadi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> O‘quvchi sinfdoshiga messenjerda vazifa yuboradi, o‘qituvchiga esa rasmiy tarzda elektron pochta orqali hisobot jo‘natadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Muloqotda odob qoidalariga amal qiling.</li><li>Shaxsiy ma’lumotlarni himoya qiling.</li><li>Mobil tarmoq avlodlari tezlik bilan farqlanadi.</li></ul>","quiz":[{"q":"Rasmiy xat yuborish uchun qaysi vosita ko‘proq mos?","o":["Elektron pochta","Quvvat adapteri","Ekran saqlagich","Tasodifiy rasm"],"a":0,"e":"Elektron pochta rasmiy xabarlar uchun mos."},{"q":"Jonli tasvir va ovozli aloqani nima beradi?","o":["Papka yaratish","Video qo‘ng‘iroq","Matnli izoh","Fayl arxivlash"],"a":1,"e":"Video qo‘ng‘iroq tasvir va ovozni uzatadi."},{"q":"Internetda muloqot qoidasi qaysi?","o":["Ishonchsiz xabarlarni tarqatish","Shaxsiy ma’lumotlarni hammaga berish","Haqorat qilish","Hurmat bilan muloqot qilish"],"a":3,"e":"Odob muloqotning asosi."},{"q":"Notanish odam shaxsiy ma’lumot so‘rasa, nima qilasiz?","o":["Darhol beraman","Parolni aytaman","Telefon raqamimni hammaga yozaman","Bermayman"],"a":3,"e":"Shaxsiy ma’lumotni notanishlarga berish xavfli."},{"q":"Mobil tarmoqlarda aloqa qaysi qurilmalar orqali ta’minlanadi?","o":["Faqat skanerlar","Faqat printerlar","Faqat monitorlar","Tayanch stansiyalar"],"a":3,"e":"Stansiyalar yacheykalarda aloqani ta’minlaydi."},{"q":"Qaysi avlod mobil tarmog‘i 4G dan keyin keladi?","o":["5G","3G","2G","1G"],"a":0,"e":"5G 4G dan keyingi avlod."},{"q":"Vaziyat: sizga noma’lum havola bilan xabar keldi. Nima qilasiz?","o":["Hammaga yuboraman","Parolimni yozaman","Havolani ochmayman va ehtiyot bo‘laman","Darhol bosaman"],"a":2,"e":"Noma’lum havola xavfli bo‘lishi mumkin."},{"q":"Messenjerning asosiy afzalligi nima?","o":["Faqat uzoq muddat saqlash","Tezkor xabar almashish","Faqat rasm chizish","Faqat chop etish"],"a":1,"e":"Messenjerlar tezkor aloqa beradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Har keyingi mobil avlod odatda tezroq bo‘ladi","Mobil tarmoq simsiz bo‘lmaydi","5G faqat matn uchun","2G eng tez avlod"],"a":0,"e":"Avlodlar tezligi oshib boradi."},{"q":"Ijtimoiy tarmoqda boshqa odamga munosabat qanday bo‘lishi kerak?","o":["Hurmatli va odobli","Qo‘pol","E’tiborsiz va haqoratomuz","Aldamchi"],"a":0,"e":"Onlayn ham odob qoidalari amal qiladi."}]},{"t":"24-dars. Video va veb konferensiya. Videokonferensiyaning jamiyatga ta‘siri","lesson":"<p>Videokonferensiya — turli joylardagi odamlarning internet orqali real vaqtda tasvir va ovoz bilan uchrashuvi. Veb konferensiya esa ko‘proq taqdimot, ma’ruza va ekran ulashishga yo‘naltirilgan bo‘ladi.</p>\n<h4>Zarur vositalar</h4>\n<ul><li>Kamera, mikrofon va karnay yoki quloqchin.</li><li>Barqaror internet aloqasi.</li><li>Konferensiya dasturi yoki xizmati.</li></ul>\n<h4>Imkoniyatlari</h4>\n<ul><li>Ekranni ulashish va taqdimot ko‘rsatish.</li><li>Chat orqali yozma muloqot.</li><li>Uchrashuvni yozib olish.</li><li>Ko‘p ishtirokchi bir vaqtda qatnashadi.</li><li>Ishtirokchilar mikrofonni gapirmayotganda o‘chirib qo‘yishi odobdan hisoblanadi.</li></ul>\n<h4>Jamiyatga ta’siri</h4>\n<ul><li>Vaqt va yo‘l xarajatini tejaydi.</li><li>Masofaviy ta’lim va ish imkonini beradi.</li><li>Uzoq joylardagi mutaxassislar bilan hamkorlik osonlashadi.</li><li>Kamchiligi: internetga bog‘liqlik va jonli muloqotning kamayishi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> O‘qituvchi darsni videokonferensiya orqali o‘tkazadi: ekranni ulashib taqdimot ko‘rsatadi, o‘quvchilar esa savollarini chatga yozadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Videokonferensiyada tasvir va ovoz real vaqtda uzatiladi.</li><li>U vaqt va xarajatni tejaydi.</li><li>Barqaror internet muhim.</li></ul>","quiz":[{"q":"Videokonferensiya nima?","o":["Faqat rasm chizish","Internet orqali tasvir va ovozli jonli uchrashuv","Faqat fayl nusxalash","Faqat matn yozish"],"a":1,"e":"Real vaqtda tasvir va ovoz uzatiladi."},{"q":"Videokonferensiya uchun qaysi uskuna zarur?","o":["Faqat flesh xotira","Faqat skaner","Faqat printer","Kamera va mikrofon"],"a":3,"e":"Tasvir va ovoz uchun kamera va mikrofon kerak."},{"q":"Ekranni ulashish nima uchun kerak?","o":["Faylni o‘chirish uchun","Kompyuterni o‘chirish uchun","Taqdimot yoki ishni boshqalarga ko‘rsatish uchun","Parolni yashirish uchun"],"a":2,"e":"Ishtirokchilar sizning ekraningizni ko‘radi."},{"q":"Videokonferensiyaning afzalligi qaysi?","o":["Ovoz uzatmasligi","Internetni talab qilmasligi","Vaqt va yo‘l xarajatini tejashi","Faqat bir kishi qatnashishi"],"a":2,"e":"Masofadan uchrashuv xarajatni kamaytiradi."},{"q":"Videokonferensiyaning kamchiligi qaysi?","o":["Barqaror internetga bog‘liqligi","Juda arzonligi","Ovoz uzatilmasligi","Faqat bitta shaharda ishlashi"],"a":0,"e":"Aloqa yomon bo‘lsa, sifat tushadi."},{"q":"Vaziyat: ishtirokchi savol bermoqchi, lekin gapirish noqulay. Nima qiladi?","o":["Chatga yozadi","Kompyuterni o‘chiradi","Kamerani yirtadi","Ulanishni uzadi"],"a":0,"e":"Chat yozma muloqotni ta’minlaydi."},{"q":"Videokonferensiya jamiyatga qanday ta’sir qiladi?","o":["Masofaviy ish va ta’limni osonlashtiradi","Hech qanday ta’sir yo‘q","Internetni o‘chiradi","Barcha maktablarni yopadi"],"a":0,"e":"Masofadan ishlash va o‘qish imkonini beradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Veb konferensiya taqdimot va ma’ruzaga mos","Veb konferensiya faqat matn uchun","Konferensiya internetsiz ishlaydi","Konferensiyada tovush bo‘lmaydi"],"a":0,"e":"Veb konferensiya ma’ruza va taqdimotga yo‘naltirilgan."},{"q":"Uchrashuvni keyinchalik ko‘rish uchun nima qilinadi?","o":["O‘chiriladi","Yozib olinadi","Chop etiladi","Shifrlanadi, lekin ko‘rilmaydi"],"a":1,"e":"Konferensiyani yozib olish mumkin."},{"q":"Dars paytida ishtirokchi mikrofonni qachon o‘chirib qo‘yishi odobga mos?","o":["Doim gapirib turganda","Gapirmayotganda","Hech qachon","Faqat kamera o‘chirilganda"],"a":1,"e":"Fon shovqini bo‘lmasligi uchun."}]},{"t":"25-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 3</b> quyidagi darslarni qamrab oladi:</p><ul><li>Samarasi yuqori va past bo‘lgan texnologiyalar. Turli davlatlardagi holatlarni o‘rganish</li><li>Tarmoq kompyuterlari. Lokal hududiy (Local area networks) va global hududiy tarmoq (Wide area networks).</li><li>Kliyent-server va peer-to-peer tarmoqlari.</li><li>Virtual shaxsiy tarmoq (VPN)</li><li>Intranet va ekstranet. Internet va uning xususiyatlari</li><li>Internetda muloqot qilish. Mobil tarmoqlar</li><li>Video va veb konferensiya. Videokonferensiyaning jamiyatga ta‘siri</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Eng katta WAN qaysi?","o":["USB","Maktab LANi","Bluetooth","Internet"],"a":3,"e":"Internet butun dunyo tarmoqlarini bog‘laydi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Intranetga kirish odatda parol bilan cheklanadi","Internetga faqat bitta tashkilot egalik qiladi","Ekstranet internetdan oldin yaratilgan","Intranet butun dunyoga ochiq"],"a":0,"e":"Intranet yopiq tarmoqdir."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Texnologiyani o‘qitmasdan joriy qilish yaxshi","Texnologiya ehtiyojga mos bo‘lsa, samara oshadi","Qimmat texnologiya har doim samarali","Infratuzilma ahamiyatsiz"],"a":1,"e":"Moslik samarani oshiradi."},{"q":"Ekstranet kimlar uchun ochiladi?","o":["Tanlangan tashqi hamkorlar va mijozlar","Faqat bitta kompyuter foydalanuvchisi","Hech kim uchun","Hamma, hech qanday cheklovsiz"],"a":0,"e":"Ekstranet cheklangan tashqi kirish beradi."},{"q":"VPN nima?","o":["Video protokol turi","Virtual shaxsiy tarmoq","Printer drayveri","Bulutli xotira"],"a":1,"e":"VPN — Virtual Private Network."},{"q":"Ekranni ulashish nima uchun kerak?","o":["Faylni o‘chirish uchun","Kompyuterni o‘chirish uchun","Taqdimot yoki ishni boshqalarga ko‘rsatish uchun","Parolni yashirish uchun"],"a":2,"e":"Ishtirokchilar sizning ekraningizni ko‘radi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Internet LAN hisoblanadi","Maktab tarmog‘i WAN deyiladi","Turli shaharlarni bog‘lovchi tarmoq WAN bo‘ladi","LAN butun dunyoni qamraydi"],"a":2,"e":"WAN keng hududni qamraydi."},{"q":"Videokonferensiyaning afzalligi qaysi?","o":["Ovoz uzatmasligi","Internetni talab qilmasligi","Vaqt va yo‘l xarajatini tejashi","Faqat bir kishi qatnashishi"],"a":2,"e":"Masofadan uchrashuv xarajatni kamaytiradi."},{"q":"Ikki do‘st to‘g‘ridan-to‘g‘ri fayl almashmoqda. Bu qaysi model?","o":["Mobil tarmoq","WAN","Kliyent-server","P2P"],"a":3,"e":"To‘g‘ridan-to‘g‘ri almashish P2P."},{"q":"Infratuzilma nimani o‘z ichiga oladi?","o":["Faqat rasmlarni","Faqat dastur nomlarini","Faqat ekran saqlagichni","Elektr va aloqa tarmog‘ini"],"a":3,"e":"Elektr va internet texnologiya ishlashi uchun kerak."},{"q":"Qaysi tarmoq kichik va arzon?","o":["Kliyent-server tarmog‘i yirik korxona darajasida","Maxsus ma’lumotlar markazi","Peer-to-peer","Global bulut"],"a":2,"e":"P2P soddaligi bilan kichik tarmoqqa mos."},{"q":"Tarmoq afzalligi qaysi?","o":["Resurslarni birgalikda ishlatish","Faqat bitta kompyuterda ishlash","Kompyuter tezligini kamaytirish","Printerlarni olib tashlash"],"a":0,"e":"Printer va fayllar umumiy bo‘ladi."},{"q":"Shifrlash nima uchun kerak?","o":["Tarmoqni o‘chirish uchun","Fayl hajmini oshirish uchun","Trafikni begona shaxs o‘qiy olmasligi uchun","Ekranni tozalash uchun"],"a":2,"e":"Shifrlangan ma’lumotni faqat egasi o‘qiydi."},{"q":"Internet ishlashi uchun qaysi protokollar to‘plami asos bo‘ladi?","o":["TCP/IP","JPEG/PNG","BIOS/UEFI","HTML/CSS"],"a":0,"e":"TCP/IP internetning asosiy protokollari."},{"q":"Texnologiyani qo‘llab-quvvatlash nimani bildiradi?","o":["Ta’mirlash va yordam ko‘rsatishni","Narxni oshirishni","Texnologiyani yo‘q qilishni","Faqat reklama qilishni"],"a":0,"e":"Qo‘llab-quvvatlash ishlashda davomiylikni beradi."},{"q":"VPN ishlatilganda IP manzil nima bo‘ladi?","o":["Butunlay yo‘qoladi","VPN serverining manzili ko‘rinadi","Faqat kabelga yoziladi","Hech qachon o‘zgarmaydi"],"a":1,"e":"Tashqarida server manzili ko‘rinadi."},{"q":"Messenjerning asosiy afzalligi nima?","o":["Faqat uzoq muddat saqlash","Tezkor xabar almashish","Faqat rasm chizish","Faqat chop etish"],"a":1,"e":"Messenjerlar tezkor aloqa beradi."},{"q":"Videokonferensiya nima?","o":["Faqat rasm chizish","Internet orqali tasvir va ovozli jonli uchrashuv","Faqat fayl nusxalash","Faqat matn yozish"],"a":1,"e":"Real vaqtda tasvir va ovoz uzatiladi."},{"q":"Vaziyat: sizga noma’lum havola bilan xabar keldi. Nima qilasiz?","o":["Hammaga yuboraman","Parolimni yozaman","Havolani ochmayman va ehtiyot bo‘laman","Darhol bosaman"],"a":2,"e":"Noma’lum havola xavfli bo‘lishi mumkin."},{"q":"Kliyent-server tarmog‘ining kamchiligi qaysi?","o":["Ma’lumot saqlanmaydi","Xavfsizlik umuman yo‘q","Kompyuterlar o‘zaro ulanmaydi","Server buzilsa, tarmoq ishi buziladi"],"a":3,"e":"Server markaziy nuqta bo‘ladi."}]},{"t":"26-dars. Ekspert tizim haqida","lesson":"<p>Ekspert tizim — ma’lum sohadagi mutaxassis (ekspert) bilimlarini kompyuterda saqlab, shu asosda maslahat beradigan va muammo yechadigan dasturdir. U sun’iy intellekt yo‘nalishiga kiradi.</p>\n<h4>Ekspert tizimning vazifasi</h4>\n<ul><li>Murakkab masalada mutaxassis o‘rnini qisman bosish.</li><li>Savollar berib, javoblar asosida xulosa chiqarish.</li><li>Qaror qabul qilishda yordam berish.</li><li>Xulosasini sabablari bilan tushuntirib berish.</li></ul>\n<h4>Qo‘llanish sohalari</h4>\n<ul><li>Tibbiyot — kasallikni dastlabki aniqlash.</li><li>Texnika — nosozlikni topish.</li><li>Moliya, geologiya va ta’limda maslahat berish.</li></ul>\n<h4>Afzallik va kamchiliklar</h4>\n<ul><li>Doim mavjud, charchamaydi, bilimni saqlaydi.</li><li>Faqat o‘ziga kiritilgan bilim doirasida ishlaydi.</li><li>Yangi, kutilmagan holatlarda cheklangan bo‘lishi mumkin.</li><li>Yakuniy javobgarlik odamda qoladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Avtomobil nosozligini aniqlovchi ekspert tizim ustaga savollar beradi: \"Dvigatel ishga tushyaptimi?\" Javoblarga qarab nosozlik sababini taxmin qiladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Ekspert tizim mutaxassis bilimini ishlatadi.</li><li>U faqat ma’lum soha uchun ishlaydi.</li><li>Yakuniy qaror odamniki.</li></ul>","quiz":[{"q":"Ekspert tizim nima?","o":["Mutaxassis bilimiga asoslangan maslahatchi dastur","Antivirus","Operatsion tizim","Matn muharriri"],"a":0,"e":"Ekspert tizim bilimga asoslangan."},{"q":"Ekspert tizim qaysi sohaga kiradi?","o":["Sun’iy intellekt","Faqat printerlar","Faqat tarmoq kabellari","Faqat audio yozish"],"a":0,"e":"U sun’iy intellekt yo‘nalishida."},{"q":"Ekspert tizimning vazifasi qaysi?","o":["Faqat fayllarni arxivlash","Faqat o‘yin o‘ynash","Faqat rasm skanerlash","Qaror qabul qilishda yordam berish"],"a":3,"e":"U maslahat va yechim beradi."},{"q":"Qaysi sohada ekspert tizim ishlatilishi mumkin?","o":["Faqat klaviatura ishlab chiqarishda","Faqat kabel tortishda","Tibbiyotda dastlabki tashxisda","Hech qaysi sohada"],"a":2,"e":"Tibbiyot tipik misol."},{"q":"Ekspert tizimning afzalligi qaysi?","o":["Barcha sohani biladi","Charchamaydi va bilimni saqlaydi","Hech qachon xato qilmaydi","Doim insonni almashtiradi"],"a":1,"e":"Doimiy mavjud va bilimni saqlaydi."},{"q":"Ekspert tizimning cheklovi qaysi?","o":["Faqat kiritilgan bilim doirasida ishlaydi","Dastur emas","Savol bera olmaydi","Tezkor ishlay olmaydi"],"a":0,"e":"Bilim doirasi chegaralangan."},{"q":"Vaziyat: ekspert tizim tashxis qo‘ydi, lekin holat g‘ayrioddiy. Nima qilinadi?","o":["Tizimga so‘zsiz ishoniladi","Natija o‘chiriladi va unutiladi","Kompyuter almashtiriladi","Mutaxassis bilan maslahatlashiladi"],"a":3,"e":"Yakuniy qaror mutaxassisda."},{"q":"Ekspert tizim foydalanuvchiga nima qiladi?","o":["Faqat internetni o‘chiradi","Savollar berib, javoblar asosida xulosa chiqaradi","Faqat chop etadi","Faqat musiqa chaladi"],"a":1,"e":"U dialog orqali ishlaydi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Ekspert tizim bilimsiz ishlaydi","Ekspert tizim ma’lum soha uchun yaratiladi","Ekspert tizim apparat qurilmasi","Ekspert tizim hamma sohani biladi"],"a":1,"e":"Har tizim muayyan soha bilimiga asoslanadi."},{"q":"\"Ekspert\" so‘zi nimani bildiradi?","o":["Oddiy foydalanuvchini","Sohaning bilimdon mutaxassisini","Dastur xatosini","Kabel turini"],"a":1,"e":"Ekspert — soha mutaxassisi."}]},{"t":"27-dars. Bilimlar bazasi va yakunlovchi mexanizm","lesson":"<p>Ekspert tizimning ikki asosiy qismi — bilimlar bazasi va yakunlovchi mexanizm (xulosa chiqarish mexanizmi). Bilimlar bazasi bilimni saqlaydi, yakunlovchi mexanizm esa shu bilimdan foydalanib xulosa chiqaradi.</p>\n<h4>Bilimlar bazasi</h4>\n<ul><li>Sohaga oid faktlar va qoidalar to‘plami.</li><li>Qoidalar odatda \"AGAR ... U HOLDA ...\" ko‘rinishida yoziladi.</li><li>Bilimni mutaxassislardan olib, tizimga kiritadi bilimlar muhandisi.</li></ul>\n<h4>Yakunlovchi mexanizm</h4>\n<ul><li>Foydalanuvchi kiritgan ma’lumotni bilimlar bazasidagi qoidalar bilan solishtiradi.</li><li>Mos qoidalarni qo‘llab, yangi xulosa hosil qiladi.</li><li>Xulosaga qanday kelganini tushuntirib berishi mumkin.</li></ul>\n<h4>Ma’lumotlar bazasidan farqi</h4>\n<ul><li>Oddiy ma’lumotlar bazasi faqat ma’lumotni saqlaydi.</li><li>Bilimlar bazasi qoidalar orqali xulosa chiqarish imkonini ham beradi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Qoida: AGAR haroratning qiymati yuqori VA yo‘tal bor, U HOLDA shifokorga murojaat qilish tavsiya etiladi. Yakunlovchi mexanizm bu qoidani foydalanuvchi javoblariga qo‘llaydi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Bilimlar bazasi bilim va qoidalarni saqlaydi.</li><li>Yakunlovchi mexanizm xulosa chiqaradi.</li><li>Qoidalar AGAR-U HOLDA shaklida yoziladi.</li></ul>","quiz":[{"q":"Bilimlar bazasi nimani saqlaydi?","o":["Faktlar va qoidalarni","Faqat tovushlarni","Faqat parollarni","Faqat rasmlarni"],"a":0,"e":"Bilimlar bazasi bilim to‘plamidir."},{"q":"Yakunlovchi mexanizmning vazifasi nima?","o":["Ma’lumotni chop etish","Tarmoqni ulash","Faylni arxivlash","Bilim asosida xulosa chiqarish"],"a":3,"e":"U bilimdan xulosa chiqaradi."},{"q":"Qoidalar odatda qanday shaklda yoziladi?","o":["KOPIYA ... O‘CHIR ...","BOSH ... OXIR ...","AGAR ... U HOLDA ...","SAQLA ... CHOP ET ..."],"a":2,"e":"Shart-natija shakli ishlatiladi."},{"q":"Bilimlar muhandisi nima qiladi?","o":["Kabellarni tortadi","Mutaxassis bilimini tizimga kiritadi","Monitorlarni ta’mirlaydi","Tarmoqni o‘chiradi"],"a":1,"e":"U bilimni yig‘ib, tizimga joylaydi."},{"q":"Qaysi tuzilma xulosa chiqara oladi?","o":["Monitor","Oddiy fayl nomi","Sichqoncha","Yakunlovchi mexanizm"],"a":3,"e":"Xulosani mexanizm chiqaradi."},{"q":"Bilimlar bazasi oddiy ma’lumotlar bazasidan qanday farq qiladi?","o":["Qoidalar orqali xulosa chiqarishga imkon beradi","Faqat rasm saqlaydi","Hech qanday farq yo‘q","Faqat jadval ko‘rinishida"],"a":0,"e":"Bilimlar bazasi qoidalarni ham o‘z ichiga oladi."},{"q":"Vaziyat: tizim qoidalari eskirgan. Nima qilinadi?","o":["Monitor almashtiriladi","Tizim o‘chirib qo‘yiladi va unutiladi","Foydalanuvchi o‘zgartiriladi","Bilimlar bazasi yangilanadi"],"a":3,"e":"Bilim doimiy yangilanishi kerak."},{"q":"Tizim xulosaga qanday kelganini tushuntirishi nima uchun muhim?","o":["Foydalanuvchi natijaga ishonishi uchun","Fayl kichrayishi uchun","Rasm chiroyli bo‘lishi uchun","Tarmoq tezlashishi uchun"],"a":0,"e":"Tushuntirish ishonchni oshiradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Qoida faqat rasm bo‘ladi","Bilimlar bazasi xulosa chiqaradi","Mexanizm bilimni saqlaydi","Yakunlovchi mexanizm qoidalarni foydalanuvchi ma’lumotlariga qo‘llaydi"],"a":3,"e":"Mexanizm bilim va ma’lumotni bog‘laydi."},{"q":"\"AGAR yomg‘ir yog‘sa, U HOLDA soyabon ol\" qoidasida natija qaysi?","o":["Soyabon olish","AGAR so‘zi","Qoida raqami","Yomg‘ir yog‘ishi"],"a":0,"e":"U holda qismi natijani bildiradi."}]},{"t":"28-dars. Foydalanuvchi interfeysi","lesson":"<p>Foydalanuvchi interfeysi — dastur bilan inson o‘rtasidagi muloqot vositasi. Ekspert tizimda interfeys foydalanuvchiga savollar berish, javoblarni qabul qilish va natijani tushunarli ko‘rsatish uchun xizmat qiladi.</p>\n<h4>Interfeys turlari</h4>\n<ul><li><b>Buyruqlar satri</b> — buyruqlar matn ko‘rinishida kiritiladi.</li><li><b>Grafik interfeys</b> — oyna, tugma, menyu va piktogrammalar.</li><li><b>Ovozli interfeys</b> — buyruqlar ovoz orqali beriladi.</li></ul>\n<h4>Yaxshi interfeys talablari</h4>\n<ul><li>Sodda va tushunarli bo‘lishi.</li><li>Bir xil elementlar bir xil ko‘rinishda bo‘lishi.</li><li>Foydalanuvchi xatosida tushunarli xabar chiqishi.</li><li>Savollar aniq, javob variantlari qulay bo‘lishi.</li></ul>\n<h4>Ekspert tizim interfeysi</h4>\n<ul><li>Savol-javob dialogi, tanlov tugmalari yoki ro‘yxatlar ishlatiladi.</li><li>Natija va uning izohi ko‘rsatiladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Tibbiy ekspert tizim interfeysida \"Harorat bormi?\" savoli va \"Ha\" hamda \"Yo‘q\" tugmalari bo‘ladi. Foydalanuvchi bosib javob beradi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Interfeys — foydalanuvchi va dastur aloqasi.</li><li>Grafik interfeys oyna va tugmalardan iborat.</li><li>Yaxshi interfeys sodda va izchil.</li></ul>","quiz":[{"q":"Foydalanuvchi interfeysi nima?","o":["Kompyuter korpusi","Xotira turi","Foydalanuvchi va dastur orasidagi muloqot vositasi","Tarmoq kabeli"],"a":2,"e":"Interfeys — inson va dastur aloqasi."},{"q":"Buyruqlar satri interfeysida buyruq qanday kiritiladi?","o":["Faqat sichqoncha bilan","Rasm chizib","Matn ko‘rinishida","Ovoz bilan"],"a":2,"e":"Buyruqlar klaviaturada yoziladi."},{"q":"Grafik interfeys nimalardan iborat?","o":["Faqat matn satridan","Faqat kabellardan","Oyna, tugma, menyu va piktogrammalardan","Faqat tovushdan"],"a":2,"e":"Vizual elementlar grafik interfeysni tashkil qiladi."},{"q":"Yaxshi interfeys qanday bo‘lishi kerak?","o":["Sodda va tushunarli","Faqat chiroyli, lekin noqulay","Murakkab va chalkash","Bir xil emas, har xil"],"a":0,"e":"Qulaylik asosiy talab."},{"q":"Ekspert tizimda interfeys nima qiladi?","o":["Ekranni sovutadi","Savollar beradi va natijani ko‘rsatadi","Bilimni o‘chiradi","Kabelni ulaydi"],"a":1,"e":"Foydalanuvchi bilan dialog yuritadi."},{"q":"Ovozli interfeysda buyruq qanday beriladi?","o":["Ovoz orqali","Faqat tugma bosib","Faqat rasm orqali","Faqat klaviaturada"],"a":0,"e":"Ovozli buyruqlar mikrofon orqali qabul qilinadi."},{"q":"Vaziyat: foydalanuvchi noto‘g‘ri qiymat kiritdi. Yaxshi interfeys nima qiladi?","o":["Tushunarli xato xabarini ko‘rsatadi","Ma’lumotni o‘chiradi","Kompyuterni o‘chiradi","Dasturni to‘xtatib qo‘yadi, hech narsa demaydi"],"a":0,"e":"Aniq xabar foydalanuvchiga yordam beradi."},{"q":"Izchillik interfeysda nimani bildiradi?","o":["Har safar ko‘rinish o‘zgarishini","Faqat rang almashishini","Elementlar yo‘qolishini","Bir xil elementlar bir xil ko‘rinishda bo‘lishini"],"a":3,"e":"Izchillik tushunishni osonlashtiradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Interfeys foydalanuvchi qulayligiga mo‘ljallanadi","Interfeys faqat ovozdan iborat","Interfeys ahamiyatsiz","Interfeys faqat dasturchi uchun"],"a":0,"e":"Asosiy maqsad — qulaylik."},{"q":"Ekspert tizimda \"Ha\"/\"Yo‘q\" tugmalari nima uchun qo‘yiladi?","o":["Fayl kattalashishi uchun","Bilimni o‘chirish uchun","Javobni oson tanlash uchun","Tarmoqni tezlatish uchun"],"a":2,"e":"Tanlov tugmalari dialogni soddalashtiradi."}]},{"t":"29-dars. Ekspert tizimlardan foydalanish","lesson":"<p>Ekspert tizimlardan turli sohalarda foydalaniladi. Tizim bilan ishlash savol-javob shaklida bo‘ladi: foydalanuvchi ma’lumotlarni kiritadi, tizim esa bilimlar bazasi asosida tavsiya yoki xulosa beradi.</p>\n<h4>Ekspert tizim bilan ishlash tartibi</h4>\n<ul><li>Muammo yoki savolni aniq belgilang.</li><li>Tizim so‘ragan ma’lumotlarni to‘g‘ri kiriting.</li><li>Chiqqan xulosa va izohni diqqat bilan o‘qing.</li><li>Natijani mustaqil tekshirib, kerak bo‘lsa, mutaxassis bilan maslahatlashing.</li></ul>\n<h4>Qo‘llanish misollari</h4>\n<ul><li>Tibbiyot: simptomlar asosida dastlabki tavsiya.</li><li>Texnika: nosozlikni qidirish.</li><li>Qishloq xo‘jaligi: o‘simlik kasalligini aniqlash.</li><li>Ta’lim: o‘quvchiga mos mashqlar tavsiya etish.</li></ul>\n<h4>Ehtiyot bo‘lish</h4>\n<ul><li>Kiritilgan noto‘g‘ri ma’lumot noto‘g‘ri xulosaga olib keladi.</li><li>Tizim tavsiyasi — yakuniy qaror emas, yordamchi vosita.</li></ul>\n<div class=\"ex\"><b>Misol.</b> O‘simlik kasalligi ekspert tizimida barg rangi, dog‘lar va namlik haqida savollarga javob berilsa, tizim ehtimoliy kasallik va davolash usulini tavsiya qiladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Ma’lumotni aniq va to‘g‘ri kiriting.</li><li>Tizim tavsiyasini tanqidiy baholang.</li><li>Murakkab holatda mutaxassisga murojaat qiling.</li></ul>","quiz":[{"q":"Ekspert tizim bilan ishlash qanday boshlanadi?","o":["Kabelni uzishdan","Muammoni aniq belgilashdan","Faylni o‘chirishdan","Tizimni o‘chirishdan"],"a":1,"e":"Avval nimaga yechim kerakligi aniqlanadi."},{"q":"Noto‘g‘ri ma’lumot kiritilsa, nima bo‘ladi?","o":["Xulosa noto‘g‘ri bo‘lishi mumkin","Hech narsa o‘zgarmaydi","Tizim o‘zi tuzatadi","Xulosa albatta to‘g‘ri bo‘ladi"],"a":0,"e":"Kirish sifati natija sifatini belgilaydi."},{"q":"Tizim tavsiyasi qanday qabul qilinadi?","o":["Hech qachon o‘qilmaydi","Majburiy yakuniy qaror sifatida","Yordamchi tavsiya sifatida","Faqat rasm sifatida"],"a":2,"e":"Tavsiya tanqidiy baholanadi."},{"q":"Qaysi sohada ekspert tizim ishlatilishi mumkin?","o":["Hech qaysida","Qishloq xo‘jaligida kasallikni aniqlashda","Faqat musiqa chalishda","Faqat kabel tortishda"],"a":1,"e":"Ko‘p sohada qo‘llanadi."},{"q":"Ekspert tizim ish tartibida chiqqan xulosa bilan nima qilinadi?","o":["O‘qiladi va tekshiriladi","E’tiborsiz qoldiriladi","Faqat nusxalanadi","Darhol o‘chiriladi"],"a":0,"e":"Natijani diqqat bilan o‘qish kerak."},{"q":"Vaziyat: tizim murakkab tibbiy holatga noaniq javob berdi. Nima qilinadi?","o":["Shifokorga murojaat qilinadi","Tizimga qayta-qayta ishoniladi","Dori o‘zboshimchalik bilan ichiladi","Hech narsa qilinmaydi"],"a":0,"e":"Murakkab holatda mutaxassis kerak."},{"q":"Ekspert tizim ta’limda nima qilishi mumkin?","o":["Imtihonni o‘zi topshirishi","Maktabni almashtirishi","O‘quvchiga mos mashqlar tavsiya etishi","Kitob chop etishi"],"a":2,"e":"Tavsiya berish mumkin."},{"q":"Tizim so‘raydigan ma’lumotlar qanday kiritilishi kerak?","o":["To‘g‘ri va aniq","Taxminiy va tasodifiy","Bo‘sh qoldirilib","Faqat raqam bilan har doim"],"a":0,"e":"Aniq ma’lumot aniq natija beradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Ekspert tizim har doim to‘g‘ri","Tizimga hech qachon savol berilmaydi","Ekspert tizim yordamchi vosita hisoblanadi","Foydalanuvchi hech narsa kiritmaydi"],"a":2,"e":"U yordamchi vosita."},{"q":"Texnikada ekspert tizim nima uchun ishlatiladi?","o":["Rasm chizish uchun","Kitob yozish uchun","Nosozlikni qidirish uchun","Tarmoq kabelini tortish uchun"],"a":2,"e":"Nosozlik sababini topishda yordam beradi."}]},{"t":"30-dars. Ma‘lumotlarni qayta ishlash tizimlari","lesson":"<p>Ma’lumotlarni qayta ishlash tizimlari — ma’lumotlarni to‘plash, saqlash, o‘zgartirish va natija sifatida taqdim etishni amalga oshiradigan tizimlardir. Qayta ishlash jarayoni uch bosqichdan iborat: kirish, qayta ishlash va chiqish.</p>\n<h4>Qayta ishlash bosqichlari</h4>\n<ul><li><b>Kirish</b> — ma’lumotlarni to‘plash va kiritish.</li><li><b>Qayta ishlash</b> — saralash, hisoblash, taqqoslash, tartiblash.</li><li><b>Chiqish</b> — hisobot, jadval yoki diagramma ko‘rinishidagi natija.</li><li><b>Saqlash</b> — natija va ma’lumotni keyingi foydalanish uchun saqlash.</li></ul>\n<h4>Qayta ishlash turlari</h4>\n<ul><li><b>Paketli</b> (batch) — ma’lumotlar to‘planib, birdan qayta ishlanadi (masalan, oylik ish haqi).</li><li><b>Interaktiv</b> — foydalanuvchi bilan dialog orqali, javob tezda beriladi.</li><li><b>Real vaqtda</b> — ma’lumot kelgan zahoti ishlanadi.</li></ul>\n<h4>Misollar</h4>\n<ul><li>Maktab jurnali.</li><li>Do‘kon kassa tizimi.</li><li>Bank hisoblari.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Do‘kon kassasida mahsulot shtrix-kodi o‘qiladi (kirish), tizim narxni topib hisoblaydi (qayta ishlash), chek chiqadi (chiqish).</div>\n<h4>Eslab qoling</h4>\n<ul><li>Kirish, qayta ishlash, chiqish — asosiy bosqichlar.</li><li>Paketli qayta ishlashda ma’lumot to‘planib ishlanadi.</li><li>Interaktiv tizim javobni tez beradi.</li></ul>","quiz":[{"q":"Ma’lumotlarni qayta ishlashning asosiy bosqichlari qaysilar?","o":["Chop etish, o‘chirish, bo‘yash","Kirish, qayta ishlash, chiqish","Saqlamaslik, yo‘q qilish, yopish","Yozish, o‘chirish, yo‘qotish"],"a":1,"e":"Bu klassik uch bosqich."},{"q":"Hisoblash, saralash va taqqoslash qaysi bosqichga kiradi?","o":["Kirish","Ulanish","Qayta ishlash","Chiqish"],"a":2,"e":"Bu bosqichda ma’lumot o‘zgartiriladi."},{"q":"Hisobot va diagramma qaysi bosqichga tegishli?","o":["Ma’lumotni yig‘ish","Hisoblash","Kirish","Chiqish"],"a":3,"e":"Natija chiqish bosqichida taqdim etiladi."},{"q":"Paketli qayta ishlash qanday?","o":["Har ma’lumot zahoti ishlanadi","Ma’lumotlar to‘planib, birdan qayta ishlanadi","Foydalanuvchi bilan doimiy dialog bo‘ladi","Ma’lumot kiritilmaydi"],"a":1,"e":"Paket usulida ma’lumotlar guruhlanadi."},{"q":"Paketli qayta ishlashga qaysi misol mos?","o":["Ovozli xabar yuborish","Dastlabki video qo‘ng‘iroq","O‘yin o‘ynash","Oylik ish haqini hisoblash"],"a":3,"e":"Ish haqi oy oxirida birdan hisoblanadi."},{"q":"Interaktiv tizimning xususiyati qaysi?","o":["Natija bir oydan keyin chiqadi","Ma’lumot kiritilmaydi","Faqat tun kuni ishlaydi","Foydalanuvchi bilan dialog orqali tez javob beradi"],"a":3,"e":"Interaktiv tizim tez javob qaytaradi."},{"q":"Vaziyat: kassada mahsulot shtrix-kodi o‘qilishi qaysi bosqichga kiradi?","o":["Chiqish","Qayta ishlash","Kirish","O‘chirish"],"a":2,"e":"Shtrix-kodni o‘qish — ma’lumot kiritish."},{"q":"Chek chop etilishi qaysi bosqich?","o":["Ulanish","Kirish","Qayta ishlash","Chiqish"],"a":3,"e":"Natija chiqariladi."},{"q":"Real vaqtda qayta ishlash nimani bildiradi?","o":["Ma’lumot kelgan zahoti ishlanishini","Tizim ishlamasligini","Natija bir necha kundan keyin chiqishini","Ma’lumot saqlanmasligini"],"a":0,"e":"Real vaqt — kechiktirmasdan ishlash."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Qayta ishlash tizimi faqat rasm bilan ishlaydi","Qayta ishlashda saqlash bo‘lmaydi","Chiqish bosqichi birinchi keladi","Maktab jurnali ma’lumotlarni qayta ishlash tizimiga misol"],"a":3,"e":"Jurnal ma’lumotlarni to‘playdi va natija beradi."}]},{"t":"31-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 4</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ekspert tizim haqida</li><li>Bilimlar bazasi va yakunlovchi mexanizm</li><li>Foydalanuvchi interfeysi</li><li>Ekspert tizimlardan foydalanish</li><li>Ma‘lumotlarni qayta ishlash tizimlari</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Buyruqlar satri interfeysida buyruq qanday kiritiladi?","o":["Faqat sichqoncha bilan","Rasm chizib","Matn ko‘rinishida","Ovoz bilan"],"a":2,"e":"Buyruqlar klaviaturada yoziladi."},{"q":"Foydalanuvchi interfeysi nima?","o":["Kompyuter korpusi","Xotira turi","Foydalanuvchi va dastur orasidagi muloqot vositasi","Tarmoq kabeli"],"a":2,"e":"Interfeys — inson va dastur aloqasi."},{"q":"Ma’lumotlarni qayta ishlashning asosiy bosqichlari qaysilar?","o":["Chop etish, o‘chirish, bo‘yash","Kirish, qayta ishlash, chiqish","Saqlamaslik, yo‘q qilish, yopish","Yozish, o‘chirish, yo‘qotish"],"a":1,"e":"Bu klassik uch bosqich."},{"q":"Ekspert tizimning cheklovi qaysi?","o":["Faqat kiritilgan bilim doirasida ishlaydi","Dastur emas","Savol bera olmaydi","Tezkor ishlay olmaydi"],"a":0,"e":"Bilim doirasi chegaralangan."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Qoida faqat rasm bo‘ladi","Bilimlar bazasi xulosa chiqaradi","Mexanizm bilimni saqlaydi","Yakunlovchi mexanizm qoidalarni foydalanuvchi ma’lumotlariga qo‘llaydi"],"a":3,"e":"Mexanizm bilim va ma’lumotni bog‘laydi."},{"q":"Hisoblash, saralash va taqqoslash qaysi bosqichga kiradi?","o":["Kirish","Ulanish","Qayta ishlash","Chiqish"],"a":2,"e":"Bu bosqichda ma’lumot o‘zgartiriladi."},{"q":"Qaysi sohada ekspert tizim ishlatilishi mumkin?","o":["Hech qaysida","Qishloq xo‘jaligida kasallikni aniqlashda","Faqat musiqa chalishda","Faqat kabel tortishda"],"a":1,"e":"Ko‘p sohada qo‘llanadi."},{"q":"Ovozli interfeysda buyruq qanday beriladi?","o":["Ovoz orqali","Faqat tugma bosib","Faqat rasm orqali","Faqat klaviaturada"],"a":0,"e":"Ovozli buyruqlar mikrofon orqali qabul qilinadi."},{"q":"Tizim tavsiyasi qanday qabul qilinadi?","o":["Hech qachon o‘qilmaydi","Majburiy yakuniy qaror sifatida","Yordamchi tavsiya sifatida","Faqat rasm sifatida"],"a":2,"e":"Tavsiya tanqidiy baholanadi."},{"q":"Ekspert tizimning afzalligi qaysi?","o":["Barcha sohani biladi","Charchamaydi va bilimni saqlaydi","Hech qachon xato qilmaydi","Doim insonni almashtiradi"],"a":1,"e":"Doimiy mavjud va bilimni saqlaydi."},{"q":"Interaktiv tizimning xususiyati qaysi?","o":["Natija bir oydan keyin chiqadi","Ma’lumot kiritilmaydi","Faqat tun kuni ishlaydi","Foydalanuvchi bilan dialog orqali tez javob beradi"],"a":3,"e":"Interaktiv tizim tez javob qaytaradi."},{"q":"Qaysi tuzilma xulosa chiqara oladi?","o":["Monitor","Oddiy fayl nomi","Sichqoncha","Yakunlovchi mexanizm"],"a":3,"e":"Xulosani mexanizm chiqaradi."},{"q":"Tizim xulosaga qanday kelganini tushuntirishi nima uchun muhim?","o":["Foydalanuvchi natijaga ishonishi uchun","Fayl kichrayishi uchun","Rasm chiroyli bo‘lishi uchun","Tarmoq tezlashishi uchun"],"a":0,"e":"Tushuntirish ishonchni oshiradi."},{"q":"Vaziyat: foydalanuvchi noto‘g‘ri qiymat kiritdi. Yaxshi interfeys nima qiladi?","o":["Tushunarli xato xabarini ko‘rsatadi","Ma’lumotni o‘chiradi","Kompyuterni o‘chiradi","Dasturni to‘xtatib qo‘yadi, hech narsa demaydi"],"a":0,"e":"Aniq xabar foydalanuvchiga yordam beradi."},{"q":"Ekspert tizim bilan ishlash qanday boshlanadi?","o":["Kabelni uzishdan","Muammoni aniq belgilashdan","Faylni o‘chirishdan","Tizimni o‘chirishdan"],"a":1,"e":"Avval nimaga yechim kerakligi aniqlanadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Ekspert tizim bilimsiz ishlaydi","Ekspert tizim ma’lum soha uchun yaratiladi","Ekspert tizim apparat qurilmasi","Ekspert tizim hamma sohani biladi"],"a":1,"e":"Har tizim muayyan soha bilimiga asoslanadi."},{"q":"Yakunlovchi mexanizmning vazifasi nima?","o":["Ma’lumotni chop etish","Tarmoqni ulash","Faylni arxivlash","Bilim asosida xulosa chiqarish"],"a":3,"e":"U bilimdan xulosa chiqaradi."},{"q":"Ekspert tizim nima?","o":["Mutaxassis bilimiga asoslangan maslahatchi dastur","Antivirus","Operatsion tizim","Matn muharriri"],"a":0,"e":"Ekspert tizim bilimga asoslangan."},{"q":"Chek chop etilishi qaysi bosqich?","o":["Ulanish","Kirish","Qayta ishlash","Chiqish"],"a":3,"e":"Natija chiqariladi."},{"q":"Tizim so‘raydigan ma’lumotlar qanday kiritilishi kerak?","o":["To‘g‘ri va aniq","Taxminiy va tasodifiy","Bo‘sh qoldirilib","Faqat raqam bilan har doim"],"a":0,"e":"Aniq ma’lumot aniq natija beradi."}]},{"t":"32-dars. Real vaqt rejimida qayta ishlash tizimi","lesson":"<p>Real vaqt rejimida qayta ishlash tizimi ma’lumot kelishi bilan uni zudlik bilan qayta ishlaydi va natijani kechiktirmay beradi. Bunday tizimlarda javob vaqti juda muhim, kechikish jiddiy oqibatga olib kelishi mumkin.</p>\n<h4>Xususiyatlari</h4>\n<ul><li>Ma’lumot kelgan zahoti qayta ishlanadi.</li><li>Javob vaqti qat’iy cheklangan.</li><li>Yuqori ishonchlilik talab etiladi.</li><li>Ko‘pincha sensorlardan kelgan ma’lumotlar bilan ishlaydi.</li></ul>\n<h4>Misollar</h4>\n<ul><li>Aviadispetcherlik va transport harakatini boshqarish.</li><li>Bankomatlar va onlayn to‘lovlar.</li><li>Tibbiy monitoring qurilmalari.</li><li>Avtomobilning xavfsizlik tizimlari (masalan, havo yostig‘i).</li></ul>\n<h4>Paketli tizimdan farqi</h4>\n<ul><li>Paketli tizimda ma’lumot to‘planib, keyin ishlanadi.</li><li>Real vaqt tizimida kutish deyarli yo‘q.</li><li>Bunday tizimlar uzluksiz ishlashi va xatolarga chidamli bo‘lishi kerak.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Bemorning yurak urishini kuzatuvchi qurilma ma’lumotni uzluksiz oladi va xavfli o‘zgarishda darhol signal beradi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Real vaqt tizimida javob kechikmaydi.</li><li>Ishonchlilik juda muhim.</li><li>Sensorlar bilan ko‘p ishlaydi.</li></ul>","quiz":[{"q":"Real vaqt rejimida qayta ishlash nima?","o":["Faqat qog‘ozda ishlash","Ma’lumotni oyiga bir marta ishlash","Ma’lumotni saqlamaslik","Ma’lumotni kelgan zahoti ishlash"],"a":3,"e":"Kechiktirmay ishlash real vaqtni bildiradi."},{"q":"Real vaqt tizimida nima ayniqsa muhim?","o":["Fayl nomi uzunligi","Ekran rangi","Javob vaqti","Klaviatura turi"],"a":2,"e":"Kechikish xavfli bo‘lishi mumkin."},{"q":"Qaysi misol real vaqt tizimiga kiradi?","o":["Oylik hisobot arxivi","Tibbiy monitoring qurilmasi","Eski hujjatlar bazasi","Matn muharriri shabloni"],"a":1,"e":"Monitoring darhol javob beradi."},{"q":"Paketli tizim real vaqt tizimidan nimasi bilan farq qiladi?","o":["Ma’lumot kelgan zahoti ishlanadi","Javob juda tez beriladi","Ma’lumot to‘planib, keyin ishlanadi","Sensorlardan foydalanadi"],"a":2,"e":"Paketli tizimda kutish bor."},{"q":"Real vaqt tizimlari ko‘pincha qaysi qurilmalardan ma’lumot oladi?","o":["Klaviatura tugmalaridan faqat","Printerlardan","Fleshkalardan faqat","Sensorlardan"],"a":3,"e":"Sensorlar o‘lchovlarni uzluksiz uzatadi."},{"q":"Vaziyat: avtomobil havo yostig‘i to‘qnashuvda ishga tushishi kerak. Qaysi tizim kerak?","o":["Arxiv tizimi","Real vaqt tizimi","Paketli qayta ishlash","Oylik hisobot tizimi"],"a":1,"e":"Soniyaning ulushlarida javob kerak."},{"q":"Real vaqt tizimiga qanday talab qo‘yiladi?","o":["Yuqori ishonchlilik","Sekinlik","Past ishonchlilik","Faqat chiroyli ko‘rinish"],"a":0,"e":"Xato jiddiy oqibatga olib keladi."},{"q":"Qaysi biri real vaqt tizimiga misol?","o":["Elektron kitob fayli","Aviadispetcherlik tizimi","Eski surat albomi","Maktab kitoblari ro‘yxati"],"a":1,"e":"Dispetcherlik darhol qaror talab qiladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Real vaqt tizimi sensorsiz ishlamaydi","Real vaqt tizimida kutish deyarli yo‘q","Real vaqt tizimida natija kunlab kutiladi","Real vaqt tizimida javob ahamiyatsiz"],"a":1,"e":"Kechikish minimal bo‘lishi kerak."},{"q":"Onlayn to‘lov tizimi nima uchun tez ishlashi kerak?","o":["Mijoz natijani zudlik bilan kutadi","Chunki internet kerak emas","Chunki rang o‘zgaradi","Chunki fayl kichik"],"a":0,"e":"To‘lovlar tezkor tasdiqlanishi kerak."}]},{"t":"33-dars. Elektron jadval yaratish. Qatorlar va ustunlarni boshqarish","lesson":"<p>Elektron jadval — ma’lumotlarni qator va ustunlardan iborat katakchalarda saqlash, hisoblash va tahlil qilish dasturi. Ustunlar harflar bilan, qatorlar raqamlar bilan belgilanadi, katak manzili esa ikkalasidan iborat (masalan, B3).</p>\n<h4>Jadval yaratish</h4>\n<ul><li>Yangi kitob (fayl) ochiladi va varaqlar bilan ishlanadi.</li><li>Sarlavhalar birinchi qatorga yoziladi.</li><li>Ma’lumot katakka kiritilib, Enter bilan tasdiqlanadi.</li><li>Fayl saqlanadi, mazmunli nom beriladi.</li></ul>\n<h4>Qator va ustunlarni boshqarish</h4>\n<ul><li>Qator yoki ustun qo‘shish va o‘chirish mumkin.</li><li>Qator balandligi va ustun kengligi o‘zgartiriladi.</li><li>Qator va ustunni yashirish yoki ko‘rsatish mumkin.</li><li>Kataklarni birlashtirish sarlavha uchun qulay.</li></ul>\n<h4>Ma’lumot kiritish tavsiyalari</h4>\n<ul><li>Bir ustunda bir xil turdagi ma’lumot bo‘lsin.</li><li>Bo‘sh qator va ustunlarni ortiqcha qoldirmang.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Sinf ro‘yxatini yaratish: A1 katakka \"Ism\", B1 katakka \"Baho\" yoziladi, keyingi qatorlarga o‘quvchilarning ismi va baholari kiritiladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Katak manzili ustun harfi va qator raqamidan iborat.</li><li>Birinchi qatorga odatda sarlavha yoziladi.</li><li>Qator va ustunlarni qo‘shish, o‘chirish mumkin.</li></ul>","quiz":[{"q":"Elektron jadvalda ustunlar qanday belgilanadi?","o":["Rasmlar bilan","Harflar bilan","Ranglar bilan","Raqamlar bilan"],"a":1,"e":"A, B, C kabi harflar ishlatiladi."},{"q":"Elektron jadvalda qatorlar qanday belgilanadi?","o":["Raqamlar bilan","Harflar bilan","Nomlar bilan","Belgilar bilan"],"a":0,"e":"1, 2, 3 kabi raqamlar."},{"q":"B3 katak qayerda joylashgan?","o":["B ustun va 3 qatorda","3 ustun va B qatorda","B qatorning oxirida","Birinchi qatorda"],"a":0,"e":"Avval ustun harfi, keyin qator raqami."},{"q":"Ma’lumot kiritgandan keyin uni tasdiqlash uchun nima bosiladi?","o":["Caps Lock","Esc","Num Lock","Enter"],"a":3,"e":"Enter kiritishni tasdiqlaydi."},{"q":"Sarlavhalar odatda qayerga yoziladi?","o":["Faqat alohida faylga","Oxirgi qatorga","Tasodifiy joyga","Birinchi qatorga"],"a":3,"e":"Birinchi qator ustunlar nomi uchun."},{"q":"Qator balandligi nimani anglatadi?","o":["Faylning hajmini","Qatorning vertikal o‘lchamini","Ustun nomini","Katakning rangini faqat"],"a":1,"e":"Balandlik qator o‘lchami."},{"q":"Vaziyat: ustundagi matn sig‘may qoldi. Nima qilish kerak?","o":["Dasturni yopish","Ustun kengligini oshirish","Qatorni yo‘qotish","Faylni o‘chirish"],"a":1,"e":"Kengligini o‘zgartirib, matn sig‘diriladi."},{"q":"Yangi qator qo‘shish nima uchun kerak?","o":["Rangni o‘zgartirish uchun","Jadvalga yangi yozuv kiritish uchun","Faylni o‘chirish uchun","Dasturni yopish uchun"],"a":1,"e":"Qator yangi ma’lumot uchun."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Bir ustunda bir xil turdagi ma’lumot yozish tavsiya etiladi","Qator va ustunlar o‘zgarmaydi","Sarlavha bo‘lmasligi kerak","Bir ustunda har xil turdagi ma’lumotlarni aralashtirish yaxshi"],"a":0,"e":"Bir turdagi ma’lumotlar tahlilni osonlashtiradi."},{"q":"Kataklarni birlashtirish ko‘pincha nima uchun ishlatiladi?","o":["Umumiy sarlavha yozish uchun","Ma’lumotni o‘chirish uchun","Faylni himoyalash uchun","Rasmni siqish uchun"],"a":0,"e":"Bir nechta katak bitta katakka aylanadi."}]},{"t":"34-dars. Elektron jadval xavfsizligi","lesson":"<p>Elektron jadvaldagi ma’lumot muhim bo‘lishi mumkin: hisob-kitoblar, ro‘yxatlar, moliyaviy ma’lumotlar. Shuning uchun uni ruxsatsiz ko‘rish, o‘zgartirish va tasodifiy o‘chirib yuborishdan himoya qilish zarur.</p>\n<h4>Himoya usullari</h4>\n<ul><li>Faylni parol bilan ochish yoki o‘zgartirishdan himoyalash.</li><li>Varaq yoki katakchalarni tahrirlashdan himoyalash (bloklash).</li><li>Formulalarni yashirish, faqat natijani ko‘rsatish.</li><li>Muhim kataklarni qulflab, kerakli kataklarni ochiq qoldirish.</li></ul>\n<h4>Qo‘shimcha choralar</h4>\n<ul><li>Faylning zaxira nusxasini saqlash.</li><li>Fayl versiyalarini boshqarish.</li><li>Kirish huquqini faqat kerakli odamlarga berish.</li><li>Kuchli, o‘ylab topilishi qiyin parol tanlash.</li></ul>\n<h4>Parol qoidalari</h4>\n<ul><li>Parolni unutsangiz, uni tiklash qiyin bo‘lishi mumkin.</li><li>Parolni hammaga aytmang va ochiq yozib qo‘ymang.</li></ul>\n<div class=\"ex\"><b>Misol.</b> O‘qituvchi baholar jadvalida faqat baho kataklarini tahrirlashga ruxsat beradi, formulalar yozilgan kataklarni esa qulflab qo‘yadi. Shunda o‘quvchi adashib formulani buzmaydi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Muhim jadvalni parol bilan himoyalang.</li><li>Formulalarni tasodifiy o‘zgarishdan qulflang.</li><li>Zaxira nusxa saqlang.</li></ul>","quiz":[{"q":"Elektron jadvalni himoyalashdan maqsad nima?","o":["Fayl hajmini oshirish","Ma’lumotni ruxsatsiz o‘zgartirish va yo‘qolishdan saqlash","Jadval rangini o‘zgartirish","Internet tezligini oshirish"],"a":1,"e":"Himoya ma’lumot xavfsizligi uchun."},{"q":"Faylni parol bilan himoyalash nimani ta’minlaydi?","o":["Faqat parolni biladiganlar ochadi","Fayl kichrayadi","Ma’lumot avtomatik tahlil qilinadi","Fayl tezroq ochiladi"],"a":0,"e":"Parol ruxsatsiz kirishni to‘sadi."},{"q":"Katakchalarni qulflash nima beradi?","o":["Rangini o‘zgartiradi","Dasturni tezlashtiradi","Ularni tasodifan o‘zgartirishdan saqlaydi","Ularni o‘chiradi"],"a":2,"e":"Qulflangan katak tahrirlanmaydi."},{"q":"Formulalarni yashirishning foydasi qaysi?","o":["Formulani boshqalar ko‘rmaydi, natija ko‘rinadi","Ma’lumot tezlashadi","Fayl o‘chadi","Natija yo‘qoladi"],"a":0,"e":"Faqat natija ko‘rsatiladi."},{"q":"Zaxira nusxa nima uchun kerak?","o":["Rangni saqlash uchun","Parolni o‘chirish uchun","Fayl buzilsa yoki o‘chsa, tiklash uchun","Fayl sekin ishlashi uchun"],"a":2,"e":"Zaxira nusxadan tiklash mumkin."},{"q":"Kuchli parol qanday bo‘ladi?","o":["Faqat 1234","Ismingiz","Faqat bitta harf","Uzun, harf, raqam va belgilar aralash"],"a":3,"e":"Murakkab parol topilishi qiyin."},{"q":"Vaziyat: boshqalar baholar jadvalini tasodifan o‘zgartirib qo‘yishdi. Nima qilish kerak edi?","o":["Zaxira nusxa olmaslik","Faylni internetga qo‘yish","Varaqni tahrirlashdan himoyalash kerak edi","Parolni hammaga aytish"],"a":2,"e":"Himoyalash tasodifiy o‘zgarishning oldini oladi."},{"q":"Kirish huquqi kimga beriladi?","o":["Notanishlarga","Hech kimga, hatto egasiga","Hammaga, cheklovsiz","Faqat kerakli odamlarga"],"a":3,"e":"Huquq zaruratga qarab beriladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Parolni hammaga aytish xavfsizlikni pasaytiradi","Zaxira nusxa xavfsizlikka zarar","Parol ochiq yozib qo‘yilishi yaxshi","Himoya kerak emas"],"a":0,"e":"Parol sirli saqlanishi kerak."},{"q":"Varaqni himoyalashda kerakli kataklarni nima qilish mumkin?","o":["Ochiq qoldirish mumkin","Hammasini o‘chirish kerak","Rasmga aylantirish","Hech qachon ochmaslik"],"a":0,"e":"Ba’zi kataklar tahrirga ochiq qoldiriladi."}]},{"t":"35-dars. Panel va oynalarni interfeysga mahkamlash","lesson":"<p>Zamonaviy dasturlarda ishchi muhit <b>panel</b> va <b>oynalardan</b> iborat. Ularni interfeysga <b>mahkamlash</b> (dock) — kerakli vositalarni doim ko‘z oldida ushlab turish va ish maydonini qulay tartiblash usuli.</p>\n<h4>Asosiy tushunchalar</h4>\n<ul><li><b>Panel</b> — tugmalar va buyruqlar to‘plami joylashgan maydon (asboblar paneli, xossalar paneli).</li><li><b>Mahkamlash</b> — panelni oyna chetiga qo‘yish, shunda u joyidan siljimaydi.</li><li><b>Suzuvchi panel</b> — mahkamlanmagan, ekranning istalgan joyiga olib o‘tiladigan panel.</li><li>Panelni <b>yig‘ish</b> (yashirish) ish maydonini kengaytiradi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Dasturlash muhitida kod muharriri markazda, fayllar daraxti chapga, xatolar ro‘yxati pastga mahkamlanadi. Shunda dasturchi bir qarashda hammasini ko‘radi.</div>\n<h4>Qanday sozlanadi</h4>\n<ol><li>Kerakli panelni tanlang va sichqoncha bilan ushlang.</li><li>Uni oyna chetiga olib boring: dastur mahkamlash joylarini ko‘rsatadi.</li><li>Sichqonchani qo‘yib yuboring: panel joyiga o‘rnashadi.</li><li>Keraksiz panelni yopish yoki yig‘ish mumkin.</li></ol>\n<h4>Eslab qoling</h4><ul><li>Interfeysni o‘z ishingizga moslash vaqtni tejaydi.</li><li>Ish muhitini boshlang‘ich holatga qaytarish imkoniyati ko‘pincha mavjud.</li><li>Juda ko‘p ochiq panel ish maydonini toraytiradi.</li></ul>","quiz":[{"q":"Panelni interfeysga mahkamlash nimani anglatadi?","o":["Panelni boshqa faylga nusxalash","Panelni dasturdan o‘chirish","Panel rangini o‘zgartirish","Panelni oyna chetiga joylab, o‘rnini qotirish"],"a":3,"e":"Mahkamlangan panel siljimaydigan qilib oynaga biriktiriladi."},{"q":"Mahkamlanmagan, ekranning istalgan joyiga olib o‘tish mumkin bo‘lgan panel qanday ataladi?","o":["Suzuvchi panel","Tizim paneli","Mahkam panel","Yashirin fayl"],"a":0,"e":"Suzuvchi panelni erkin siljitish mumkin."},{"q":"Panelni yig‘ish (yashirish) nimaga yordam beradi?","o":["Dasturni tezlashtirishga","Parolni almashtirishga","Faylni saqlashga","Ish maydonini kengaytirishga"],"a":3,"e":"Yashirilgan panel joy bo‘shatadi, kerak bo‘lganda qayta ochiladi."},{"q":"Dasturchi kod muharririni markazga, xatolar ro‘yxatini pastga qo‘ydi. Bu nima uchun qulay?","o":["Kompyuter xotirasi ko‘payadi","Kod avtomatik to‘g‘rilanadi","Kerakli ma’lumotlar bir qarashda ko‘rinib turadi","Internet tezlashadi"],"a":2,"e":"Qulay joylashtirish ish samaradorligini oshiradi."},{"q":"Panelni mahkamlash uchun avval nima qilinadi?","o":["Kompyuter qayta ishga tushiriladi","Faylning nomi o‘zgartiriladi","Panelni sichqoncha bilan ushlab, oyna chetiga olib boriladi","Dastur o‘chirib qayta o‘rnatiladi"],"a":2,"e":"Panelni tortib, mahkamlash joyiga qo‘yiladi."},{"q":"Quyidagilardan qaysi biri interfeysni sozlashning foydasi hisoblanadi?","o":["Ma’lumotlarni avtomatik shifrlaydi","Virusdan to‘liq himoya qiladi","Ishni qulaylashtirib, vaqtni tejaydi","Fayl hajmini kichraytiradi"],"a":2,"e":"Interfeysni moslash ish tezligiga ta’sir qiladi."},{"q":"Ish maydoni juda ko‘p ochiq panel bilan to‘lib ketsa, nima qilish maqsadga muvofiq?","o":["Dasturni o‘chirmasdan qoldirish","Yana ko‘proq panel ochish","Keraksiz panellarni yopish yoki yig‘ish","Monitorni almashtirish"],"a":2,"e":"Keraksiz panelni yashirib, ish maydoni kengaytiriladi."},{"q":"Panel nima?","o":["Faqat matn saqlaydigan fayl","Tugma va buyruqlar joylashgan maydon","Tarmoq qurilmasi","Antivirus dasturi"],"a":1,"e":"Panel buyruqlarni qulay joylashtirish uchun xizmat qiladi."},{"q":"Ish muhiti buzilib ketgan bo‘lsa, ko‘pgina dasturlarda nima qilish mumkin?","o":["Operatsion tizimni almashtirish","Hech narsa qilib bo‘lmaydi","Interfeysni boshlang‘ich holatga qaytarish","Kompyuterni sotish"],"a":2,"e":"Odatda joylashuvni asl holatga qaytarish buyrug‘i bor."},{"q":"Quyidagilardan qaysi biri mahkamlangan panelga xos?","o":["Joyidan o‘z-o‘zidan siljimaydi","Faqat bir marta ishlatiladi","Fayl nomini yashiradi","Doim ekranning o‘rtasida suzib yuradi"],"a":0,"e":"Mahkamlangan panel o‘z o‘rnida turadi."}]},{"t":"36-dars. Elektron jadvalni formatlash. Shartli formatlash","lesson":"<p>Elektron jadvalda ma’lumot nafaqat to‘g‘ri, balki o‘qishga qulay ham bo‘lishi kerak. Buning uchun <b>formatlash</b> qo‘llanadi, <b>shartli formatlash</b> esa katak ko‘rinishini ichidagi qiymatga qarab avtomatik o‘zgartiradi.</p>\n<h4>Oddiy formatlash</h4>\n<ul><li><b>Son formati:</b> umumiy, pul, foiz, sana, vaqt, kasr.</li><li><b>Tekislash:</b> chapga, o‘rtaga, o‘ngga; katakni birlashtirish.</li><li><b>Shrift, to‘ldirish rangi, chegaralar.</b></li><li><b>Matnni o‘rash</b> — uzun matn katak ichida bir necha qatorga bo‘linadi.</li></ul>\n<h4>Shartli formatlash</h4>\n<p>Katak ko‘rinishi <b>shart</b> bajarilganda o‘zgaradi. Masalan, bahosi 3 dan past o‘quvchilar qizil rangda ko‘rsatiladi.</p>\n<div class=\"ex\"><b>Misol.</b> Savdo jadvalida sotuv rejasidan oshgan kataklar yashil, past bo‘lganlari qizil bo‘lsin. Diapazon belgilanadi, qoida: «qiymat reja qiymatidan katta» yoki «kichik», va format tanlanadi.</div>\n<h4>Shartli formatlash turlari</h4>\n<ul><li>Katak qoidalari (katta, kichik, teng, matn tarkibi, takrorlanuvchi).</li><li>Eng yuqori/eng quyi qiymatlar.</li><li>Ma’lumot chiziqlari, rang shkalalari, belgilar to‘plami.</li></ul>\n<h4>Eslab qoling</h4><ul><li>Shartli format qiymat o‘zgarsa, avtomatik yangilanadi.</li><li>Qiymatning o‘zi o‘zgarmaydi, faqat ko‘rinishi o‘zgaradi.</li></ul>","quiz":[{"q":"Shartli formatlash nima?","o":["Formulani o‘chirish","Katak ko‘rinishining ichidagi qiymatga qarab avtomatik o‘zgarishi","Katakni qo‘lda bo‘yash","Jadvalni boshqa faylga nusxalash"],"a":1,"e":"Shart bajarilsa, katak belgilangan formatga o‘tadi."},{"q":"Shartli formatlash qo‘llanganda katakdagi qiymat nima bo‘ladi?","o":["O‘zgarmaydi, faqat ko‘rinishi o‘zgaradi","Nolga aylanadi","Matnga aylanadi","O‘chib ketadi"],"a":0,"e":"Format faqat tashqi ko‘rinishga ta’sir qiladi."},{"q":"Katak ichidagi uzun matnni bir necha qatorda ko‘rsatish qaysi sozlama bilan bajariladi?","o":["Filtrlash","Katakni o‘chirish","Saralash","Matnni o‘rash"],"a":3,"e":"Matnni o‘rash qatorlarni katak kengligiga moslaydi."},{"q":"Quyidagilardan qaysi biri shartli formatlashga misol?","o":["Bahosi 3 dan past kataklar qizil bo‘lishi","Sarlavhani qalin qilish","Barcha kataklarni qo‘lda sariq qilish","Jadval nomini o‘zgartirish"],"a":0,"e":"Bunda rang qiymatga qarab avtomatik beriladi."},{"q":"Katak qiymati o‘zgarsa, shartli format nima bo‘ladi?","o":["Yangi qiymatga qarab avtomatik qayta baholanadi","Faylni o‘chiradi","Xato xabarini chiqaradi","O‘zgarishsiz qoladi"],"a":0,"e":"Qoida doim amal qiladi."},{"q":"Son formatlari qatoriga qaysi biri kiradi?","o":["Sichqoncha tezligi","Pul birligi","Printer rangi","Klaviatura turi"],"a":1,"e":"Pul, foiz, sana va vaqt son formatlaridir."},{"q":"Ma’lumot chiziqlari va rang shkalalari nima uchun ishlatiladi?","o":["Qiymatlarni vizual taqqoslash uchun","Parol qo‘yish uchun","Tarmoqqa ulanish uchun","Faylni siqish uchun"],"a":0,"e":"Ular qiymat kattaligini rang yoki chiziq uzunligi bilan ko‘rsatadi."},{"q":"Eng yuqori 10 qiymatni ajratib ko‘rsatish qaysi turga kiradi?","o":["Eng yuqori/eng quyi qiymatlar qoidasi","Hoshiya chizish","Katakni birlashtirish","Sahifa maketi"],"a":0,"e":"Bunday qoida eng katta yoki eng kichik qiymatlarni belgilaydi."},{"q":"Katakni birlashtirish nima uchun kerak?","o":["Diagramma yaratish uchun","Formulani hisoblash uchun","Faylni saqlash uchun","Bir necha katakni bitta katak qilib, sarlavha joylash uchun"],"a":3,"e":"Birlashtirilgan katak kengaytirilgan sarlavhaga qulay."},{"q":"Shartli formatlashni qo‘llash uchun avval nima qilinadi?","o":["Dastur o‘chiriladi","Ekran yorug‘ligi o‘zgartiriladi","Fayl yopiladi","Diapazon belgilanadi"],"a":3,"e":"Qoida tanlangan katak diapazoniga qo‘llanadi."}]},{"t":"37-dars. Formula va funksiyalarni yaratish. Katakka absolyut va nisbiy murojaat","lesson":"<p><b>Formula</b> — elektron jadvalda hisoblash buyrug‘i, u doim <b>=</b> belgisidan boshlanadi. <b>Funksiya</b> — tayyor hisoblash vositasi (masalan, SUM, AVERAGE, MAX, MIN).</p>\n<div class=\"ex\"><b>Misol.</b> =A1+B1 — ikki katak yig‘indisi; =SUM(A1:A5) — beshta katak yig‘indisi; =AVERAGE(B2:B9) — o‘rtacha qiymat.</div>\n<h4>Murojaat turlari</h4>\n<ul><li><b>Nisbiy murojaat</b> (A1): formula nusxalanganda manzil joyiga qarab o‘zgaradi.</li><li><b>Absolyut murojaat</b> ($A$1): nusxalanganda manzil o‘zgarmaydi.</li><li><b>Aralash murojaat</b> ($A1 yoki A$1): bir qismi qotirilgan.</li></ul>\n<div class=\"ex\"><b>Misol.</b> B2 katakda narx, C1 katakda kurs bo‘lsin. Barcha narxni kursga ko‘paytirish uchun =B2*$C$1 yoziladi. Pastga nusxalanganda B2 B3, B4 ga o‘zgaradi, $C$1 esa o‘zgarmaydi.</div>\n<h4>Eslab qoling</h4><ul><li>Dollar belgisi ($) manzilni qotiradi.</li><li>Ko‘pchilik dasturlarda murojaat turini klaviaturadagi maxsus tugma bilan almashtirish mumkin.</li><li>Diapazon ikki nuqta bilan yoziladi: A1:A5.</li></ul>","quiz":[{"q":"Formula qaysi belgidan boshlanadi?","o":["@ belgisidan","? belgisidan","= belgisidan","# belgisidan"],"a":2,"e":"Elektron jadvalda formula tenglik belgisi bilan boshlanadi."},{"q":"$A$1 qanday murojaat?","o":["Diapazon","Absolyut murojaat","Nisbiy murojaat","Funksiya"],"a":1,"e":"Ikki dollar belgisi satr va ustunni ham qotiradi."},{"q":"Formula pastga nusxalanganda manzili o‘zgaradigan murojaat qaysi?","o":["To‘liq qotirilgan murojaat","Nisbiy murojaat","Absolyut murojaat","Dollarli murojaat"],"a":1,"e":"Nisbiy manzil joylashuvga moslashadi."},{"q":"Barcha narxni bitta kursga ko‘paytirish uchun kurs katagiga qanday murojaat qilinadi?","o":["Faqat C","Nisbiy: C1","Absolyut: $C$1","Faqat 1"],"a":2,"e":"Kurs katagi nusxalanganda o‘zgarmasligi kerak."},{"q":"=SUM(A1:A5) formulasi nimani hisoblaydi?","o":["Eng katta qiymatni","Faqat A1 va A5 ni ko‘paytiradi","A1 dan A5 gacha katak yig‘indisini","A1 dan A5 gacha o‘rtachani"],"a":2,"e":"SUM funksiyasi yig‘indi hisoblaydi."},{"q":"A1:A5 yozuvi nimani bildiradi?","o":["Bo‘lish amalini","Sahifa raqamini","Katakdan kataklar diapazonini","Fayl nomini"],"a":2,"e":"Ikki nuqta diapazon chegarasini ko‘rsatadi."},{"q":"AVERAGE funksiyasi nima hisoblaydi?","o":["Yig‘indini","O‘rtacha arifmetik qiymatni","Eng kichik qiymatni","Kataklar sonini"],"a":1,"e":"AVERAGE — o‘rtacha qiymat."},{"q":"$A1 qanday murojaat?","o":["To‘liq absolyut","Matn","Aralash murojaat","To‘liq nisbiy"],"a":2,"e":"Faqat ustun qotirilgan."},{"q":"Funksiya nima?","o":["Katak rangi","Sahifa o‘lchami","Tayyor hisoblash vositasi","Fayl kengaytmasi"],"a":2,"e":"Funksiya berilgan qiymatlar ustida amal bajaradi."},{"q":"=B2*$C$1 formula B3 ga nusxalansa, qanday ko‘rinishga keladi?","o":["=B3*$C$1","=B3*C2","=B2*$C$2","=C3*$C$1"],"a":0,"e":"Nisbiy B2 o‘zgaradi, absolyut $C$1 qoladi."}]},{"t":"38-dars. Nomlangan katak va diapazon","lesson":"<p>Katak yoki diapazon manzilini (A1:C10) eslab qolish qiyin. Shuning uchun ularga <b>nom</b> berish mumkin. Nomlangan katak formulani o‘qishni osonlashtiradi.</p>\n<div class=\"ex\"><b>Misol.</b> C1 katagiga «Kurs» nomi berilsa, =B2*$C$1 o‘rniga =B2*Kurs deb yozish mumkin. Bunday formula tushunarli va nusxalanganda xato qilmaydi.</div>\n<h4>Nom berish qoidalari</h4>\n<ul><li>Nom harfdan yoki pastki chiziqdan boshlanadi.</li><li>Nomda probel bo‘lmaydi (pastki chiziqdan foydalaniladi: Soliq_foizi).</li><li>Nom katak manziliga o‘xshamasligi kerak (masalan, A1 deb nomlab bo‘lmaydi).</li><li>Nom ishchi kitob bo‘ylab bir xil ma’noda ishlaydi.</li></ul>\n<h4>Foydalari</h4>\n<ul><li>Formulalar o‘qishga oson bo‘ladi.</li><li>Katta jadvalda kerakli diapazonga tez o‘tish mumkin.</li><li>Absolyut murojaatni qo‘lda yozish shart emas.</li><li>Xatolar kamayadi.</li></ul>\n<h4>Eslab qoling</h4><ul><li>Nomlangan diapazon funksiyalarda argument sifatida ishlatiladi: =SUM(Sotuv).</li><li>Nomlarni boshqarish oynasida ularni o‘zgartirish va o‘chirish mumkin.</li></ul>","quiz":[{"q":"Nomlangan katak nima uchun qulay?","o":["Internet tezlashadi","Jadval avtomatik chop etiladi","Fayl hajmi kamayadi","Formula tushunarli bo‘ladi va xato kamayadi"],"a":3,"e":"Nom manzildan eslab qolish oson."},{"q":"Quyidagilardan qaysi biri to‘g‘ri nom bo‘la oladi?","o":["Soliq foizi","Soliq_foizi","A1","1Soliq"],"a":1,"e":"Probelsiz, harfdan boshlangan nom to‘g‘ri."},{"q":"Nomda probel ishlatsa bo‘ladimi?","o":["Yo‘q, probel o‘rniga pastki chiziq ishlatiladi","Ha, hech qanday cheklov yo‘q","Faqat ikkita probel","Faqat nomning oxirida"],"a":0,"e":"Nomda probel bo‘lishi mumkin emas."},{"q":"Nomlangan diapazon funksiyada qanday ishlatiladi?","o":["Argument sifatida: =SUM(Sotuv)","Faqat diagrammada","Faqat chop etishda","Faqat sarlavhada"],"a":0,"e":"Nom manzil o‘rnida yoziladi."},{"q":"A1 deb katakka nom berish mumkinmi?","o":["Faqat ikkinchi sahifada","Ha, har doim","Faqat son bo‘lsa","Yo‘q, chunki bu katak manziliga o‘xshaydi"],"a":3,"e":"Nom manzilga o‘xshamasligi shart."},{"q":"Katta jadvalda nomlangan diapazonning yana bir foydasi qaysi?","o":["Tovush yoqiladi","Kerakli joyga tez o‘tish mumkin","Rasm hajmi kichrayadi","Ma’lumot shifrlanadi"],"a":1,"e":"Nom orqali diapazon tez tanlanadi."},{"q":"=B2*Kurs formulasida Kurs nima?","o":["Operator","Nomlangan katak","Funksiya","Fayl nomi"],"a":1,"e":"Kurs — katakka berilgan nom."},{"q":"Nomlarni boshqarish oynasida nima qilish mumkin?","o":["Nomni o‘zgartirish va o‘chirish","Rasmni qirqish","Kompyuter parolini almashtirish","Faylni internetga yuklash"],"a":0,"e":"Bu yerda barcha nomlar ko‘rinadi va tahrirlanadi."},{"q":"Nomlangan katakdan foydalanish absolyut murojaat bilan solishtirganda nimasi qulay?","o":["Jadval o‘zi hisoblaydi","Katak o‘chirilmaydi","Formula umuman kerak emas","$ belgilarini qo‘lda yozish shart emas"],"a":3,"e":"Nom odatda butun kitobda bir joyga ishora qiladi."},{"q":"Nomlangan diapazon nima?","o":["Rangli katak","Chop etish maydoni","Diagramma turi","Nom berilgan kataklar guruhi"],"a":3,"e":"Diapazonga ham nom berish mumkin."}]},{"t":"39-dars. Yaxlitlash funksiyalari","lesson":"<p>Hisob-kitobda natijani kerakli aniqlikkacha <b>yaxlitlash</b> kerak bo‘ladi: narxlar, o‘rtacha ball, foizlar. Elektron jadvalda buning uchun maxsus funksiyalar bor.</p>\n<h4>Asosiy funksiyalar</h4>\n<ul><li><b>ROUND(son; xonalar)</b> — oddiy qoida bo‘yicha yaxlitlaydi (5 va undan katta raqamda yuqoriga).</li><li><b>ROUNDUP</b> — har doim kattaroq tomonga (noldan uzoqlashtirib).</li><li><b>ROUNDDOWN</b> — har doim kichikroq tomonga (noldan yaqinlashtirib).</li><li><b>INT</b> — sonning butun qismini beradi (musbat sonlarda kasr qismini tashlaydi).</li></ul>\n<div class=\"ex\"><b>Misol.</b> A1 katakda 3,14159 bo‘lsin.<br>ROUND(A1; 2) natijasi 3,14.<br>ROUNDUP(A1; 2) natijasi 3,15.<br>ROUNDDOWN(A1; 2) natijasi 3,14.<br>ROUND(1234; -2) natijasi 1200 — manfiy xona butun qismdagi xonalarni yaxlitlaydi.</div>\n<h4>Xonalar soni</h4>\n<p>Ikkinchi argument 0 bo‘lsa, son butungacha yaxlitlanadi; musbat bo‘lsa, kasr qismidagi xonalar soni; manfiy bo‘lsa, vergulgacha bo‘lgan xonalar yaxlitlanadi.</p>\n<p>Diqqat: katakning son formatida xonalar sonini kamaytirish faqat ko‘rinishni o‘zgartiradi, qiymatni emas. ROUND esa qiymatning o‘zini o‘zgartiradi.</p>\n<h4>Eslab qoling</h4><ul><li>ROUND, ROUNDUP, ROUNDDOWN va INT yaxlitlash funksiyalaridir.</li><li>Manfiy xonalar soni vergulgacha bo‘lgan xonalarni yaxlitlaydi.</li><li>Format ko‘rinishni, funksiya qiymatni o‘zgartiradi.</li></ul>","quiz":[{"q":"Sonni oddiy qoida bo‘yicha yaxlitlaydigan funksiya qaysi?","o":["ROUNDDOWN","SUM","ROUND","INT"],"a":2,"e":"ROUND oddiy matematik qoida bilan yaxlitlaydi."},{"q":"ROUND(3,14159; 2) natijasi nechaga teng?","o":["3,14","3,1","3,142","3,15"],"a":0,"e":"Uchinchi raqam 1, shuning uchun 3,14 qoladi."},{"q":"ROUNDUP(3,14159; 2) natijasi nechaga teng?","o":["3,14","3,15","3,2","3,1"],"a":1,"e":"ROUNDUP doim kattaroq tomonga yaxlitlaydi."},{"q":"ROUNDDOWN(7,89; 1) natijasi nechaga teng?","o":["8","7,9","7,8","7,89"],"a":2,"e":"ROUNDDOWN ortiqcha xonani kattalashtirmay tashlaydi."},{"q":"ROUND(1234; -2) natijasi nechaga teng?","o":["1000","1300","1230","1200"],"a":3,"e":"Manfiy xona yuzliklargacha yaxlitlaydi."},{"q":"ROUND funksiyasining ikkinchi argumenti nimani bildiradi?","o":["Qoldiriladigan xonalar sonini","Jadval nomini","Yaxlitlanadigan katak rangini","Funksiya nusxalari sonini"],"a":0,"e":"Bu argument xonalar sonini beradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Son formati qiymatni doim yaxlitlab o‘zgartiradi","ROUND funksiyasi faqat ko‘rinishni o‘zgartiradi","Son formatida xonalarni kamaytirish qiymatni emas, ko‘rinishni o‘zgartiradi","Yaxlitlash faqat butun sonlarga qo‘llanadi"],"a":2,"e":"Format ko‘rinishga, ROUND qiymatga ta’sir qiladi."},{"q":"Do‘konda narx 12,3456 so‘m chiqdi, uni tiyingacha (ikki xona) yaxlitlash kerak. Qaysi ifoda mos?","o":["INT(12,3456)","ROUND(12,3456; -2)","ROUND(12,3456; 0)","ROUND(12,3456; 2)"],"a":3,"e":"Ikki xona uchun ikkinchi argument 2 bo‘ladi."},{"q":"INT funksiyasi 8,9 sonidan qanday natija beradi?","o":["0","8,9","9","8"],"a":3,"e":"INT butun qismni qaytaradi."},{"q":"Yaxlitlashni noldan uzoqlashtirib bajaruvchi funksiya qaysi?","o":["ROUNDDOWN","ABS","INT","ROUNDUP"],"a":3,"e":"ROUNDUP sonni modul bo‘yicha oshiradi."}]},{"t":"40-dars. Sana va vaqtga oid funksiyalar. Shartli funksiyalar. Qidirish funksiyalari","lesson":"<p>Elektron jadval sana va vaqt bilan ishlay oladi, shartga qarab qaror qabul qiladi va kerakli ma’lumotni jadvaldan qidirib topadi.</p>\n<h4>Sana va vaqt funksiyalari</h4>\n<ul><li><b>TODAY()</b> — joriy sana, <b>NOW()</b> — joriy sana va vaqt.</li><li><b>YEAR, MONTH, DAY</b> — sanadan yil, oy, kunni ajratadi.</li><li>Ikki sana ayirmasi — oradagi kunlar soni.</li></ul>\n<h4>Shartli funksiyalar</h4>\n<p><b>IF(shart; agar rost; agar yolg‘on)</b> shart bajarilishiga qarab ikki natijadan birini beradi. Murakkab shartlar uchun <b>AND</b> (hammasi rost) va <b>OR</b> (kamida biri rost) ishlatiladi.</p>\n<div class=\"ex\"><b>Misol.</b> =IF(B2&gt;=3;\"O‘tdi\";\"Qoldi\") — baho 3 yoki undan yuqori bo‘lsa «O‘tdi», aks holda «Qoldi» yoziladi.</div>\n<h4>Qidirish funksiyalari</h4>\n<ul><li><b>VLOOKUP</b> — qiymatni jadvalning birinchi ustunidan qidirib, shu qatordagi boshqa ustundan natija qaytaradi.</li><li><b>HLOOKUP</b> — xuddi shunday, lekin birinchi qatordan qidiradi.</li></ul>\n<p>Qidirish jadvalida aniq moslik uchun odatda oxirgi argument sifatida «aniq moslik» tanlanadi.</p>\n<h4>Eslab qoling</h4><ul><li>TODAY har ochilganda yangilanadi.</li><li>IF ikki yo‘ldan birini tanlaydi.</li><li>VLOOKUP vertikal, HLOOKUP gorizontal qidiradi.</li></ul>","quiz":[{"q":"Joriy sanani beradigan funksiya qaysi?","o":["SUM","DAY","YEAR","TODAY"],"a":3,"e":"TODAY joriy sanani qaytaradi."},{"q":"Sanadan faqat yilni ajratib oladigan funksiya qaysi?","o":["YEAR","MONTH","NOW","DAY"],"a":0,"e":"YEAR sananing yil qismini beradi."},{"q":"IF funksiyasi qanday ishlaydi?","o":["Shartga qarab ikki natijadan birini beradi","Katak rangini o‘zgartiradi","Sonlarni qo‘shadi","Jadvalni saralaydi"],"a":0,"e":"IF shart rost yoki yolg‘onligiga qarab natija beradi."},{"q":"=IF(B2>=3;\"O‘tdi\";\"Qoldi\") formulada B2 ga 2 yozilsa, natija qanday bo‘ladi?","o":["2","Xato","O‘tdi","Qoldi"],"a":3,"e":"Shart yolg‘on, ikkinchi natija chiqadi."},{"q":"Bir nechta shartning hammasi bir vaqtda bajarilishini tekshirish uchun qaysi funksiya ishlatiladi?","o":["TODAY","AND","INT","OR"],"a":1,"e":"AND hamma shart rost bo‘lsa, rost beradi."},{"q":"Kamida bitta shart bajarilsa, rost beradigan funksiya qaysi?","o":["ROUND","DAY","OR","AND"],"a":2,"e":"OR kamida bitta rost shartni yetarli deb oladi."},{"q":"Qiymatni jadvalning birinchi ustunidan qidirib, shu qatordagi boshqa ustundan natija qaytaradigan funksiya qaysi?","o":["HLOOKUP","VLOOKUP","NOW","ROUNDUP"],"a":1,"e":"VLOOKUP vertikal qidiradi."},{"q":"Ma’lumotlar birinchi qatorda joylashgan jadvalda qidirish uchun qaysi funksiya mos?","o":["HLOOKUP","VLOOKUP","YEAR","IF"],"a":0,"e":"HLOOKUP gorizontal qidiradi."},{"q":"Tug‘ilgan sana ma’lum. Hozirgi yoshni hisoblash uchun qaysi funksiya kerak bo‘ladi?","o":["HLOOKUP","ROUND","AND","TODAY"],"a":3,"e":"Yosh joriy sana va tug‘ilgan sana farqidan topiladi."},{"q":"NOW va TODAY funksiyalarining farqi nimada?","o":["Ular bir xil natija beradi","NOW faqat vaqtni, TODAY faqat yilni beradi","NOW vaqtni ham beradi, TODAY faqat sanani","TODAY sonni yaxlitlaydi"],"a":2,"e":"NOW sana va vaqtni, TODAY faqat sanani qaytaradi."}]},{"t":"41-dars. INDEX va MATCH funksiyalari","lesson":"<p>VLOOKUP faqat birinchi ustundan qidira oladi. <b>INDEX</b> va <b>MATCH</b> funksiyalari birgalikda ancha moslashuvchan qidirish imkonini beradi.</p>\n<h4>MATCH funksiyasi</h4>\n<p><b>MATCH(qidirilayotgan qiymat; diapazon; tur)</b> qiymat diapazonda nechanchi o‘rinda turganini aytadi. Natija — qiymatning o‘zi emas, uning <b>tartib raqami</b>. Aniq moslik uchun tur 0 beriladi.</p>\n<h4>INDEX funksiyasi</h4>\n<p><b>INDEX(diapazon; qator raqami)</b> diapazonning berilgan o‘rnidagi qiymatni qaytaradi.</p>\n<div class=\"ex\"><b>Misol.</b> A2:A10 da o‘quvchilar ismlari, C2:C10 da baholari bo‘lsin.<br>=MATCH(\"Aziz\"; A2:A10; 0) — Azizning o‘rnini topadi, aytaylik 4.<br>=INDEX(C2:C10; 4) — C ustunidagi 4-qiymatni beradi.<br>Birlashtirilgan: =INDEX(C2:C10; MATCH(\"Aziz\"; A2:A10; 0)).</div>\n<h4>Nima uchun qulay?</h4>\n<ul><li>Qidiriladigan ustun natija ustunidan chapda yoki o‘ngda bo‘lishi mumkin.</li><li>Jadvalga ustun qo‘shilsa ham, formula ishlashda davom etadi.</li></ul>\n<h4>Eslab qoling</h4><ul><li>MATCH o‘rinni topadi, INDEX shu o‘rindagi qiymatni oladi.</li><li>Aniq qidirish uchun MATCH da tur 0 qo‘yiladi.</li></ul>","quiz":[{"q":"MATCH funksiyasi nimani qaytaradi?","o":["Qiymatning diapazondagi tartib raqamini","Diapazon yig‘indisini","Qiymatning o‘zini","Katak rangini"],"a":0,"e":"MATCH o‘rin raqamini beradi."},{"q":"INDEX funksiyasi nima qiladi?","o":["Qiymatni qidirib o‘rnini aytadi","Sonni yaxlitlaydi","Diapazonning berilgan o‘rnidagi qiymatni qaytaradi","Sanani o‘zgartiradi"],"a":2,"e":"INDEX o‘rin bo‘yicha qiymat oladi."},{"q":"=INDEX(C2:C10; 4) formula nimani beradi?","o":["C ustunidagi to‘rtinchi qiymatni","To‘rtta qiymat yig‘indisini","C2 va C10 farqini","C4 katakni o‘chiradi"],"a":0,"e":"Diapazonning 4-elementi qaytariladi."},{"q":"MATCH da aniq moslikni qidirish uchun tur argumentiga nima yoziladi?","o":["10","-2","1","0"],"a":3,"e":"Aniq moslik uchun 0 qo‘yiladi."},{"q":"INDEX va MATCH birgalikda qanday ishlaydi?","o":["Ikkalasi sanani qaytaradi","INDEX o‘rinni topadi, MATCH sonni yaxlitlaydi","Ikkalasi ham yig‘indi hisoblaydi","MATCH o‘rinni topadi, INDEX shu o‘rindan qiymat oladi"],"a":3,"e":"MATCH natijasi INDEX ga qator raqami bo‘ladi."},{"q":"A2:A10 da ismlar bor. =MATCH(\"Aziz\"; A2:A10; 0) natijasi 4 bo‘ldi. Bu nimani bildiradi?","o":["Aziz 4 marta uchraydi","Azizning bahosi 4","Aziz A4 emas, A10 da","Aziz diapazonda 4-o‘rinda turibdi"],"a":3,"e":"MATCH tartib raqamini beradi."},{"q":"INDEX/MATCH ning VLOOKUP ga nisbatan afzalligi nima?","o":["Hech qachon xato bermaydi","Jadval kerak emas","Faqat sonlar bilan ishlaydi","Qidiriladigan ustun natija ustunidan chapda ham bo‘lishi mumkin"],"a":3,"e":"Bu juftlik ustunlar tartibiga bog‘liq emas."},{"q":"Qidirilgan qiymat diapazonda topilmasa, MATCH odatda nima beradi?","o":["Xato qiymati","0","Bo‘sh matn","Eng birinchi qiymat"],"a":0,"e":"Topilmasa, xato (masalan, #N/A) chiqadi."},{"q":"Ismi bo‘yicha o‘quvchining bahosini topish kerak, ismlar va baholar alohida ustunlarda. Qaysi ifoda mos?","o":["IF(ism; baholar)","TODAY(ism)","ROUND(ism; 0)","INDEX(baholar; MATCH(ism; ismlar; 0))"],"a":3,"e":"Avval ism o‘rni topiladi, keyin shu o‘rindagi baho olinadi."},{"q":"MATCH funksiyasining uchta argumenti qaysi javobda to‘g‘ri ketma-ketlikda berilgan?","o":["Diapazon, tur, qiymat","Qator, ustun, sahifa","Qidiriladigan qiymat, diapazon, tur","Tur, qiymat, rang"],"a":2,"e":"MATCH(qiymat; diapazon; tur)."}]},{"t":"42-dars. Shartli statistik funksiyalar","lesson":"<p>Ba’zan butun diapazonni emas, faqat <b>shartni qanoatlantiruvchi</b> kataklarni hisoblash kerak. Buning uchun shartli statistik funksiyalar ishlatiladi.</p>\n<h4>Asosiy funksiyalar</h4>\n<ul><li><b>COUNTIF(diapazon; shart)</b> — shartga mos kataklar sonini sanaydi.</li><li><b>SUMIF(diapazon; shart; yig‘indi diapazoni)</b> — shartga mos qiymatlar yig‘indisini topadi.</li><li><b>AVERAGEIF</b> — shartga mos qiymatlarning o‘rtachasini topadi.</li><li><b>COUNTIFS, SUMIFS, AVERAGEIFS</b> — bir nechta shart bilan.</li></ul>\n<div class=\"ex\"><b>Misol.</b> B2:B21 da o‘quvchilar baholari bor.<br>=COUNTIF(B2:B21; 5) — «5» baho olganlar soni.<br>=COUNTIF(B2:B21; \"&lt;3\") — 3 dan past baholar soni.<br>=SUMIF(A2:A21; \"Toshkent\"; C2:C21) — shahri Toshkent bo‘lgan qatorlarning C ustunidagi yig‘indisi.</div>\n<h4>Shart yozilishi</h4>\n<p>Raqam to‘g‘ridan-to‘g‘ri yoziladi, taqqoslash belgilari esa matn kabi qo‘shtirnoqda: \"&gt;100\", \"&lt;&gt;0\". Matn shartlari ham qo‘shtirnoqda yoziladi.</p>\n<h4>Eslab qoling</h4><ul><li>COUNTIF sanaydi, SUMIF qo‘shadi, AVERAGEIF o‘rtacha topadi.</li><li>Bir nechta shart uchun «IFS» turidagi funksiyalar ishlatiladi.</li></ul>","quiz":[{"q":"Shartga mos kataklar sonini sanaydigan funksiya qaysi?","o":["COUNTIF","SUMIF","MATCH","AVERAGEIF"],"a":0,"e":"COUNTIF shartli sanash uchun."},{"q":"Shartga mos qiymatlarni qo‘shadigan funksiya qaysi?","o":["SUMIF","ROUND","TODAY","COUNTIF"],"a":0,"e":"SUMIF shartli yig‘indi topadi."},{"q":"Shartga mos qiymatlarning o‘rtachasini topadigan funksiya qaysi?","o":["COUNTIF","VLOOKUP","AVERAGEIF","INDEX"],"a":2,"e":"AVERAGEIF shartli o‘rtacha hisoblaydi."},{"q":"=COUNTIF(B2:B21; 5) formula nimani hisoblaydi?","o":["Birinchi 5 ta katakni","B2:B21 oralig‘ida 5 ga teng kataklar sonini","5 ga ko‘paytirilgan yig‘indini","Hamma kataklar yig‘indisini"],"a":1,"e":"Shart bo‘yicha 5 ga teng kataklar sanaladi."},{"q":"3 dan past baholar sonini topish uchun shart qanday yoziladi?","o":["COUNT(B2:B21 > 3)","SUMIF(B2:B21; 3)","COUNTIF(B2:B21; <3 ga)","COUNTIF(B2:B21; \"<3\")"],"a":3,"e":"Taqqoslash belgisi qo‘shtirnoq ichida yoziladi."},{"q":"Bir nechta shart bo‘yicha sanash uchun qaysi funksiya ishlatiladi?","o":["COUNTIFS","ROUNDUP","IF","COUNTIF faqat"],"a":0,"e":"COUNTIFS bir necha shartni qabul qiladi."},{"q":"SUMIF ning uchinchi argumenti nimani bildiradi?","o":["Natija katakning rangini","Qo‘shtirnoq belgisini","Shart matnini","Yig‘ilishi kerak bo‘lgan qiymatlar diapazonini"],"a":3,"e":"Uchinchi argument yig‘iladigan ustunni ko‘rsatadi."},{"q":"Do‘konda sotuvlar jadvali bor. Faqat «Non» mahsulotining umumiy tushumini topish uchun qaysi funksiya mos?","o":["HLOOKUP","SUMIF","NOW","COUNTIF"],"a":1,"e":"Mahsulot nomi bo‘yicha shartli yig‘indi kerak."},{"q":"Sinfda nechta o‘quvchi «5» baho olganini bilish uchun qaysi funksiya qulay?","o":["COUNTIF","DAY","SUMIF","AVERAGEIF"],"a":0,"e":"Kataklar soni kerak, yig‘indi emas."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Shartli statistik funksiyalar faqat shartga mos kataklar bilan ishlaydi","SUMIF diapazondagi barcha qiymatlarni shartsiz qo‘shadi","COUNTIF faqat matn kataklarini sanaydi","AVERAGEIF yig‘indi beradi"],"a":0,"e":"Bu funksiyalar shart bo‘yicha saralab hisoblaydi."}]},{"t":"43-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 5</b> quyidagi darslarni qamrab oladi:</p><ul><li>Real vaqt rejimida qayta ishlash tizimi</li><li>Elektron jadval yaratish. Qatorlar va ustunlarni boshqarish</li><li>Elektron jadval xavfsizligi</li><li>Panel va oynalarni interfeysga mahkamlash</li><li>Elektron jadvalni formatlash. Shartli formatlash</li><li>Formula va funksiyalarni yaratish. Katakka absolyut va nisbiy murojaat</li><li>Nomlangan katak va diapazon</li><li>Yaxlitlash funksiyalari</li><li>Sana va vaqtga oid funksiyalar. Shartli funksiyalar. Qidirish funksiyalari</li><li>INDEX va MATCH funksiyalari</li><li>Shartli statistik funksiyalar</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"=COUNTIF(B2:B21; 5) formula nimani hisoblaydi?","o":["Birinchi 5 ta katakni","B2:B21 oralig‘ida 5 ga teng kataklar sonini","5 ga ko‘paytirilgan yig‘indini","Hamma kataklar yig‘indisini"],"a":1,"e":"Shart bo‘yicha 5 ga teng kataklar sanaladi."},{"q":"Vaziyat: ustundagi matn sig‘may qoldi. Nima qilish kerak?","o":["Dasturni yopish","Ustun kengligini oshirish","Qatorni yo‘qotish","Faylni o‘chirish"],"a":1,"e":"Kengligini o‘zgartirib, matn sig‘diriladi."},{"q":"Vaziyat: avtomobil havo yostig‘i to‘qnashuvda ishga tushishi kerak. Qaysi tizim kerak?","o":["Arxiv tizimi","Real vaqt tizimi","Paketli qayta ishlash","Oylik hisobot tizimi"],"a":1,"e":"Soniyaning ulushlarida javob kerak."},{"q":"Kuchli parol qanday bo‘ladi?","o":["Faqat 1234","Ismingiz","Faqat bitta harf","Uzun, harf, raqam va belgilar aralash"],"a":3,"e":"Murakkab parol topilishi qiyin."},{"q":"Paketli tizim real vaqt tizimidan nimasi bilan farq qiladi?","o":["Ma’lumot kelgan zahoti ishlanadi","Javob juda tez beriladi","Ma’lumot to‘planib, keyin ishlanadi","Sensorlardan foydalanadi"],"a":2,"e":"Paketli tizimda kutish bor."},{"q":"ROUNDDOWN(7,89; 1) natijasi nechaga teng?","o":["8","7,9","7,8","7,89"],"a":2,"e":"ROUNDDOWN ortiqcha xonani kattalashtirmay tashlaydi."},{"q":"MATCH da aniq moslikni qidirish uchun tur argumentiga nima yoziladi?","o":["10","-2","1","0"],"a":3,"e":"Aniq moslik uchun 0 qo‘yiladi."},{"q":"3 dan past baholar sonini topish uchun shart qanday yoziladi?","o":["COUNT(B2:B21 > 3)","SUMIF(B2:B21; 3)","COUNTIF(B2:B21; <3 ga)","COUNTIF(B2:B21; \"<3\")"],"a":3,"e":"Taqqoslash belgisi qo‘shtirnoq ichida yoziladi."},{"q":"=B2*$C$1 formula B3 ga nusxalansa, qanday ko‘rinishga keladi?","o":["=B3*$C$1","=B3*C2","=B2*$C$2","=C3*$C$1"],"a":0,"e":"Nisbiy B2 o‘zgaradi, absolyut $C$1 qoladi."},{"q":"NOW va TODAY funksiyalarining farqi nimada?","o":["Ular bir xil natija beradi","NOW faqat vaqtni, TODAY faqat yilni beradi","NOW vaqtni ham beradi, TODAY faqat sanani","TODAY sonni yaxlitlaydi"],"a":2,"e":"NOW sana va vaqtni, TODAY faqat sanani qaytaradi."},{"q":"Kamida bitta shart bajarilsa, rost beradigan funksiya qaysi?","o":["ROUND","DAY","OR","AND"],"a":2,"e":"OR kamida bitta rost shartni yetarli deb oladi."},{"q":"B3 katak qayerda joylashgan?","o":["B ustun va 3 qatorda","3 ustun va B qatorda","B qatorning oxirida","Birinchi qatorda"],"a":0,"e":"Avval ustun harfi, keyin qator raqami."},{"q":"Nomda probel ishlatsa bo‘ladimi?","o":["Yo‘q, probel o‘rniga pastki chiziq ishlatiladi","Ha, hech qanday cheklov yo‘q","Faqat ikkita probel","Faqat nomning oxirida"],"a":0,"e":"Nomda probel bo‘lishi mumkin emas."},{"q":"Panelni yig‘ish (yashirish) nimaga yordam beradi?","o":["Dasturni tezlashtirishga","Parolni almashtirishga","Faylni saqlashga","Ish maydonini kengaytirishga"],"a":3,"e":"Yashirilgan panel joy bo‘shatadi, kerak bo‘lganda qayta ochiladi."},{"q":"Funksiya nima?","o":["Katak rangi","Sahifa o‘lchami","Tayyor hisoblash vositasi","Fayl kengaytmasi"],"a":2,"e":"Funksiya berilgan qiymatlar ustida amal bajaradi."},{"q":"INDEX/MATCH ning VLOOKUP ga nisbatan afzalligi nima?","o":["Hech qachon xato bermaydi","Jadval kerak emas","Faqat sonlar bilan ishlaydi","Qidiriladigan ustun natija ustunidan chapda ham bo‘lishi mumkin"],"a":3,"e":"Bu juftlik ustunlar tartibiga bog‘liq emas."},{"q":"Nomlangan diapazon funksiyada qanday ishlatiladi?","o":["Argument sifatida: =SUM(Sotuv)","Faqat diagrammada","Faqat chop etishda","Faqat sarlavhada"],"a":0,"e":"Nom manzil o‘rnida yoziladi."},{"q":"Do‘konda narx 12,3456 so‘m chiqdi, uni tiyingacha (ikki xona) yaxlitlash kerak. Qaysi ifoda mos?","o":["INT(12,3456)","ROUND(12,3456; -2)","ROUND(12,3456; 0)","ROUND(12,3456; 2)"],"a":3,"e":"Ikki xona uchun ikkinchi argument 2 bo‘ladi."},{"q":"Quyidagilardan qaysi biri mahkamlangan panelga xos?","o":["Joyidan o‘z-o‘zidan siljimaydi","Faqat bir marta ishlatiladi","Fayl nomini yashiradi","Doim ekranning o‘rtasida suzib yuradi"],"a":0,"e":"Mahkamlangan panel o‘z o‘rnida turadi."},{"q":"Shartli formatlash qo‘llanganda katakdagi qiymat nima bo‘ladi?","o":["O‘zgarmaydi, faqat ko‘rinishi o‘zgaradi","Nolga aylanadi","Matnga aylanadi","O‘chib ketadi"],"a":0,"e":"Format faqat tashqi ko‘rinishga ta’sir qiladi."}]},{"t":"44-dars. Validatsiya qoidalari","lesson":"<p>Ma’lumotlar to‘g‘ri bo‘lmasa, undan chiqarilgan xulosa ham noto‘g‘ri bo‘ladi. <b>Validatsiya</b> — kiritilayotgan ma’lumot belgilangan qoidalarga mos ekanligini tekshirish.</p>\n<h4>Validatsiya qoidalari</h4>\n<ul><li><b>Tur tekshiruvi:</b> maydonga son kerak bo‘lsa, matn kiritib bo‘lmaydi.</li><li><b>Diapazon tekshiruvi:</b> qiymat ruxsat etilgan oraliqda bo‘lishi kerak (masalan, baho 2 dan 5 gacha).</li><li><b>Uzunlik tekshiruvi:</b> matn belgilari soni cheklanadi.</li><li><b>Ro‘yxat tekshiruvi:</b> qiymat oldindan berilgan variantlardan biri bo‘lishi kerak.</li><li><b>Majburiylik:</b> maydon bo‘sh qolmasligi shart.</li><li><b>Format tekshiruvi:</b> sana yoki telefon raqami ko‘rinishi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> «Yosh» maydoni uchun qoida: butun son, 5 dan 100 gacha. 150 yoki «yigirma» kiritilsa, tizim rad etadi va xabar ko‘rsatadi.</div>\n<h4>Validatsiya va verifikatsiya</h4>\n<p>Validatsiya ma’lumot qoidaga mosligini tekshiradi. Verifikatsiya esa ma’lumot haqiqatga to‘g‘riligini tasdiqlaydi (masalan, kiritilgan raqamni asl hujjat bilan solishtirish).</p>\n<h4>Eslab qoling</h4><ul><li>Validatsiya xatolarni kiritish vaqtida oldini oladi.</li><li>Qoida to‘g‘ri bo‘lsa ham, ma’lumot haqiqatga mos bo‘lmasligi mumkin.</li></ul>","quiz":[{"q":"Validatsiya nima?","o":["Kiritilayotgan ma’lumot qoidalarga mosligini tekshirish","Faylni arxivlash","Jadvalni chop etish","Ma’lumotni rangli qilish"],"a":0,"e":"Validatsiya qoidaga muvofiqlikni tekshiradi."},{"q":"Baho maydoniga faqat 2 dan 5 gacha son kiritishga ruxsat berish qaysi tekshiruvga misol?","o":["Diapazon tekshiruvi","Majburiylik tekshiruvi","Ro‘yxat tekshiruvi","Uzunlik tekshiruvi"],"a":0,"e":"Qiymat oraliq bilan cheklanmoqda."},{"q":"Viloyat nomini oldindan berilgan ro‘yxatdan tanlash qaysi tekshiruv turi?","o":["Diapazon tekshiruvi","Uzunlik tekshiruvi","Tur tekshiruvi","Ro‘yxat tekshiruvi"],"a":3,"e":"Qiymat tayyor variantlardan olinadi."},{"q":"«Maydon bo‘sh qolmasligi kerak» qoidasi qanday ataladi?","o":["Majburiylik","Saralash","Format","Diapazon"],"a":0,"e":"Majburiy maydon to‘ldirilishi shart."},{"q":"Telefon raqami faqat 9 ta raqamdan iborat bo‘lishini tekshirish qaysi turga yaqin?","o":["Ro‘yxat tekshiruvi","Majburiy yig‘indi","Diapazon tekshiruvi sana uchun","Uzunlik va format tekshiruvi"],"a":3,"e":"Belgilar soni va ko‘rinishi tekshiriladi."},{"q":"Son kerak bo‘lgan maydonga «yigirma» yozish mumkinmi?","o":["Ha, har doim","Faqat chorshanba kuni","Yo‘q, tur tekshiruvi buni rad etadi","Faqat bosh harf bilan"],"a":2,"e":"Tur tekshiruvi matnni rad etadi."},{"q":"Validatsiya va verifikatsiya o‘rtasidagi farq nima?","o":["Ular bir xil narsa","Verifikatsiya faqat parol uchun","Validatsiya qoidaga moslikni, verifikatsiya haqiqatga to‘g‘rilikni tekshiradi","Validatsiya faqat rasmlar uchun"],"a":2,"e":"Ikki tushuncha turli maqsadga ega."},{"q":"Foydalanuvchi 17.02.2020 sanani «yosh» maydoniga yozmoqchi. Qaysi qoida buni to‘xtatadi?","o":["Chop etish sozlamasi","Tur va diapazon tekshiruvi","Shrift tekshiruvi","Rang tekshiruvi"],"a":1,"e":"Yosh butun son va oraliqda bo‘lishi kerak."},{"q":"Validatsiya qachon samaraliroq?","o":["Fayl o‘chirilgandan keyin","Hech qachon","Ma’lumot kiritilayotgan paytda","Kompyuter o‘chirilganda"],"a":2,"e":"Xato kiritishning o‘zida oldi olinadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Validatsiya faqat sonlar uchun","Validatsiya ma’lumotni o‘chiradi","Validatsiyadan o‘tgan ma’lumot ham noto‘g‘ri bo‘lishi mumkin","Validatsiyadan o‘tgan ma’lumot doim haqiqatga mos"],"a":2,"e":"Masalan, 5 dan 100 gacha yosh qoidasi 40 deb noto‘g‘ri yozilgan yoshni ham o‘tkazadi."}]},{"t":"45-dars. Elektron jadvalga qo‘llanadigan validatsiya","lesson":"<p>Elektron jadvallarda validatsiya <b>ma’lumotlarni tekshirish</b> vositasi orqali o‘rnatiladi. Katak yoki diapazon belgilanadi, so‘ng unga qoida beriladi.</p>\n<h4>Qoidani o‘rnatish bosqichlari</h4>\n<ol><li>Tekshiriladigan katak yoki diapazonni belgilang.</li><li>Ma’lumotlar bo‘limidagi ma’lumotlarni tekshirish vositasini oching.</li><li>Ruxsat etiladigan tur: butun son, o‘nli son, ro‘yxat, sana, vaqt, matn uzunligi yoki boshqa formula.</li><li>Shartni (masalan, orasida, katta, teng) va chegara qiymatlarini kiriting.</li><li>Kerak bo‘lsa, kiritish ko‘rsatmasi va xato xabarini yozing.</li></ol>\n<div class=\"ex\"><b>Misol.</b> Baholar ustuni uchun: butun son, 2 dan 5 gacha. Xato xabari: «Baho 2 dan 5 gacha bo‘lsin». Ro‘yxat uchun: «Sinf» katagiga 10-A, 10-B, 10-D variantlarini kiritsangiz, katakda ro‘yxatdan tanlash paydo bo‘ladi.</div>\n<h4>Xato xabarlari</h4>\n<ul><li>To‘xtatish — noto‘g‘ri qiymatni umuman qabul qilmaydi.</li><li>Ogohlantirish va ma’lumot — foydalanuvchiga tanlov beradi yoki faqat xabardor qiladi.</li></ul>\n<h4>Eslab qoling</h4><ul><li>Qoida avval katakka qo‘llanadi, keyin kiritish tekshiriladi.</li><li>Ro‘yxat orqali tanlash imlo xatolarini kamaytiradi.</li></ul>","quiz":[{"q":"Validatsiya qoidasini o‘rnatishdan oldin nima qilinadi?","o":["Fayl o‘chiriladi","Tekshiriladigan katak yoki diapazon belgilanadi","Jadval chop etiladi","Shrift o‘zgartiriladi"],"a":1,"e":"Qoida belgilangan kataklarga qo‘llanadi."},{"q":"Ro‘yxatdan tanlash ko‘rinishidagi qoida nima uchun foydali?","o":["Imlo va kiritish xatolarini kamaytiradi","Ranglarni almashtiradi","Formulalarni o‘chiradi","Faylni kichraytiradi"],"a":0,"e":"Faqat tayyor variantlar tanlanadi."},{"q":"Noto‘g‘ri qiymatni umuman qabul qilmaydigan xato turi qaysi?","o":["To‘xtatish","Eslatma","Ogohlantirish","Ma’lumot"],"a":0,"e":"To‘xtatish kiritishga yo‘l bermaydi."},{"q":"Baho ustuniga 2 dan 5 gacha butun son qoidasi o‘rnatilgan. 7 kiritilsa, nima bo‘ladi?","o":["Xato xabari chiqadi va qiymat rad etiladi","Qiymat 5 ga aylanadi","Qiymat qabul qilinadi","Jadval o‘chadi"],"a":0,"e":"To‘xtatish turida noto‘g‘ri qiymat qabul qilinmaydi."},{"q":"Kiritish ko‘rsatmasi nima uchun yoziladi?","o":["Katak rangini o‘zgartirish uchun","Foydalanuvchiga qanday qiymat kerakligini aytish uchun","Saralash uchun","Formulani yashirish uchun"],"a":1,"e":"Ko‘rsatma kiritishdan oldin yo‘l-yo‘riq beradi."},{"q":"Quyidagilardan qaysi biri ruxsat etiladigan turga kirmaydi?","o":["Rasm o‘lchami","Butun son","Sana","Matn uzunligi"],"a":0,"e":"Qolganlari tekshirish turlari."},{"q":"Validatsiya qoidasi o‘rnatilgan katakdagi qiymatlarning hammasi darhol tekshiriladimi?","o":["Faqat formulalar tekshiriladi","Hech narsa tekshirilmaydi","Hamma eski qiymatlar avtomatik o‘chadi","Qoida asosan yangi kiritilayotgan qiymatlarga ta’sir qiladi"],"a":3,"e":"Oldin kiritilgan qiymatlar o‘z-o‘zidan o‘zgarmaydi."},{"q":"Katakka faqat sana kiritishga ruxsat berish uchun qaysi tur tanlanadi?","o":["Sana","Matn uzunligi","Butun son","Ro‘yxat"],"a":0,"e":"Sana turi sana shaklidagi qiymatlarni qabul qiladi."},{"q":"Sinf nomi uchun (10-A, 10-B, 10-D) qaysi turni tanlash qulay?","o":["Ro‘yxat","Sana","Vaqt","O‘nli son"],"a":0,"e":"Variantlar oldindan ma’lum."},{"q":"Xato xabarini yozish nimaga xizmat qiladi?","o":["Faylni tezlashtiradi","Kiritish nima uchun rad etilganini tushuntiradi","Ma’lumotni shifrlaydi","Jadvalni nusxalaydi"],"a":1,"e":"Foydalanuvchi xatosini tuzatishi uchun kerak."}]},{"t":"46-dars. Ma‘lumotlar kiritilishini tekshirish","lesson":"<p>Ma’lumotlar kiritilishini tekshirish faqat dasturiy qoidalar bilan cheklanmaydi. Kiritish jarayonining o‘zi to‘g‘ri tashkil etilishi kerak.</p>\n<h4>Tekshirish usullari</h4>\n<ul><li><b>Validatsiya qoidalari:</b> tur, oraliq, uzunlik, ro‘yxat.</li><li><b>Ikki marta kiritish:</b> bir xil ma’lumot ikki marta kiritilib, mos kelishi tekshiriladi (parolni tasdiqlash kabi).</li><li><b>Nazorat raqami:</b> kod oxiriga qo‘shiladigan raqam yordamida xatolarni topish.</li><li><b>Vizual tekshiruv:</b> kiritilgan ma’lumotni asl manba bilan solishtirish — bu verifikatsiya.</li><li><b>Ko‘rib chiqish:</b> ikkinchi shaxs tekshirishi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Registratsiya shaklida elektron pochta manzilida «@» belgisi borligi, parol esa ikki marta bir xil kiritilganligi tekshiriladi.</div>\n<h4>Foydalanuvchi uchun qulaylik</h4>\n<ul><li>Maydonlarga tushunarli nom va namuna yozish.</li><li>Tayyor ro‘yxatdan tanlash.</li><li>Xato haqida aniq xabar berish.</li></ul>\n<h4>Eslab qoling</h4><ul><li>Kiritishda xatolar odatiy hol — ularni oldindan kamaytirish kerak.</li><li>Dasturiy tekshiruv va inson tekshiruvi bir-birini to‘ldiradi.</li></ul>","quiz":[{"q":"Parolni ikki marta kiritish nima uchun talab qilinadi?","o":["Kiritishda yo‘l qo‘yilgan xatoni aniqlash uchun","Ekranni yoritish uchun","Parolni uzaytirish uchun","Faylni siqish uchun"],"a":0,"e":"Ikki yozuv mos kelmasa, xato bor."},{"q":"Kiritilgan ma’lumotni asl hujjat bilan solishtirish qanday ataladi?","o":["Filtrlash","Import","Saralash","Verifikatsiya"],"a":3,"e":"Haqiqatga mosligi tasdiqlanadi."},{"q":"Elektron pochta manzilida «@» belgisi borligini tekshirish qaysi tekshiruv turi?","o":["Format tekshiruvi","Ikki marta kiritish","Saralash","Diapazon tekshiruvi"],"a":0,"e":"Manzil ko‘rinishi tekshiriladi."},{"q":"Nazorat raqami nima uchun ishlatiladi?","o":["Ranglarni tanlash uchun","Kodni kiritishdagi xatolarni topish uchun","Diagramma chizish uchun","Faylni nusxalash uchun"],"a":1,"e":"Nazorat raqami kod to‘g‘riligini tekshirishga yordam beradi."},{"q":"Maydonga namuna yozib qo‘yish (masalan, 12.05.2010) nimaga yordam beradi?","o":["Ma’lumotni shifrlashga","Jadvalni saralashga","Foydalanuvchi to‘g‘ri formatda kiritishiga","Faylni tezlashtirishga"],"a":2,"e":"Namuna kutilgan ko‘rinishni ko‘rsatadi."},{"q":"Quyidagilardan qaysi biri kiritish xatolarini kamaytirish usuli emas?","o":["Aniq xato xabari berish","Maydon nomini tushunarli yozish","Hamma maydonni bo‘sh va izohsiz qoldirish","Tayyor ro‘yxatdan tanlash"],"a":2,"e":"Izohsiz bo‘sh maydonlar xatoni ko‘paytiradi."},{"q":"Ikkinchi shaxsning kiritilgan ma’lumotni qayta ko‘rib chiqishi nimaga misol?","o":["Inson tekshiruvi","Dasturiy validatsiya","Saralash","Shifrlash"],"a":0,"e":"Bu qo‘lda ko‘rib chiqish."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Inson tekshiruvi har doim xato beradi","Tekshirish umuman kerak emas","Dasturiy tekshiruv inson tekshiruvini butunlay almashtiradi","Dasturiy tekshiruv va inson tekshiruvi bir-birini to‘ldiradi"],"a":3,"e":"Ikkala usul birga ishonchliroq natija beradi."},{"q":"Registratsiya shaklida yosh maydoniga -5 kiritildi. Qaysi qoida buni to‘xtata oladi?","o":["Sahifa maketi","Rang tekshiruvi","Shrift tanlash","Diapazon tekshiruvi"],"a":3,"e":"Yosh manfiy bo‘la olmaydi, oraliq cheklanadi."},{"q":"Nima uchun tayyor ro‘yxatdan tanlash qulay?","o":["Ma’lumot yo‘qoladi","Fayl hajmi oshadi","Sana avtomatik o‘zgaradi","Bir xil nomlar turli yozilishining oldi olinadi"],"a":3,"e":"Imlo va yozilish farqlari bo‘lmaydi."}]},{"t":"47-dars. Ma‘lumotlarni filtrlash va saralash","lesson":"<p>Jadvalda ma’lumot ko‘paygan sari kerakli yozuvni topish qiyinlashadi. <b>Saralash</b> va <b>filtrlash</b> bu muammoni hal qiladi.</p>\n<h4>Saralash</h4>\n<p>Saralash qatorlarni tanlangan ustun qiymatiga ko‘ra tartiblaydi: matn uchun alifbo tartibida (A dan Z gacha yoki teskari), sonlar uchun o‘sish yoki kamayish bo‘yicha. Bir necha ustun bo‘yicha ham saralash mumkin: masalan, avval sinf bo‘yicha, keyin ball bo‘yicha.</p>\n<h4>Filtrlash</h4>\n<p>Filtr faqat shartga mos qatorlarni ko‘rsatadi, qolganlari vaqtincha yashiriladi (o‘chmaydi). Filtr ustun sarlavhasidagi tugma orqali o‘rnatiladi.</p>\n<div class=\"ex\"><b>Misol.</b> O‘quvchilar jadvalida «Sinf» ustunida 10-A tanlansa, faqat shu sinf qatorlari ko‘rinadi. Ball ustunida «eng yuqori 10» filtrini qo‘shsak, shu sinfning eng yaxshi o‘nta o‘quvchisini ko‘ramiz.</div>\n<h4>Muhim qoidalar</h4>\n<ul><li>Ma’lumotlar sarlavha qatori bilan to‘liq diapazon sifatida belgilanishi kerak, aks holda ustunlar aralashib ketadi.</li><li>Filtrni olib tashlash barcha qatorlarni qaytaradi.</li></ul>\n<h4>Eslab qoling</h4><ul><li>Saralash tartibni, filtr ko‘rinishni o‘zgartiradi.</li><li>Filtr ma’lumotni o‘chirmaydi.</li></ul>","quiz":[{"q":"Saralash nima qiladi?","o":["Qatorlarni tanlangan ustun bo‘yicha tartiblaydi","Formulalarni yaratadi","Qatorlarni o‘chiradi","Diagramma chizadi"],"a":0,"e":"Saralash tartibni o‘zgartiradi."},{"q":"Filtr nima qiladi?","o":["Qiymatlarni yaxlitlaydi","Qatorlarni butunlay o‘chiradi","Shartga mos qatorlarni ko‘rsatadi, qolganini yashiradi","Jadvalni boshqa faylga ko‘chiradi"],"a":2,"e":"Filtrlangan qatorlar yashirinadi, o‘chmaydi."},{"q":"Filtr olib tashlansa, yashirilgan qatorlar nima bo‘ladi?","o":["Nolga aylanadi","Qaytadan ko‘rinadi","Butunlay yo‘qoladi","Matnga aylanadi"],"a":1,"e":"Ma’lumot hech qachon o‘chmagan."},{"q":"Sonlarni kamayish tartibida saralash qanday natija beradi?","o":["Eng kichigi tepada bo‘ladi","Hammasi nolga aylanadi","Tartib o‘zgarmaydi","Eng kattasi tepada bo‘ladi"],"a":3,"e":"Kamayish tartibi kattadan kichikka."},{"q":"Avval sinf, so‘ng ball bo‘yicha saralash nima deb ataladi?","o":["Formulali saralash","Katak birlashtirish","Bir martalik filtr","Bir necha ustun bo‘yicha saralash"],"a":3,"e":"Ikki saralash darajasi beriladi."},{"q":"Saralashda sarlavhasiz ustunni alohida belgilab saralasak, qanday xato yuz berishi mumkin?","o":["Fayl o‘chib ketadi","Ma’lumotlar qatorlari aralashib ketadi","Dastur yopiladi","Ranglar o‘zgaradi"],"a":1,"e":"Qatorlar bir-biriga bog‘liqligi buziladi."},{"q":"Faqat 10-A sinf o‘quvchilarini ko‘rish uchun nima ishlatiladi?","o":["Yaxlitlash","Filtr","Katakni birlashtirish","Sahifa maketi"],"a":1,"e":"Shart bo‘yicha qatorlar ko‘rsatiladi."},{"q":"Matn ustunini alifbo tartibida saralashning bir turi qaysi?","o":["Eng katta qiymat","Ma’lumot chizig‘i","Pul formati","A dan Z gacha"],"a":3,"e":"Matnlar alifbo bo‘yicha tartiblanadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Saralash qiymatlarni o‘zgartiradi","Filtr yashirilgan qatorlarni butunlay o‘chiradi","Filtr ma’lumotni o‘chirmaydi, faqat ko‘rinishini cheklaydi","Filtr faqat sonlar uchun ishlaydi"],"a":2,"e":"Qatorlar filtr o‘chirilganda qaytadi."},{"q":"Eng yuqori ball olgan 10 o‘quvchini ko‘rsatish uchun nima qo‘llanadi?","o":["Shrift o‘lchami","Matnni o‘rash","Eng yuqori qiymatlar filtri","Katak chegarasi"],"a":2,"e":"Bunday filtr eng katta qiymatlarni ajratadi."}]},{"t":"48-dars. Jamlovchi jadvallar va diagrammalar","lesson":"<p>Katta jadvaldan xulosa chiqarish uchun ma’lumotni jamlab ko‘rsatish kerak. Buning ikki qulay vositasi — <b>jamlovchi jadval</b> va <b>diagramma</b>.</p>\n<h4>Jamlovchi jadval</h4>\n<p>Bu manba jadvaldagi ma’lumotlarni toifalar bo‘yicha jamlaydigan yangi jadval: yig‘indi, o‘rtacha, soni, eng katta yoki eng kichik qiymat. Formula yozmasdan, maydonlarni qator, ustun va qiymat sohalariga sudrab joylashtirish bilan tuziladi.</p>\n<div class=\"ex\"><b>Misol.</b> Savdo jadvalida sana, mahsulot, filial va summa bor. Jamlovchi jadvalda qatorlarga «Filial», ustunlarga «Mahsulot», qiymatlarga «Summa yig‘indisi» qo‘yiladi — har filialning har mahsulot bo‘yicha savdosi ko‘rinadi.</div>\n<p>Manba o‘zgarsa, jamlovchi jadval avtomatik yangilanmaydi — uni yangilash kerak bo‘ladi.</p>\n<h4>Diagrammalar</h4>\n<ul><li><b>Ustunli:</b> toifalarni taqqoslash.</li><li><b>Chiziqli:</b> vaqt bo‘yicha o‘zgarish.</li><li><b>Doiraviy:</b> butunning qismlari ulushi.</li></ul>\n<p>Diagrammaga sarlavha, o‘qlar nomi va kerak bo‘lsa, izoh qo‘shiladi.</p>\n<h4>Eslab qoling</h4><ul><li>Jamlovchi jadval ma’lumotni toifalar bo‘yicha jamlaydi.</li><li>Diagramma turi ma’lumot xususiyatiga mos tanlanadi.</li></ul>","quiz":[{"q":"Jamlovchi jadval nima uchun ishlatiladi?","o":["Faylni himoyalash uchun","Rasm chizish uchun","Matnni tahrirlash uchun","Ma’lumotni toifalar bo‘yicha jamlab ko‘rsatish uchun"],"a":3,"e":"U yig‘indi, o‘rtacha va boshqalarni toifalarda beradi."},{"q":"Jamlovchi jadvalni tuzish uchun nimalar kerak?","o":["Jadvalni bosib chiqarish","Har bir katakka qo‘lda formula yozish","Maydonlarni qator, ustun va qiymat sohalariga joylashtirish","Parol o‘rnatish"],"a":2,"e":"Maydonlar sudralib joylashtiriladi."},{"q":"Vaqt bo‘yicha o‘zgarishni ko‘rsatish uchun qaysi diagramma qulay?","o":["Chiziqli","Piktogramma","Doiraviy","Ustunli faqat bitta toifa"],"a":0,"e":"Chiziqli diagramma dinamikani ko‘rsatadi."},{"q":"Butunning qismlari ulushini ko‘rsatish uchun qaysi diagramma mos?","o":["Chiziqli","Tarqoq nuqtali","Saralash","Doiraviy"],"a":3,"e":"Doira ulushlarni ko‘rsatadi."},{"q":"Toifalarni (masalan, filiallarni) taqqoslash uchun qaysi diagramma mos?","o":["Doiraviy 50 qism bilan","Rasmli","Ustunli","Faqat jadval"],"a":2,"e":"Ustunli diagramma toifalarni solishtiradi."},{"q":"Jamlovchi jadvalda manba ma’lumot o‘zgarsa, nima qilish kerak?","o":["Faylni o‘chirish kerak","Hech narsa kerak emas","Yangi diagramma chizish shart","Jamlovchi jadvalni yangilash kerak"],"a":3,"e":"Jamlovchi jadval odatda qo‘lda yangilanadi."},{"q":"Diagrammaga nima qo‘shish uni tushunarli qiladi?","o":["Parol","Qo‘shimcha varaq","Faylga rasm","Sarlavha va o‘qlar nomi"],"a":3,"e":"Sarlavha va nomlar diagramma mazmunini tushuntiradi."},{"q":"Savdo jadvalidan har filialning umumiy tushumini tez olish uchun nima ishlatiladi?","o":["Shartli format","Sahifa maketi","Katakni birlashtirish","Jamlovchi jadval"],"a":3,"e":"Filial bo‘yicha yig‘indi topiladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Jamlovchi jadval manba ma’lumotni o‘chiradi","Jamlovchi jadval manba ma’lumotni o‘zgartirmaydi","Diagramma faqat bitta turda bo‘ladi","Jamlovchi jadval faqat matn bilan ishlaydi"],"a":1,"e":"U manbaning jamlangan ko‘rinishini yaratadi."},{"q":"Jamlovchi jadvalda qiymatlar sohasida qaysi hisoblash turini tanlash mumkin?","o":["Faqat matn shrifti","Yig‘indi, o‘rtacha yoki soni","Faqat rang","Faqat sahifa raqami"],"a":1,"e":"Qiymatlarga hisoblash turi qo‘llanadi."}]},{"t":"49-dars. Ma‘lumotlarni import va eksport qilish","lesson":"<p>Ma’lumotlarni import qilish — boshqa fayl yoki dasturdagi ma’lumotlarni jadvalga olib kirish, eksport qilish esa jadvaldagi ma’lumotlarni boshqa formatda tashqariga chiqarish demakdir. Bu dasturlar o‘rtasida ma’lumot almashishni osonlashtiradi.</p>\n<h4>Import</h4>\n<ul><li>Matnli fayl (TXT, CSV) yoki boshqa jadval faylidan ma’lumot olinadi.</li><li>CSV faylida qiymatlar odatda vergul yoki boshqa ajratuvchi bilan ajratilgan bo‘ladi.</li><li>Import paytida ajratuvchi va ma’lumot turi (matn, son, sana) to‘g‘ri tanlanishi kerak.</li></ul>\n<h4>Eksport</h4>\n<ul><li>Jadval CSV, PDF, TXT yoki boshqa formatda saqlanadi.</li><li>PDF o‘zgartirish uchun emas, ko‘rish va chop etish uchun qulay.</li><li>CSV boshqa dasturlarga ma’lumot uzatishda keng qo‘llanadi.</li></ul>\n<h4>Tekshirish</h4>\n<ul><li>Importdan keyin ma’lumotlar to‘g‘ri joylashganini tekshiring.</li><li>Sanalar va sonlar matn bo‘lib qolmaganini ko‘ring.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Bank hisobotini CSV fayl ko‘rinishida yuklab, elektron jadvalga import qilasiz va unda hisob-kitob qilasiz. Natijani esa PDF qilib eksport qilib, boshqalarga yuborasiz.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Import — ma’lumotni olib kirish.</li><li>Eksport — ma’lumotni chiqarish.</li><li>CSV — oddiy matnli jadval formati.</li></ul>","quiz":[{"q":"Import qilish nima?","o":["Parol qo‘yish","Jadvalni chop etish","Jadvalni o‘chirish","Tashqi ma’lumotni jadvalga olib kirish"],"a":3,"e":"Import — tashqaridan olib kirish."},{"q":"Eksport qilish nima?","o":["Ma’lumotni o‘chirish","Jadval ma’lumotini boshqa formatda tashqariga chiqarish","Faqat jadvalga rasm qo‘yish","Jadvalni yashirish"],"a":1,"e":"Eksport — tashqariga chiqarish."},{"q":"CSV fayl qanday?","o":["Faqat audio fayl","Faqat video fayl","Faqat rasm fayli","Qiymatlari ajratuvchi bilan ajratilgan matnli fayl"],"a":3,"e":"CSV oddiy matnli jadval formati."},{"q":"PDF formatida eksport qilish nima uchun qulay?","o":["Ko‘rish va chop etish uchun","Ma’lumotni tahlil qilish uchun","Formulalarni tahrirlash uchun","Jadvalga formula yozish uchun"],"a":0,"e":"PDF o‘zgartirish uchun emas, ko‘rsatish uchun."},{"q":"Import paytida nimani to‘g‘ri tanlash kerak?","o":["Ekran rangini","Printer nomini","Ajratuvchi va ma’lumot turini","Klaviatura tilini faqat"],"a":2,"e":"Noto‘g‘ri tanlansa, ma’lumot buziladi."},{"q":"Vaziyat: import qilingan sanalar matn bo‘lib qolgan. Nima qilinadi?","o":["Hech narsa qilinmaydi","Rang beriladi","Ustun turini sanaga o‘zgartirib tekshiriladi","Jadval o‘chiriladi"],"a":2,"e":"Ma’lumot turi to‘g‘rilanishi kerak."},{"q":"Ma’lumotlar boshqa dasturga uzatiladi. Qaysi format keng ishlatiladi?","o":["CSV","ISO","EXE","MP3"],"a":0,"e":"CSV ko‘p dastur tomonidan tushuniladi."},{"q":"Importdan keyin nima qilish tavsiya etiladi?","o":["Faylni darhol o‘chirish","Ma’lumotlarning to‘g‘ri joylashganini tekshirish","Parol qo‘yish","Tekshirmasdan formula yozish"],"a":1,"e":"Xatolarni erta topish uchun tekshiriladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Import va eksport bir xil","Eksport jadvaldan ma’lumotni tashqariga chiqaradi","Eksport tashqaridan ma’lumot olib kiradi","Import jadvaldan ma’lumotni olib chiqadi"],"a":1,"e":"Import kirish, eksport chiqish."},{"q":"Import/eksport qanday imkoniyat beradi?","o":["Tarmoqni uzish","Dasturlar o‘rtasida ma’lumot almashish","Dasturni o‘chirish","Fayl nomini yashirish"],"a":1,"e":"Ma’lumot almashishni osonlashtiradi."}]},{"t":"50-dars. Grafik va diagrammalar. Modellashtirish. Simulyatorlar","lesson":"<p>Grafik va diagrammalar jadvaldagi sonlarni ko‘rgazmali ko‘rsatadi. Modellashtirish esa real jarayonni soddalashtirilgan ko‘rinishda kompyuterda tasvirlash va tadqiq etishdir. Simulyator modelni ishlatib, jarayonni sinash imkonini beradi.</p>\n<h4>Grafik va diagrammalar</h4>\n<ul><li>Ustunli diagramma qiymatlarni solishtiradi.</li><li>Doiraviy diagramma qismlarning ulushini ko‘rsatadi.</li><li>Chiziqli grafik o‘zgarishni vaqt bo‘yicha ko‘rsatadi.</li><li>Diagramma sarlavha, o‘qlar nomi va izohlarga ega bo‘lishi kerak.</li></ul>\n<h4>Modellashtirish</h4>\n<ul><li>Model — haqiqiy obyekt yoki jarayonning soddalashtirilgan nusxasi.</li><li>Elektron jadvalda parametrlarni o‘zgartirib, natija qanday o‘zgarishini ko‘rish mumkin.</li><li>Model real hayotdagi tajribadan arzon va xavfsiz.</li></ul>\n<h4>Simulyatorlar</h4>\n<ul><li>Simulyator real vaziyatni kompyuterda taqlid qiladi.</li><li>Masalan, uchuvchilar yoki haydovchilarni o‘qitishda ishlatiladi.</li><li>Xatolar real oqibatga olib kelmaydi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Kreditning oylik to‘lovi uchun jadval modeli yaratiladi: foiz yoki muddat o‘zgartirilsa, to‘lov summasi avtomatik o‘zgaradi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Diagramma ma’lumotga mos turda tanlanadi.</li><li>Model real jarayonning soddalashtirilgan ko‘rinishi.</li><li>Simulyator xavfsiz mashq imkonini beradi.</li></ul>","quiz":[{"q":"Vaqt bo‘yicha o‘zgarishni ko‘rsatish uchun qaysi diagramma mos?","o":["Chiziqli grafik","Faqat jadval","Rasm","Doiraviy diagramma"],"a":0,"e":"Grafik o‘zgarishni ko‘rsatadi."},{"q":"Qismlarning ulushini ko‘rsatish uchun qaysi diagramma mos?","o":["Faqat sarlavha","Formula","Doiraviy diagramma","Chiziqli grafik"],"a":2,"e":"Doiraviy diagramma ulushni ko‘rsatadi."},{"q":"Qiymatlarni solishtirish uchun qaysi diagramma mos?","o":["Ovozli yozuv","Ustunli diagramma","Havola","Faqat matn"],"a":1,"e":"Ustunlar balandligi solishtiriladi."},{"q":"Model nima?","o":["Haqiqiy obyektning o‘zi","Obyekt yoki jarayonning soddalashtirilgan nusxasi","Faqat rasm fayli","Faqat dastur nomi"],"a":1,"e":"Model asl nusxani soddalashtiradi."},{"q":"Modellashtirishning afzalligi qaysi?","o":["Doim real tajribadan qimmat","Natija bo‘lmasligi","Faqat chiroyli rasm","Arzon va xavfsiz tajriba qilish imkoni"],"a":3,"e":"Modelda tajriba xavfsiz."},{"q":"Simulyator nima qiladi?","o":["Parolni buzadi","Faylni arxivlaydi","Ekranni tozalaydi","Real vaziyatni kompyuterda taqlid qiladi"],"a":3,"e":"Simulyator taqlid qiladi."},{"q":"Simulyatordan qayerda foydalaniladi?","o":["Faqat kabel tortishda","Faqat rasm chop etishda","Uchuvchi va haydovchilarni o‘qitishda","Faqat fayl nomlashda"],"a":2,"e":"Xavfsiz mashq uchun ishlatiladi."},{"q":"Vaziyat: foiz stavkasini o‘zgartirganda kredit to‘lovi avtomatik o‘zgardi. Bu nima?","o":["Virus ta’siri","Xotira yetishmasligi","Jadvaldagi model ishlashi","Tarmoq xatosi"],"a":2,"e":"Parametr o‘zgarishi natijani yangilaydi."},{"q":"Diagrammada nima bo‘lishi kerak?","o":["Hech qanday yozuv","Faqat bezak","Tasodifiy rasm","Sarlavha va izohlar"],"a":3,"e":"Izoh tushunarlilikni oshiradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Diagramma ma’lumotsiz chiziladi","Model haqiqiy jarayondan soddaroq bo‘ladi","Model har doim asl nusxa bilan bir xil","Simulyatorda xatolar real oqibatga olib keladi"],"a":1,"e":"Model soddalashtirilgan."}]},{"t":"51-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 6</b> quyidagi darslarni qamrab oladi:</p><ul><li>Validatsiya qoidalari</li><li>Elektron jadvalga qo‘llanadigan validatsiya</li><li>Ma‘lumotlar kiritilishini tekshirish</li><li>Ma‘lumotlarni filtrlash va saralash</li><li>Jamlovchi jadvallar va diagrammalar</li><li>Ma‘lumotlarni import va eksport qilish</li><li>Grafik va diagrammalar. Modellashtirish. Simulyatorlar</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Jamlovchi jadvalda manba ma’lumot o‘zgarsa, nima qilish kerak?","o":["Faylni o‘chirish kerak","Hech narsa kerak emas","Yangi diagramma chizish shart","Jamlovchi jadvalni yangilash kerak"],"a":3,"e":"Jamlovchi jadval odatda qo‘lda yangilanadi."},{"q":"Viloyat nomini oldindan berilgan ro‘yxatdan tanlash qaysi tekshiruv turi?","o":["Diapazon tekshiruvi","Uzunlik tekshiruvi","Tur tekshiruvi","Ro‘yxat tekshiruvi"],"a":3,"e":"Qiymat tayyor variantlardan olinadi."},{"q":"Validatsiya qoidasini o‘rnatishdan oldin nima qilinadi?","o":["Fayl o‘chiriladi","Tekshiriladigan katak yoki diapazon belgilanadi","Jadval chop etiladi","Shrift o‘zgartiriladi"],"a":1,"e":"Qoida belgilangan kataklarga qo‘llanadi."},{"q":"Kiritilgan ma’lumotni asl hujjat bilan solishtirish qanday ataladi?","o":["Filtrlash","Import","Saralash","Verifikatsiya"],"a":3,"e":"Haqiqatga mosligi tasdiqlanadi."},{"q":"Import/eksport qanday imkoniyat beradi?","o":["Tarmoqni uzish","Dasturlar o‘rtasida ma’lumot almashish","Dasturni o‘chirish","Fayl nomini yashirish"],"a":1,"e":"Ma’lumot almashishni osonlashtiradi."},{"q":"Validatsiya qachon samaraliroq?","o":["Fayl o‘chirilgandan keyin","Hech qachon","Ma’lumot kiritilayotgan paytda","Kompyuter o‘chirilganda"],"a":2,"e":"Xato kiritishning o‘zida oldi olinadi."},{"q":"Parolni ikki marta kiritish nima uchun talab qilinadi?","o":["Kiritishda yo‘l qo‘yilgan xatoni aniqlash uchun","Ekranni yoritish uchun","Parolni uzaytirish uchun","Faylni siqish uchun"],"a":0,"e":"Ikki yozuv mos kelmasa, xato bor."},{"q":"Ro‘yxatdan tanlash ko‘rinishidagi qoida nima uchun foydali?","o":["Imlo va kiritish xatolarini kamaytiradi","Ranglarni almashtiradi","Formulalarni o‘chiradi","Faylni kichraytiradi"],"a":0,"e":"Faqat tayyor variantlar tanlanadi."},{"q":"Quyidagilardan qaysi biri kiritish xatolarini kamaytirish usuli emas?","o":["Aniq xato xabari berish","Maydon nomini tushunarli yozish","Hamma maydonni bo‘sh va izohsiz qoldirish","Tayyor ro‘yxatdan tanlash"],"a":2,"e":"Izohsiz bo‘sh maydonlar xatoni ko‘paytiradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Jamlovchi jadval manba ma’lumotni o‘chiradi","Jamlovchi jadval manba ma’lumotni o‘zgartirmaydi","Diagramma faqat bitta turda bo‘ladi","Jamlovchi jadval faqat matn bilan ishlaydi"],"a":1,"e":"U manbaning jamlangan ko‘rinishini yaratadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Import va eksport bir xil","Eksport jadvaldan ma’lumotni tashqariga chiqaradi","Eksport tashqaridan ma’lumot olib kiradi","Import jadvaldan ma’lumotni olib chiqadi"],"a":1,"e":"Import kirish, eksport chiqish."},{"q":"Noto‘g‘ri qiymatni umuman qabul qilmaydigan xato turi qaysi?","o":["To‘xtatish","Eslatma","Ogohlantirish","Ma’lumot"],"a":0,"e":"To‘xtatish kiritishga yo‘l bermaydi."},{"q":"Saralash nima qiladi?","o":["Qatorlarni tanlangan ustun bo‘yicha tartiblaydi","Formulalarni yaratadi","Qatorlarni o‘chiradi","Diagramma chizadi"],"a":0,"e":"Saralash tartibni o‘zgartiradi."},{"q":"Eng yuqori ball olgan 10 o‘quvchini ko‘rsatish uchun nima qo‘llanadi?","o":["Shrift o‘lchami","Matnni o‘rash","Eng yuqori qiymatlar filtri","Katak chegarasi"],"a":2,"e":"Bunday filtr eng katta qiymatlarni ajratadi."},{"q":"Qiymatlarni solishtirish uchun qaysi diagramma mos?","o":["Ovozli yozuv","Ustunli diagramma","Havola","Faqat matn"],"a":1,"e":"Ustunlar balandligi solishtiriladi."},{"q":"Importdan keyin nima qilish tavsiya etiladi?","o":["Faylni darhol o‘chirish","Ma’lumotlarning to‘g‘ri joylashganini tekshirish","Parol qo‘yish","Tekshirmasdan formula yozish"],"a":1,"e":"Xatolarni erta topish uchun tekshiriladi."},{"q":"Validatsiya va verifikatsiya o‘rtasidagi farq nima?","o":["Ular bir xil narsa","Verifikatsiya faqat parol uchun","Validatsiya qoidaga moslikni, verifikatsiya haqiqatga to‘g‘rilikni tekshiradi","Validatsiya faqat rasmlar uchun"],"a":2,"e":"Ikki tushuncha turli maqsadga ega."},{"q":"Jamlovchi jadvalda qiymatlar sohasida qaysi hisoblash turini tanlash mumkin?","o":["Faqat matn shrifti","Yig‘indi, o‘rtacha yoki soni","Faqat rang","Faqat sahifa raqami"],"a":1,"e":"Qiymatlarga hisoblash turi qo‘llanadi."},{"q":"Faqat 10-A sinf o‘quvchilarini ko‘rish uchun nima ishlatiladi?","o":["Yaxlitlash","Filtr","Katakni birlashtirish","Sahifa maketi"],"a":1,"e":"Shart bo‘yicha qatorlar ko‘rsatiladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Diagramma ma’lumotsiz chiziladi","Model haqiqiy jarayondan soddaroq bo‘ladi","Model har doim asl nusxa bilan bir xil","Simulyatorda xatolar real oqibatga olib keladi"],"a":1,"e":"Model soddalashtirilgan."}]},{"t":"52-dars. Takrorlash","lesson":"<p><b>Takrorlash</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ma‘lumot, axborot va bilimlar bazasi. Ma‘lumot manbasi. Bevosita va bilvosita manbalardan ma‘lumot to‘plashning afzallik hamda kamchiliklari. Axborotning sifati</li><li>Kod berish, kodlash va shifrlash. Ma‘lumotlarni kodlashning afzallik va kamchiliklari. Simmetrik va asimmetrik shifrlash usullari.</li><li>Ma‘lumotlarning to‘g‘riligini tekshirish.</li><li>Vizual tekshirish va ma‘lumotlanri ikki marta kiritish.</li><li>Apparat ta‘minot. Ichki va tashqi qurilmalar</li><li>Xotira qurilmalari. Tizimli dasturiy ta‘minot. Drayverlar.</li><li>Amaliy dasturiy ta‘minot. Fotosuratni tahrirlash dasturiy ta‘minoti</li><li>Video tahrirlash dasturiy ta‘minoti. Veb sahifa ishlab chiqish dasturiy ta‘minoti</li><li>Foydalanuvchi interfeysi dizaynidagi boshqaruv elementlari. Utilit dasturlar. Buyurtma yoki tayyor dasturiy ta‘minot.</li><li>Loyiha (amaliy) ishi</li><li>Sensorlar. Harakat va bosim sensorlari, Namlik, harorat va yorug‘lik sensorlari</li><li>Elektron xavfsizlik tushunchasi.</li><li>Phishing, Pharming, Vishing, Troyan, Worm, Spyware, Rootkit, Adware, Ransomware tushunchalari va xavfsizlikni ta‘minlash.</li><li>Salomatlik va xavfsizlik.</li><li>Raqamli tengsizlik tushunchasi va sabablari, Sanoati rivojlangan va rivojlanmagan hududlar, Ijtimoiy-iqtisodiy guruhlar.</li><li>Samarasi yuqori va past bo‘lgan texnologiyalar. Turli davlatlardagi holatlarni o‘rganish</li><li>Tarmoq kompyuterlari. Lokal hududiy (Local area networks) va global hududiy tarmoq (Wide area networks).</li><li>Kliyent-server va peer-to-peer tarmoqlari.</li><li>Virtual shaxsiy tarmoq (VPN)</li><li>Intranet va ekstranet. Internet va uning xususiyatlari</li><li>Internetda muloqot qilish. Mobil tarmoqlar</li><li>Video va veb konferensiya. Videokonferensiyaning jamiyatga ta‘siri</li><li>Ekspert tizim haqida</li><li>Bilimlar bazasi va yakunlovchi mexanizm</li><li>Foydalanuvchi interfeysi</li><li>Ekspert tizimlardan foydalanish</li><li>Ma‘lumotlarni qayta ishlash tizimlari</li><li>Real vaqt rejimida qayta ishlash tizimi</li><li>Elektron jadval yaratish. Qatorlar va ustunlarni boshqarish</li><li>Elektron jadval xavfsizligi</li><li>Panel va oynalarni interfeysga mahkamlash</li><li>Elektron jadvalni formatlash. Shartli formatlash</li><li>Formula va funksiyalarni yaratish. Katakka absolyut va nisbiy murojaat</li><li>Nomlangan katak va diapazon</li><li>Yaxlitlash funksiyalari</li><li>Sana va vaqtga oid funksiyalar. Shartli funksiyalar. Qidirish funksiyalari</li><li>INDEX va MATCH funksiyalari</li><li>Shartli statistik funksiyalar</li><li>Validatsiya qoidalari</li><li>Elektron jadvalga qo‘llanadigan validatsiya</li><li>Ma‘lumotlar kiritilishini tekshirish</li><li>Ma‘lumotlarni filtrlash va saralash</li><li>Jamlovchi jadvallar va diagrammalar</li><li>Ma‘lumotlarni import va eksport qilish</li><li>Grafik va diagrammalar. Modellashtirish. Simulyatorlar</li></ul><p>Test <b>10 ta aralash savoldan</b> iborat. Qiynalgan mavzuingizning darsini qayta o‘qib chiqing.</p>","quiz":[{"q":"Panel nima?","o":["Faqat matn saqlaydigan fayl","Tugma va buyruqlar joylashgan maydon","Tarmoq qurilmasi","Antivirus dasturi"],"a":1,"e":"Panel buyruqlarni qulay joylashtirish uchun xizmat qiladi."},{"q":"$A1 qanday murojaat?","o":["To‘liq absolyut","Matn","Aralash murojaat","To‘liq nisbiy"],"a":2,"e":"Faqat ustun qotirilgan."},{"q":"Videokonferensiyaning afzalligi qaysi?","o":["Ovoz uzatmasligi","Internetni talab qilmasligi","Vaqt va yo‘l xarajatini tejashi","Faqat bir kishi qatnashishi"],"a":2,"e":"Masofadan uchrashuv xarajatni kamaytiradi."},{"q":"Ekspert tizim ta’limda nima qilishi mumkin?","o":["Imtihonni o‘zi topshirishi","Maktabni almashtirishi","O‘quvchiga mos mashqlar tavsiya etishi","Kitob chop etishi"],"a":2,"e":"Tavsiya berish mumkin."},{"q":"Vizual tekshirish nima?","o":["Ma’lumotni avtomatik shifrlash","Ekrandagi ma’lumotni asl manba bilan ko‘z orqali solishtirish","Ma’lumotni ikki marta saqlash","Virusga qarshi dastur bilan skanerlash"],"a":1,"e":"Vizual tekshirishda inson ko‘zi bilan solishtiriladi."},{"q":"Sonni oddiy qoida bo‘yicha yaxlitlaydigan funksiya qaysi?","o":["ROUNDDOWN","SUM","ROUND","INT"],"a":2,"e":"ROUND oddiy matematik qoida bilan yaxlitlaydi."},{"q":"Vaqt bo‘yicha o‘zgarishni ko‘rsatish uchun qaysi diagramma qulay?","o":["Chiziqli","Piktogramma","Doiraviy","Ustunli faqat bitta toifa"],"a":0,"e":"Chiziqli diagramma dinamikani ko‘rsatadi."},{"q":"Real vaqtda qayta ishlash nimani bildiradi?","o":["Ma’lumot kelgan zahoti ishlanishini","Tizim ishlamasligini","Natija bir necha kundan keyin chiqishini","Ma’lumot saqlanmasligini"],"a":0,"e":"Real vaqt — kechiktirmasdan ishlash."},{"q":"Elektron jadvalni himoyalashdan maqsad nima?","o":["Fayl hajmini oshirish","Ma’lumotni ruxsatsiz o‘zgartirish va yo‘qolishdan saqlash","Jadval rangini o‘zgartirish","Internet tezligini oshirish"],"a":1,"e":"Himoya ma’lumot xavfsizligi uchun."},{"q":"=IF(B2>=3;\"O‘tdi\";\"Qoldi\") formulada B2 ga 2 yozilsa, natija qanday bo‘ladi?","o":["2","Xato","O‘tdi","Qoldi"],"a":3,"e":"Shart yolg‘on, ikkinchi natija chiqadi."}]},{"t":"53-dars. Ma‘lumotlar bazasini yaratish. Ma‘lumot turlari va katak hajmlari. Uch tomonlama bog‘lanish.","lesson":"<p>Ma’lumotlar bazasini yaratishdan oldin uning tuzilishi rejalashtiriladi: qanday jadvallar kerak, har bir jadvalda qanday maydonlar bo‘ladi va ular qanday turdagi ma’lumot saqlaydi.</p>\n<h4>Ma’lumot turlari</h4>\n<ul><li>Matn (qisqa matn) — ism, manzil kabi qisqa yozuvlar uchun.</li><li>Uzun matn — izoh va tavsiflar uchun.</li><li>Son — hisob-kitob qilinadigan qiymatlar uchun.</li><li>Sana va vaqt — tug‘ilgan kun, buyurtma sanasi uchun.</li><li>Pul birligi — narx va summalar uchun.</li><li>Mantiqiy (Ha/Yo‘q) — ikki qiymatli maydon uchun.</li><li>Avtonomer — har yangi yozuvga o‘zi beriladigan tartib raqami.</li></ul>\n<h4>Katak hajmi</h4>\n<p>Maydon hajmi unga sig‘adigan eng katta qiymatni belgilaydi. Masalan, matn maydoniga belgilar soni cheklanadi, son maydonida esa tur (butun yoki kasrli) hajmni belgilaydi. Hajmni keraksiz katta qilish xotirani isrof qiladi.</p>\n<h4>Uch tomonlama bog‘lanish</h4>\n<p>Ba’zan uchta jadval o‘zaro bog‘lanadi: masalan, “O‘quvchilar”, “Fanlar” va “Baholar”. Baholar jadvali ikkala jadvalning kalit maydoniga havola qiladi.</p>\n<div class=\"ex\"><b>Misol.</b> Baholar jadvalida O‘quvchi kodi, Fan kodi va Baho maydonlari bo‘ladi. Shu orqali kim qaysi fandan qanday baho olgani ko‘rinadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Har maydonga mos tur tanlanadi.</li><li>Hajm kerakli darajada belgilanadi.</li><li>Jadvallar kalit maydonlar orqali bog‘lanadi.</li></ul>","quiz":[{"q":"Maydon uchun ma’lumot turi nimani belgilaydi?","o":["Maydonda qanday ko‘rinishdagi qiymat saqlanishini","Jadval rangini","Fayl joylashgan papkani","Ekran o‘lchamini"],"a":0,"e":"Tur maydonga kiritiladigan qiymat xarakterini aniqlaydi."},{"q":"Telefon operatori ismini saqlash uchun qaysi tur mos?","o":["Avtonomer","Qisqa matn","Mantiqiy","Sana va vaqt"],"a":1,"e":"Ism harflardan iborat matn."},{"q":"Tug‘ilgan kunni saqlash uchun qaysi tur mos?","o":["Mantiqiy","Pul birligi","Sana va vaqt","Uzun matn"],"a":2,"e":"Sana uchun maxsus tur bor."},{"q":"Avtonomer maydoni qanday ishlaydi?","o":["Faqat rasm saqlaydi","Faqat matn saqlaydi","Foydalanuvchi har safar qo‘lda yozadi","Har yangi yozuvga tartib raqamini o‘zi beradi"],"a":3,"e":"Avtonomer qiymati avtomatik hosil bo‘ladi."},{"q":"“Ha” yoki “Yo‘q” qiymati uchun qaysi tur qulay?","o":["Sana va vaqt","Avtonomer","Uzun matn","Mantiqiy"],"a":3,"e":"Ikki holatli maydon mantiqiy turda."},{"q":"Katak hajmini keraksiz katta qilishning oqibati qaysi?","o":["Kalit ishlamaydi","Jadval o‘chadi","Xotira isrof bo‘ladi","Ma’lumot yo‘qoladi"],"a":2,"e":"Ortiqcha hajm xotirani band qiladi."},{"q":"Uch tomonlama bog‘lanishda nechta jadval ishtirok etadi?","o":["Ikkita","Uchta","Bitta","To‘rtta"],"a":1,"e":"Nomidan ko‘rinib turibdi: uch jadval."},{"q":"“O‘quvchilar”, “Fanlar” va “Baholar” jadvallarini bog‘lashda Baholar jadvali nimani saqlaydi?","o":["Ikkala jadvalning kodlariga havola maydonlarini","Faqat o‘quvchi rasmini","Hech qanday kod saqlamaydi","Faqat dastur nomini"],"a":0,"e":"Baholar jadvali o‘quvchi va fan kodlari orqali bog‘lanadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Narx uchun Avtonomer tanlanadi","Narx uchun sana turi tanlanadi","Narx uchun doim mantiqiy tur tanlanadi","Narx uchun pul birligi yoki son turi mos keladi"],"a":3,"e":"Narx raqamli qiymat."},{"q":"Ma’lumotlar bazasini yaratishdan avval nima qilinadi?","o":["Hisobot chop etiladi","Tuzilma rejalashtiriladi","Dastur o‘chirib tashlanadi","Yozuvlar kiritilmasdan o‘chiriladi"],"a":1,"e":"Avval jadval va maydonlar rejalashtiriladi."}]},{"t":"54-dars. Birga-bir va birga-ko‘p bog‘lanish. Ko‘pga-ko‘p bog‘lanish. Bog‘lanishlar yaratish va foydalanish","lesson":"<p>Jadvallar o‘zaro bog‘langanda ma’lumot takrorlanmaydi va izchil saqlanadi. Bog‘lanishning uch asosiy turi mavjud.</p>\n<h4>Bog‘lanish turlari</h4>\n<ul><li><b>Birga-bir</b> — birinchi jadvalning har bir yozuviga ikkinchi jadvalda ko‘pi bilan bitta yozuv mos keladi. Masalan, fuqaro va uning pasporti.</li><li><b>Birga-ko‘p</b> — bitta yozuvga ikkinchi jadvaldagi bir nechta yozuv mos keladi. Masalan, bitta sinf va uning ko‘p o‘quvchilari.</li><li><b>Ko‘pga-ko‘p</b> — ikkala tomonda ham bir nechta yozuv mos keladi. Masalan, o‘quvchilar va to‘garaklar: o‘quvchi bir nechta to‘garakka qatnashadi, to‘garakda ko‘p o‘quvchi bor.</li></ul>\n<h4>Ko‘pga-ko‘pni amalga oshirish</h4>\n<p>Ko‘pga-ko‘p bog‘lanish to‘g‘ridan-to‘g‘ri o‘rnatilmaydi. Buning uchun oraliq (bog‘lovchi) jadval yaratiladi va u ikkita birga-ko‘p bog‘lanishga ajratiladi.</p>\n<h4>Bog‘lanish yaratish</h4>\n<ol><li>Jadvallarni tayyorlang va kalit maydonlarni belgilang.</li><li>Bog‘lanishlar oynasiga jadvallarni qo‘shing.</li><li>Asosiy jadvaldagi kalit maydonni bog‘liq jadvaldagi mos maydonga ulang.</li><li>Bog‘lanish turini tekshiring va saqlang.</li></ol>\n<div class=\"ex\"><b>Misol.</b> “Sinflar” va “O‘quvchilar” jadvallari sinf kodi orqali birga-ko‘p bog‘lanadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Bog‘lanish turi ma’lumot mantiqiga qarab tanlanadi.</li><li>Ko‘pga-ko‘p oraliq jadval orqali amalga oshadi.</li></ul>","quiz":[{"q":"Birga-ko‘p bog‘lanishga qaysi misol mos?","o":["Fuqaro va uning yagona pasporti","Ikki bir xil jadval","Hech qanday bog‘lanmagan jadvallar","Bitta sinf va uning ko‘p o‘quvchilari"],"a":3,"e":"Bitta sinfda ko‘p o‘quvchi bo‘ladi."},{"q":"Birga-bir bog‘lanishda nima bo‘ladi?","o":["Bir yozuvga ko‘pi bilan bitta yozuv mos keladi","Faqat matn saqlanadi","Jadvallar o‘chiriladi","Bir yozuvga cheksiz yozuv mos keladi"],"a":0,"e":"Birga-bir — har yozuvga bittadan."},{"q":"Ko‘pga-ko‘p bog‘lanish qanday amalga oshiriladi?","o":["Jadvalni o‘chirib","Oraliq jadval orqali","Maydon nomini o‘zgartirib","Faqat bitta jadval yaratib"],"a":1,"e":"Oraliq jadval ikki birga-ko‘pni hosil qiladi."},{"q":"Qaysi juftlik ko‘pga-ko‘p bog‘lanishga misol?","o":["Fuqaro va pasport raqami","O‘quvchilar va to‘garaklar","Sinf rahbari va uning yagona sinfi","Mamlakat va uning poytaxti"],"a":1,"e":"O‘quvchi bir nechta to‘garakka qatnashishi mumkin."},{"q":"Bog‘lanish yaratishda jadvallar qaysi maydonlar orqali ulanadi?","o":["Fayl nomi orqali","Tasodifiy tanlangan rasmlar orqali","Rang orqali","Mos kalit maydonlar orqali"],"a":3,"e":"Ulanish mos maydonlar orqali amalga oshadi."},{"q":"Bog‘lanishlar nima uchun kerak?","o":["Jadvalni sekinlashtirish uchun","Parolni almashtirish uchun","Ma’lumot takrorlanishini kamaytirish uchun","Yozuvlarni yashirish uchun"],"a":2,"e":"Bog‘lanish ortiqcha takrorni oldini oladi."},{"q":"“Sinflar” va “O‘quvchilar” jadvallarida ‘bir’ tomon qaysi jadval?","o":["Ikkalasi ham bir xil","O‘quvchilar","Sinflar","Hech biri"],"a":2,"e":"Bitta sinfga ko‘p o‘quvchi to‘g‘ri keladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Birga-bir har doim bir jadval deganidir","Ko‘pga-ko‘p ikkita birga-ko‘pga ajratiladi","Birga-ko‘pda ikkala tomon ham bitta","Ko‘pga-ko‘p hech qachon kerak bo‘lmaydi"],"a":1,"e":"Oraliq jadval ikkita birga-ko‘p bog‘lanish beradi."},{"q":"Bog‘lanish yaratishdan oldin nima tayyorlanadi?","o":["Yozuvlar nusxalanadi","Dastur o‘chiriladi","Hisobot chop etiladi","Jadvallar va kalit maydonlar"],"a":3,"e":"Avval jadval va kalitlar bo‘lishi kerak."},{"q":"Oraliq jadvalda odatda nima bo‘ladi?","o":["Ikkala jadvalga havola qiluvchi maydonlar","Faqat bitta so‘z","Faqat rasm","Hech qanday maydon bo‘lmaydi"],"a":0,"e":"U ikkala jadval kodini saqlaydi."}]},{"t":"55-dars. Oddiy yozuvli va relyatsion ma‘lumotlar bazasi o‘rtasidagi farq","lesson":"<p>Oddiy yozuvli (yassi) ma’lumotlar bazasi barcha ma’lumotni bitta jadvalda saqlaydi. Relyatsion ma’lumotlar bazasi esa ma’lumotni bir nechta o‘zaro bog‘langan jadvalda saqlaydi.</p>\n<h4>Oddiy (yassi) baza</h4>\n<ul><li>Bitta jadval, soddaligi bilan qulay.</li><li>Ma’lumot takrorlanadi: bir mijoz haqidagi ma’lumot har buyurtmada qayta yoziladi.</li><li>Yangilashda xato ehtimoli yuqori.</li><li>Kichik va oddiy ma’lumotlar uchun mos.</li></ul>\n<h4>Relyatsion baza</h4>\n<ul><li>Ma’lumot mavzulari bo‘yicha alohida jadvallarga ajratiladi.</li><li>Jadvallar kalitlar orqali bog‘lanadi.</li><li>Takrorlanish kamayadi, ma’lumot izchilligi oshadi.</li><li>Murakkab so‘rovlar va katta hajm uchun mos.</li></ul>\n<h4>Qiyoslash</h4>\n<ul><li>Yassi baza — sodda, lekin takrorlanish ko‘p.</li><li>Relyatsion baza — murakkabroq, lekin samaraliroq.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Yassi jadvalda har buyurtma qatorida mijozning ismi va manzili qayta yoziladi. Relyatsion bazada esa mijoz alohida jadvalda bir marta saqlanadi, buyurtma unga bog‘lanadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Yassi baza — bitta jadval.</li><li>Relyatsion baza — bog‘langan jadvallar.</li><li>Relyatsion baza takrorlanishni kamaytiradi.</li></ul>","quiz":[{"q":"Oddiy yozuvli baza nechta jadvaldan iborat?","o":["Bitta jadvaldan","Jadvalsiz","Ko‘p bog‘langan jadvaldan","Faqat rasmlardan"],"a":0,"e":"Yassi baza bitta jadval."},{"q":"Relyatsion baza nimadan iborat?","o":["O‘zaro bog‘langan jadvallardan","Faqat bitta ustundan","Faqat rasmdan","Faqat matn faylidan"],"a":0,"e":"Jadvallar kalitlar orqali bog‘lanadi."},{"q":"Yassi bazaning asosiy kamchiligi nima?","o":["Jadvalning yo‘qligi","Juda murakkabligi","Xotira kerak emasligi","Ma’lumotning takrorlanishi"],"a":3,"e":"Bir ma’lumot ko‘p marta yoziladi."},{"q":"Relyatsion bazaning afzalligi nima?","o":["Ma’lumot saqlanmaydi","Takrorlanish kamayadi va izchillik oshadi","Har doim eng sodda","Jadval kerak emas"],"a":1,"e":"Ma’lumot bir marta saqlanadi."},{"q":"Jadvallarni bog‘lash nima orqali amalga oshadi?","o":["Kalitlar orqali","Rangi orqali","Fayl nomi orqali","Ekran o‘lchami orqali"],"a":0,"e":"Kalitlar bog‘laydi."},{"q":"Qaysi baza kichik va oddiy ma’lumot uchun mos?","o":["Hech qaysi","Bulut bazasi faqat","Yassi baza","Murakkab relyatsion baza faqat"],"a":2,"e":"Sodda ish uchun yassi baza yetarli."},{"q":"Vaziyat: mijoz manzili o‘zgardi, yassi jadvalda uning 50 buyurtmasi bor. Qanday muammo?","o":["Hech muammo yo‘q","Ko‘p qatorni o‘zgartirish kerak, xato ehtimoli ortadi","Manzil o‘zi o‘zgaradi","Jadval o‘chadi"],"a":1,"e":"Takrorlangan ma’lumot yangilashni qiyinlashtiradi."},{"q":"Relyatsion bazada mijoz ma’lumoti qayerda saqlanadi?","o":["Alohida jadvalda bir marta","Hech qayerda","Faqat rasmda","Har buyurtmada qayta"],"a":0,"e":"Alohida jadvalda."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Relyatsion baza takrorlanishni oshiradi","Relyatsion baza katta hajm uchun qulay","Relyatsion baza bitta jadvaldan iborat","Yassi baza murakkab so‘rovlarga eng mos"],"a":1,"e":"U katta hajmga mos."},{"q":"Ma’lumot izchilligi nimani anglatadi?","o":["Ma’lumot rangini","Ma’lumotlar bir-biriga zid bo‘lmasligini","Ma’lumot tezligini","Ma’lumot ko‘pligini"],"a":1,"e":"Izchillik — ziddiyatsizlik."}]},{"t":"56-dars. Ma‘lumotlarni import qilish. Relyatsion ma‘lumotlar bazasini yaratish.","lesson":"<p>Ma’lumotlar bazasiga ma’lumotni qo‘lda kiritish o‘rniga, tayyor fayllardan (masalan, elektron jadval yoki CSV) import qilish mumkin. Import vaqtni tejaydi va xatolarni kamaytiradi. Shundan keyin relyatsion bazani rejalashtirib yaratish mumkin.</p>\n<h4>Importni amalga oshirish</h4>\n<ul><li>Manba faylini tanlang (jadval, CSV, matn).</li><li>Birinchi qator maydon nomlari ekanini belgilang.</li><li>Har maydon uchun ma’lumot turini aniqlang.</li><li>Import natijasini tekshiring.</li></ul>\n<h4>Relyatsion baza yaratish bosqichlari</h4>\n<ul><li>Obyektlarni aniqlash: nimalar haqida ma’lumot saqlanadi.</li><li>Har obyekt uchun alohida jadval yaratish.</li><li>Har jadval uchun birlamchi kalit tanlash.</li><li>Jadvallar orasida bog‘lanishlar o‘rnatish.</li></ul>\n<h4>Maslahat</h4>\n<ul><li>Bir jadvalda faqat bir mavzu bo‘lsin.</li><li>Takrorlanuvchi ma’lumotlarni alohida jadvalga chiqaring.</li></ul>\n<div class=\"ex\"><b>Misol.</b> O‘quvchilar ro‘yxatini Excel faylidan bazaga import qilib, so‘ng \"Sinflar\" jadvalini yaratib, ikkalasini sinf kodi orqali bog‘laysiz.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Import vaqtni tejaydi.</li><li>Har obyekt uchun alohida jadval kerak.</li><li>Jadvallar kalitlar orqali bog‘lanadi.</li></ul>","quiz":[{"q":"Ma’lumotni importlashning afzalligi nima?","o":["Ma’lumotni o‘chiradi","Jadvallarni yo‘q qiladi","Faylni sekinlashtiradi","Vaqtni tejaydi va xatolarni kamaytiradi"],"a":3,"e":"Qo‘lda kiritish kamayadi."},{"q":"Importda qaysi manba ishlatilishi mumkin?","o":["Faqat sichqoncha","Elektron jadval yoki CSV fayl","Faqat monitor","Faqat printer"],"a":1,"e":"Tayyor fayllardan import qilinadi."},{"q":"Importda birinchi qator nima bo‘lishi mumkin?","o":["Hisobot","Rasm","Maydon nomlari","Parol"],"a":2,"e":"Birinchi qator sarlavhalar bo‘lishi mumkin."},{"q":"Importdan keyin nima qilinadi?","o":["Hech narsa tekshirilmaydi","Baza o‘chiriladi","Natija tekshiriladi","Fayl yo‘qotiladi"],"a":2,"e":"Xatolarni topish uchun tekshiruv zarur."},{"q":"Relyatsion bazani yaratishda birinchi bosqich nima?","o":["Obyektlarni aniqlash","Hisobot chop etish","Ranglarni tanlash","Faylni arxivlash"],"a":0,"e":"Avval nimalar haqida ma’lumot saqlanishi aniqlanadi."},{"q":"Har obyekt uchun nima yaratiladi?","o":["Hammasiga bitta umumiy jadval","Faqat rasm","Alohida jadval","Faqat diagramma"],"a":2,"e":"Obyekt uchun jadval."},{"q":"Jadval uchun nima tanlanadi?","o":["Birlamchi kalit","Hech narsa","Faqat rasm","Tasodifiy rang"],"a":0,"e":"Yozuvlarni noyob aniqlash uchun kalit."},{"q":"Vaziyat: jadvalda mijoz ma’lumoti ko‘p takrorlanmoqda. Nima qilish kerak?","o":["Hammasini o‘chirish","Takrorni ko‘paytirish","Mijozlarni alohida jadvalga chiqarish","Hech narsa qilmaslik"],"a":2,"e":"Takrorlanuvchi ma’lumot alohida jadvalga chiqariladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Bir jadvalda bitta mavzu bo‘lishi tavsiya etiladi","Jadvallar bog‘lanmaydi","Bir jadvalda hamma mavzu aralash","Kalit kerak emas"],"a":0,"e":"Mavzular ajratiladi."},{"q":"Jadvallarni bog‘lash uchun nima ishlatiladi?","o":["Shriftlar","Piktogrammalar","Kalitlar","Ranglar"],"a":2,"e":"Kalitlar bog‘lovchi vazifasini bajaradi."}]},{"t":"57-dars. Kalitlar. Murakkab kalit. Tashqi kalit.","lesson":"<p>Kalit — jadvaldagi yozuvni boshqalaridan ajratib turuvchi maydon yoki maydonlar to‘plami. Kalit tufayli ma’lumotni aniq topish va jadvallarni bog‘lash mumkin.</p>\n<h4>Kalit turlari</h4>\n<ul><li><b>Birlamchi kalit</b> — yozuvni yagona aniqlaydi. Uning qiymati takrorlanmaydi va bo‘sh bo‘lmaydi. Masalan, o‘quvchi kodi.</li><li><b>Murakkab kalit</b> — ikki yoki undan ortiq maydondan iborat kalit. Bitta maydon yagonalikni ta’minlamaganda ishlatiladi.</li><li><b>Tashqi kalit</b> — boshqa jadvalning birlamchi kalitiga havola qiluvchi maydon.</li></ul>\n<h4>Qanday tanlanadi?</h4>\n<p>Ism yoki familiya kalit bo‘la olmaydi, chunki ular takrorlanishi mumkin. Shu sababli odatda kod yoki raqam maydoni ishlatiladi.</p>\n<div class=\"ex\"><b>Misol.</b> “Baholar” jadvalida bitta o‘quvchi bir nechta fandan baho oladi. O‘quvchi kodi va Fan kodi birgalikda murakkab kalit bo‘ladi. Bu maydonlar alohida esa “O‘quvchilar” va “Fanlar” jadvallariga tashqi kalit hisoblanadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Birlamchi kalit takrorlanmaydi.</li><li>Murakkab kalit bir nechta maydondan tuziladi.</li><li>Tashqi kalit jadvallarni bog‘laydi.</li></ul>","quiz":[{"q":"Birlamchi kalit nima uchun kerak?","o":["Faylni arxivlash uchun","Jadvalni bezash uchun","Matn rangini o‘zgartirish uchun","Har bir yozuvni yagona aniqlash uchun"],"a":3,"e":"Kalit yozuvni yagona belgilaydi."},{"q":"Birlamchi kalit qiymati qanday bo‘lishi shart?","o":["Doim bo‘sh","Takrorlanmas va bo‘sh bo‘lmagan","Bir xil bo‘lishi mumkin","Faqat sana"],"a":1,"e":"Yagonalik asosiy talab."},{"q":"Murakkab kalit nima?","o":["Jadval nomi","Parol","Faqat bitta uzun matn","Ikki yoki undan ortiq maydondan iborat kalit"],"a":3,"e":"U bir nechta maydonning birikmasi."},{"q":"Tashqi kalit nima?","o":["Jadvalning birinchi ustuni","Boshqa jadvalning birlamchi kalitiga havola qiluvchi maydon","Parol maydoni","Jadvalning rasmi"],"a":1,"e":"Tashqi kalit jadvallarni bog‘laydi."},{"q":"Qaysi maydon birlamchi kalit uchun yomon tanlov?","o":["Yozuv tartib raqami","Familiya","Pasport seriyasi va raqami","O‘quvchi kodi"],"a":1,"e":"Familiyalar takrorlanishi mumkin."},{"q":"Baholar jadvalida o‘quvchi va fan kodlari birgalikda qanday kalit bo‘lishi mumkin?","o":["Rasm kaliti","Hisobot","Matnli izoh","Murakkab kalit"],"a":3,"e":"Ikki maydon birikmasi yozuvni aniqlaydi."},{"q":"Murakkab kalit qachon kerak bo‘ladi?","o":["Faqat rasm saqlanganda","Bitta maydon yagonalikni ta’minlamaganda","Jadval bo‘sh bo‘lganda","Hech qachon"],"a":1,"e":"Yagonalikni maydonlar birikmasi beradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Tashqi kalit har doim birlamchi kalitdir","Tashqi kalit takrorlana olmaydi","Tashqi kalit qiymati bog‘langan jadvalda mavjud bo‘lishi kerak","Tashqi kalit faqat sana bo‘ladi"],"a":2,"e":"Tashqi kalit mavjud yozuvga ishora qiladi."},{"q":"Ikki jadvalni bog‘lash uchun qaysi kalitlardan foydalaniladi?","o":["Rasm va matn","Hisobot va forma","Ikkita parol","Birlamchi va tashqi kalit"],"a":3,"e":"Bog‘lanish shu juftlik orqali amalga oshadi."},{"q":"Bitta jadvalda nechta birlamchi kalit bo‘ladi?","o":["Doim uchta","Yozuvlar soniga teng","Bitta (u bir nechta maydondan iborat bo‘lishi mumkin)","Hech bo‘lmaydi"],"a":2,"e":"Jadvalda bitta birlamchi kalit bo‘ladi."}]},{"t":"58-dars. Bog‘lanishlar yaxlitligi. Ma‘lumotlar validatsiyasi va verifikatsiyasi","lesson":"<p>Ma’lumotlar bazasida ma’lumot to‘g‘ri va ziddiyatsiz bo‘lishi muhim. Buning uchun bog‘lanishlar yaxlitligi hamda validatsiya va verifikatsiya ishlatiladi.</p>\n<h4>Bog‘lanishlar yaxlitligi</h4>\n<p>Yaxlitlik jadvallar orasidagi bog‘lanish buzilmasligini ta’minlaydi. Masalan, mavjud bo‘lmagan sinfga o‘quvchi qo‘shib bo‘lmaydi, o‘quvchilari bor sinfni o‘chirishga esa dastur ruxsat bermaydi. Yetim yozuvlar paydo bo‘lishiga yo‘l qo‘yilmaydi.</p>\n<h4>Validatsiya</h4>\n<p>Validatsiya — kiritilayotgan ma’lumot belgilangan qoidaga mos kelishini tekshirish. Masalan, baho 2 dan 5 gacha bo‘lishi, tug‘ilgan sana kelajakda bo‘lmasligi.</p>\n<h4>Verifikatsiya</h4>\n<p>Verifikatsiya — kiritilgan ma’lumot manbaga mos va haqiqatan to‘g‘ri ekanini tasdiqlash. Masalan, ikki marta kiritib solishtirish yoki hujjat bilan taqqoslash.</p>\n<div class=\"ex\"><b>Misol.</b> Baho maydoniga 7 yozilsa, validatsiya qoidasi uni rad etadi. Baho 4 o‘rniga 5 yozilgan bo‘lsa, qoida xatoni sezmaydi; buni verifikatsiya, ya’ni jurnal bilan solishtirish topadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Yaxlitlik bog‘lanishlarni himoya qiladi.</li><li>Validatsiya qoidaga mosligini tekshiradi.</li><li>Verifikatsiya to‘g‘riligini tasdiqlaydi.</li></ul>","quiz":[{"q":"Bog‘lanishlar yaxlitligi nimani ta’minlaydi?","o":["Jadvallar orasidagi bog‘lanish buzilmasligini","Faylning kengaytmasini","Ekran yorqinligini","Jadval rangini"],"a":0,"e":"Yaxlitlik izchillikni saqlaydi."},{"q":"Yaxlitlik yoqilgan bo‘lsa, mavjud bo‘lmagan sinfga o‘quvchi qo‘shish mumkinmi?","o":["Ha, doim","Yo‘q, dastur rad etadi","Faqat kechasi","Faqat rasm bilan"],"a":1,"e":"Havola mavjud yozuvga bo‘lishi kerak."},{"q":"Validatsiya nima?","o":["Ma’lumotni o‘chirish","Faylni siqish","Ma’lumot qoidaga mosligini tekshirish","Jadvalni chop etish"],"a":2,"e":"Validatsiya format va qoidani tekshiradi."},{"q":"Verifikatsiya nima?","o":["Kiritilgan ma’lumot manbaga mos ekanini tasdiqlash","Parolni yashirish","Jadvalni nusxalash","Maydon nomini o‘zgartirish"],"a":0,"e":"Verifikatsiya to‘g‘riligini tekshiradi."},{"q":"Baho maydoniga 7 kiritilishini qaysi usul to‘xtatadi?","o":["Fayl nomini o‘zgartirish","Validatsiya qoidasi","Hisobot yaratish","Rasm qo‘shish"],"a":1,"e":"Qoida ruxsat etilgan oraliqni cheklaydi."},{"q":"Baho 4 o‘rniga 5 yozilgan xatoni qaysi usul topadi?","o":["Verifikatsiya, ya’ni manba bilan solishtirish","Hech qaysi usul topa olmaydi","Jadval ranglari","Oddiy qoida (2 dan 5 gacha)"],"a":0,"e":"5 ham ruxsat etilgan qiymat, shuning uchun manba kerak."},{"q":"Yetim yozuv nima?","o":["Kalit maydon","Eng yangi yozuv","Bo‘sh jadval","Mavjud bo‘lmagan yozuvga havola qiluvchi yozuv"],"a":3,"e":"Yaxlitlik shunday yozuvlarni oldini oladi."},{"q":"O‘quvchilari bor sinfni o‘chirishga urinilsa, yaxlitlik yoqilgan bazada nima bo‘ladi?","o":["Dastur o‘chirishga ruxsat bermaydi","Barcha jadvallar o‘chadi","Hech narsa sezilmaydi","Dastur yopiladi"],"a":0,"e":"Bog‘liq yozuvlar himoya qilinadi."},{"q":"Tug‘ilgan sana kelajakda bo‘lmasligi qoidasi nimaga misol?","o":["Bog‘lanishga","Eksportga","Saralashga","Validatsiyaga"],"a":3,"e":"Bu kiritish qoidasi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Validatsiya o‘tgan ma’lumot doim haqiqiy","Verifikatsiya bu qoidani yaratish","Validatsiya o‘tgan ma’lumot ham noto‘g‘ri bo‘lishi mumkin","Yaxlitlik faqat matn uchun"],"a":2,"e":"Qoidaga mos qiymat haqiqatga mos bo‘lmasligi mumkin."}]},{"t":"59-dars. Qidirish amallari. Murakkab querylar. Ichki va jamlanma querylar.","lesson":"<p>Query (so‘rov) — bazadan kerakli ma’lumotni tanlab olish uchun tuziladigan topshiriq. So‘rov yordamida minglab yozuv orasidan faqat shartga mos yozuvlar ko‘rsatiladi.</p>\n<h4>Qidirish amallari</h4>\n<ul><li>Taqqoslash: teng, katta, kichik, teng emas.</li><li>Oraliq: ikki qiymat orasidagi ma’lumotlar.</li><li>Andoza bo‘yicha: matnning boshlanishi yoki bir qismi bo‘yicha.</li><li>Bo‘sh qiymatni qidirish.</li></ul>\n<h4>Murakkab querylar</h4>\n<p>Bir nechta shart birgalikda ishlatiladi. “VA” (AND) holatida barcha shartlar bajarilishi kerak, “YOKI” (OR) holatida kamida bittasi yetarli, “EMAS” (NOT) shartni inkor qiladi.</p>\n<h4>Ichki va jamlanma querylar</h4>\n<ul><li><b>Ichki (ichma-ich) query</b> — boshqa so‘rov ichida ishlatiladigan so‘rov. Uning natijasi tashqi so‘rovga shart bo‘ladi.</li><li><b>Jamlanma query</b> — yozuvlarni guruhlab, jami, o‘rtacha, eng katta, eng kichik qiymat va sonni hisoblaydi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> “8-sinf VA bahosi 5” sharti faqat ikkala talabga javob beradigan o‘quvchilarni chiqaradi. Sinflar bo‘yicha o‘rtacha bahoni hisoblash jamlanma querydir.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Query ma’lumotni shart bo‘yicha tanlaydi.</li><li>VA qattiq, YOKI keng shart beradi.</li><li>Jamlanma query guruhlar bo‘yicha hisoblaydi.</li></ul>","quiz":[{"q":"Query nima?","o":["Bazadan shart bo‘yicha ma’lumot tanlash so‘rovi","Ekran rasmi","Jadvalning nomi","Faqat chop etish buyrug‘i"],"a":0,"e":"Query kerakli yozuvlarni tanlaydi."},{"q":"“VA” (AND) mantiqiy amalida yozuv qachon tanlanadi?","o":["Faqat birinchi shart bajarilganda","Hech bir shart bajarilmaganda","Barcha shartlar bajarilganda","Har doim"],"a":2,"e":"VA hamma shartni talab qiladi."},{"q":"“YOKI” (OR) amalida yozuv qachon tanlanadi?","o":["Hech shart bajarilmaganda","Hamma shart bajarilganda","Kamida bitta shart bajarilganda","Faqat ikkinchi shart bajarilganda"],"a":2,"e":"YOKI bitta shartni yetarli deb hisoblaydi."},{"q":"“EMAS” (NOT) amali nima qiladi?","o":["Yozuvni nusxalaydi","Shartni inkor qiladi","Ikki shartni qo‘shadi","Jadvalni o‘chiradi"],"a":1,"e":"NOT shartning teskarisini beradi."},{"q":"Jamlanma query nimaga mo‘ljallangan?","o":["Guruhlar bo‘yicha jami, o‘rtacha, son kabilarni hisoblash","Rasm chizish","Jadval ranglarini o‘zgartirish","Yangi parol berish"],"a":0,"e":"Jamlanma query hisoblaydi."},{"q":"Sinflar bo‘yicha o‘rtacha bahoni topish qaysi query?","o":["Faqat saralash","Rasm so‘rovi","Chop etish","Jamlanma query"],"a":3,"e":"O‘rtacha qiymat jamlanma funksiya."},{"q":"Ichki query nima?","o":["Boshqa so‘rov ichida ishlatiladigan so‘rov","Jadval ichidagi rasm","Eng sekin so‘rov","Parol"],"a":0,"e":"Natijasi tashqi so‘rovga shart bo‘ladi."},{"q":"“8-sinf VA baho 5” sharti kimlarni chiqaradi?","o":["Faqat 5 olganlarni","Faqat 8-sinf o‘quvchilarini","Ikkala talabga mos o‘quvchilarni","Barcha o‘quvchilarni"],"a":2,"e":"VA ikkala shartni talab qiladi."},{"q":"Qaysi variant ikkita shartdan birortasi yetarli bo‘lgan holatga mos?","o":["VA","Saralash","Eksport","YOKI"],"a":3,"e":"YOKI keng natija beradi."},{"q":"Murakkab query nimani anglatadi?","o":["Parol bilan himoyalangan so‘rov","Bo‘sh so‘rov","Bir nechta shartdan tuzilgan so‘rov","Faqat bitta shartli so‘rov"],"a":2,"e":"Shartlar birlashtiriladi."}]},{"t":"60-dars. Statik va dinamik parametrlar. Ma‘lumotlar bazasi doirasida hisoblashlarni amalga oshirish.","lesson":"<p>So‘rovlarda parametrlardan foydalanish ularni qayta-qayta o‘zgartirmasdan turli qiymat bilan ishlatish imkonini beradi. Bundan tashqari, baza ichida hisoblashlar ham bajariladi.</p>\n<h4>Statik va dinamik parametrlar</h4>\n<ul><li><b>Statik parametr</b> — so‘rov tuzilganda yozib qo‘yilgan o‘zgarmas qiymat. Masalan, “baho = 5”. Boshqa qiymat uchun so‘rovni qayta tahrirlash kerak.</li><li><b>Dinamik parametr</b> — so‘rov ishga tushganda foydalanuvchidan so‘raladigan qiymat. Masalan, dastur “Qaysi sinf?” deb so‘raydi va javobga qarab natija chiqaradi.</li></ul>\n<h4>Hisoblashlar</h4>\n<p>Bazada yangi hisoblanadigan maydon yaratish mumkin. Uning qiymati boshqa maydonlardan formula yordamida topiladi va alohida saqlanishi shart emas. Masalan, summa = narx * miqdor.</p>\n<div class=\"ex\"><b>Misol.</b> “Mahsulotlar” jadvalida Narx va Miqdor bor. So‘rovda Summa maydoni narx va miqdorni ko‘paytirib hisoblanadi. Chegirma foizi dinamik parametr bo‘lsa, har safar boshqa foiz kiritib natijani ko‘rish mumkin.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Statik parametr o‘zgarmas.</li><li>Dinamik parametr ishga tushganda so‘raladi.</li><li>Hisoblanadigan maydon formuladan hosil bo‘ladi.</li></ul>","quiz":[{"q":"Statik parametr qanday qiymat?","o":["Har safar foydalanuvchi kiritadigan qiymat","Tasodifiy qiymat","So‘rovga oldindan yozib qo‘yilgan o‘zgarmas qiymat","Rasm"],"a":2,"e":"Statik parametr so‘rov ichida qat’iy turadi."},{"q":"Dinamik parametr qachon kiritiladi?","o":["Hech qachon","Jadval o‘chirilganda","Kompyuter o‘chirilganda","So‘rov ishga tushganda"],"a":3,"e":"Dastur foydalanuvchidan qiymat so‘raydi."},{"q":"Har safar boshqa sinfni tanlab natija ko‘rish uchun qaysi parametr qulay?","o":["Dinamik","Rasmli","Statik","Yashirin kalit"],"a":0,"e":"Qiymat har safar so‘raladi."},{"q":"Statik parametrli so‘rovda boshqa qiymat uchun nima qilinadi?","o":["Jadvalni o‘chirish kerak","So‘rovni qayta tahrirlash kerak","Kompyuterni o‘chirish kerak","Hech narsa qilish shart emas"],"a":1,"e":"Qiymat so‘rov ichida yozilgan."},{"q":"Summa = narx * miqdor qanday maydonga misol?","o":["Rasm maydoni","Birlamchi kalit","Hisoblanadigan maydon","Tashqi kalit"],"a":2,"e":"Qiymat formuladan topiladi."},{"q":"Hisoblanadigan maydon qiymati nima asosida topiladi?","o":["Ekran o‘lchami asosida","Faylning hajmi asosida","Tasodifiy tanlash asosida","Boshqa maydonlar va formula asosida"],"a":3,"e":"Formula maydonlardan foydalanadi."},{"q":"Chegirma foizini har safar so‘rab hisob-kitob qilish qaysi parametrga mos?","o":["Statik parametrga","Kalit maydonga","Dinamik parametrga","Jadval nomiga"],"a":2,"e":"Foiz ishga tushganda kiritiladi."},{"q":"“Baho = 5” kabi yozib qo‘yilgan shart nima?","o":["Forma","Dinamik parametr","Statik parametr","Tashqi kalit"],"a":2,"e":"Qiymat oldindan belgilangan."},{"q":"Hisoblanadigan maydonni alohida saqlash shartmi?","o":["Faqat rasm sifatida","Yo‘q, u formuladan hosil bo‘lishi mumkin","Ha, doim","Faqat bo‘sh holda"],"a":1,"e":"Natija so‘rovda hisoblab chiqariladi."},{"q":"Parametrli so‘rovning afzalligi qaysi?","o":["Kalit kerak bo‘lmaydi","Bitta so‘rov turli qiymatlar bilan ishlatiladi","Hisobot chop etilmaydi","Jadval hajmi kamayadi"],"a":1,"e":"Qayta tuzish shart emas."}]},{"t":"61-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 7</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ma‘lumotlar bazasini yaratish. Ma‘lumot turlari va katak hajmlari. Uch tomonlama bog‘lanish.</li><li>Birga-bir va birga-ko‘p bog‘lanish. Ko‘pga-ko‘p bog‘lanish. Bog‘lanishlar yaratish va foydalanish</li><li>Oddiy yozuvli va relyatsion ma‘lumotlar bazasi o‘rtasidagi farq</li><li>Ma‘lumotlarni import qilish. Relyatsion ma‘lumotlar bazasini yaratish.</li><li>Kalitlar. Murakkab kalit. Tashqi kalit.</li><li>Bog‘lanishlar yaxlitligi. Ma‘lumotlar validatsiyasi va verifikatsiyasi</li><li>Qidirish amallari. Murakkab querylar. Ichki va jamlanma querylar.</li><li>Statik va dinamik parametrlar. Ma‘lumotlar bazasi doirasida hisoblashlarni amalga oshirish.</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"To‘g‘ri mulohazani tanlang.","o":["Relyatsion baza takrorlanishni oshiradi","Relyatsion baza katta hajm uchun qulay","Relyatsion baza bitta jadvaldan iborat","Yassi baza murakkab so‘rovlarga eng mos"],"a":1,"e":"U katta hajmga mos."},{"q":"Summa = narx * miqdor qanday maydonga misol?","o":["Rasm maydoni","Birlamchi kalit","Hisoblanadigan maydon","Tashqi kalit"],"a":2,"e":"Qiymat formuladan topiladi."},{"q":"Murakkab kalit nima?","o":["Jadval nomi","Parol","Faqat bitta uzun matn","Ikki yoki undan ortiq maydondan iborat kalit"],"a":3,"e":"U bir nechta maydonning birikmasi."},{"q":"“8-sinf VA baho 5” sharti kimlarni chiqaradi?","o":["Faqat 5 olganlarni","Faqat 8-sinf o‘quvchilarini","Ikkala talabga mos o‘quvchilarni","Barcha o‘quvchilarni"],"a":2,"e":"VA ikkala shartni talab qiladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Bir jadvalda bitta mavzu bo‘lishi tavsiya etiladi","Jadvallar bog‘lanmaydi","Bir jadvalda hamma mavzu aralash","Kalit kerak emas"],"a":0,"e":"Mavzular ajratiladi."},{"q":"Statik parametrli so‘rovda boshqa qiymat uchun nima qilinadi?","o":["Jadvalni o‘chirish kerak","So‘rovni qayta tahrirlash kerak","Kompyuterni o‘chirish kerak","Hech narsa qilish shart emas"],"a":1,"e":"Qiymat so‘rov ichida yozilgan."},{"q":"Tug‘ilgan sana kelajakda bo‘lmasligi qoidasi nimaga misol?","o":["Bog‘lanishga","Eksportga","Saralashga","Validatsiyaga"],"a":3,"e":"Bu kiritish qoidasi."},{"q":"“VA” (AND) mantiqiy amalida yozuv qachon tanlanadi?","o":["Faqat birinchi shart bajarilganda","Hech bir shart bajarilmaganda","Barcha shartlar bajarilganda","Har doim"],"a":2,"e":"VA hamma shartni talab qiladi."},{"q":"Har obyekt uchun nima yaratiladi?","o":["Hammasiga bitta umumiy jadval","Faqat rasm","Alohida jadval","Faqat diagramma"],"a":2,"e":"Obyekt uchun jadval."},{"q":"Bog‘lanish yaratishdan oldin nima tayyorlanadi?","o":["Yozuvlar nusxalanadi","Dastur o‘chiriladi","Hisobot chop etiladi","Jadvallar va kalit maydonlar"],"a":3,"e":"Avval jadval va kalitlar bo‘lishi kerak."},{"q":"Baho 4 o‘rniga 5 yozilgan xatoni qaysi usul topadi?","o":["Verifikatsiya, ya’ni manba bilan solishtirish","Hech qaysi usul topa olmaydi","Jadval ranglari","Oddiy qoida (2 dan 5 gacha)"],"a":0,"e":"5 ham ruxsat etilgan qiymat, shuning uchun manba kerak."},{"q":"Ikki jadvalni bog‘lash uchun qaysi kalitlardan foydalaniladi?","o":["Rasm va matn","Hisobot va forma","Ikkita parol","Birlamchi va tashqi kalit"],"a":3,"e":"Bog‘lanish shu juftlik orqali amalga oshadi."},{"q":"Katak hajmini keraksiz katta qilishning oqibati qaysi?","o":["Kalit ishlamaydi","Jadval o‘chadi","Xotira isrof bo‘ladi","Ma’lumot yo‘qoladi"],"a":2,"e":"Ortiqcha hajm xotirani band qiladi."},{"q":"Uch tomonlama bog‘lanishda nechta jadval ishtirok etadi?","o":["Ikkita","Uchta","Bitta","To‘rtta"],"a":1,"e":"Nomidan ko‘rinib turibdi: uch jadval."},{"q":"Parametrli so‘rovning afzalligi qaysi?","o":["Kalit kerak bo‘lmaydi","Bitta so‘rov turli qiymatlar bilan ishlatiladi","Hisobot chop etilmaydi","Jadval hajmi kamayadi"],"a":1,"e":"Qayta tuzish shart emas."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Birga-bir har doim bir jadval deganidir","Ko‘pga-ko‘p ikkita birga-ko‘pga ajratiladi","Birga-ko‘pda ikkala tomon ham bitta","Ko‘pga-ko‘p hech qachon kerak bo‘lmaydi"],"a":1,"e":"Oraliq jadval ikkita birga-ko‘p bog‘lanish beradi."},{"q":"Telefon operatori ismini saqlash uchun qaysi tur mos?","o":["Avtonomer","Qisqa matn","Mantiqiy","Sana va vaqt"],"a":1,"e":"Ism harflardan iborat matn."},{"q":"Ma’lumot izchilligi nimani anglatadi?","o":["Ma’lumot rangini","Ma’lumotlar bir-biriga zid bo‘lmasligini","Ma’lumot tezligini","Ma’lumot ko‘pligini"],"a":1,"e":"Izchillik — ziddiyatsizlik."},{"q":"Qaysi maydon birlamchi kalit uchun yomon tanlov?","o":["Yozuv tartib raqami","Familiya","Pasport seriyasi va raqami","O‘quvchi kodi"],"a":1,"e":"Familiyalar takrorlanishi mumkin."},{"q":"Vaziyat: mijoz manzili o‘zgardi, yassi jadvalda uning 50 buyurtmasi bor. Qanday muammo?","o":["Hech muammo yo‘q","Ko‘p qatorni o‘zgartirish kerak, xato ehtimoli ortadi","Manzil o‘zi o‘zgaradi","Jadval o‘chadi"],"a":1,"e":"Takrorlangan ma’lumot yangilashni qiyinlashtiradi."}]},{"t":"62-dars. Ma‘lumotlarni saralash. Ma‘lumot kiritish formalari.","lesson":"<p>Ma’lumotlarni saralash yozuvlarni tartib bilan joylashtirish demakdir. Ma’lumot kiritish formalari esa jadvalga ma’lumotni qulay va xatosiz kiritish uchun ishlatiladi.</p>\n<h4>Saralash</h4>\n<ul><li>O‘sish tartibida: kichikdan kattaga, A dan Z gacha, eskidan yangiga.</li><li>Kamayish tartibida: kattadan kichikka, Z dan A gacha, yangidan eskiga.</li><li>Bir nechta maydon bo‘yicha saralash mumkin: avval sinf bo‘yicha, so‘ng familiya bo‘yicha.</li></ul>\n<p>Saralash yozuvlarning mazmunini o‘zgartirmaydi, faqat ko‘rinish tartibini o‘zgartiradi.</p>\n<h4>Ma’lumot kiritish formalari</h4>\n<ul><li>Forma bir vaqtda bitta yozuvni ko‘rsatadi, shuning uchun kiritish qulay.</li><li>Unda matn maydonlari, ro‘yxatlar, bayroqchalar va tugmalar bo‘ladi.</li><li>Ro‘yxatdan tanlash yozuv xatolarini kamaytiradi.</li><li>Forma jadval yoki so‘rov asosida yaratiladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> O‘quvchilar jadvali familiya bo‘yicha A dan Z gacha saralanadi. Yangi o‘quvchini qo‘shish uchun forma ochiladi va maydonlar to‘ldiriladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Saralash o‘sish yoki kamayish tartibida bo‘ladi.</li><li>Forma kiritishni osonlashtiradi.</li></ul>","quiz":[{"q":"Saralash nima?","o":["Jadvalni nusxalash","Yozuvlarni o‘chirish","Yozuvlarni belgilangan tartibda joylashtirish","Maydon nomini almashtirish"],"a":2,"e":"Saralash tartib beradi."},{"q":"Familiyalarni A dan Z gacha joylashtirish qaysi tartib?","o":["Kamayish tartibi","Teskari kalit","O‘sish tartibi","Tasodifiy tartib"],"a":2,"e":"A dan Z gacha o‘sish tartibi."},{"q":"Narxlarni kattadan kichikka joylashtirish qaysi tartib?","o":["Kamayish tartibi","Alifbo tartibi","Hech qanday","O‘sish tartibi"],"a":0,"e":"Kattadan kichikka kamayish."},{"q":"Saralash yozuvlar mazmunini o‘zgartiradimi?","o":["Ha, kalitni almashtiradi","Yo‘q, faqat tartibini o‘zgartiradi","Ha, yozuvlarni o‘chiradi","Ha, qiymatlarni o‘zgartiradi"],"a":1,"e":"Mazmun o‘zgarmaydi."},{"q":"Avval sinf, so‘ng familiya bo‘yicha saralash nima deyiladi?","o":["Bir nechta maydon bo‘yicha saralash","Validatsiya","Eksport","Bitta maydon bo‘yicha saralash"],"a":0,"e":"Ikki maydon ketma-ket ishlatiladi."},{"q":"Forma nima uchun kerak?","o":["Parolni yashirish uchun","Ma’lumotni qulay kiritish va ko‘rish uchun","Faylni siqish uchun","Ma’lumotni o‘chirish uchun"],"a":1,"e":"Forma kiritishni osonlashtiradi."},{"q":"Forma odatda nechta yozuvni birdaniga ko‘rsatishi mumkin?","o":["Faqat o‘chirilganlarni","Hech birini","Barcha yozuvni doim","Bittasini"],"a":3,"e":"Bir vaqtda bitta yozuv."},{"q":"Formadagi ro‘yxatdan tanlash nimaga yordam beradi?","o":["Xatolarni ko‘paytirishga","Yozuv xatolarini kamaytirishga","Jadvalni o‘chirishga","Kalitni buzishga"],"a":1,"e":"Tayyor qiymatdan tanlanadi."},{"q":"Forma qanday asosda yaratiladi?","o":["Hech narsa asosida emas","Faqat rasm asosida","Jadval yoki so‘rov asosida","Faqat tovush asosida"],"a":2,"e":"Forma ma’lumot manbaiga bog‘lanadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Saralash jadvalni o‘chiradi","Saralashni o‘sish va kamayish tartibida bajarish mumkin","Saralash faqat sonlarga mumkin","Saralash faqat o‘sish tartibida bo‘ladi"],"a":1,"e":"Ikkala yo‘nalish mavjud."}]},{"t":"63-dars. Hisobotlar. Ma‘lumotlarni eksport qilish.","lesson":"<p>Hisobot — ma’lumotlarni chop etish yoki ko‘rsatish uchun chiroyli va tartibli shaklda tayyorlangan hujjat. Eksport esa ma’lumotni boshqa dastur formatiga o‘tkazishdir.</p>\n<h4>Hisobotlar</h4>\n<ul><li>Hisobot jadval yoki so‘rov asosida yaratiladi.</li><li>Unda ma’lumot guruhlanishi, saralanishi va jami qiymatlar chiqarilishi mumkin.</li><li>Sarlavha, sana va sahifa raqami qo‘shiladi.</li><li>Hisobot ma’lumotni o‘zgartirish uchun emas, ko‘rsatish va chop etish uchun mo‘ljallangan.</li></ul>\n<h4>Hisobot qismlari</h4>\n<ul><li>Sarlavha qismi — hisobot nomi.</li><li>Ma’lumotlar qismi — yozuvlar.</li><li>Yakuniy qism — jami va o‘rtacha qiymatlar.</li></ul>\n<h4>Ma’lumotlarni eksport qilish</h4>\n<p>Eksport yordamida baza ma’lumotlari elektron jadval, matn fayli yoki boshqa formatga saqlanadi. Shunda ularni boshqa dasturlarda ishlatish va boshqalarga yuborish mumkin.</p>\n<div class=\"ex\"><b>Misol.</b> Sinf bo‘yicha o‘rtacha baholar hisoboti tayyorlanadi, chop etiladi va xuddi shu ma’lumot elektron jadval fayliga eksport qilinadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Hisobot ma’lumotni tartibli ko‘rsatadi.</li><li>Eksport ma’lumotni boshqa formatga o‘tkazadi.</li></ul>","quiz":[{"q":"Hisobot nima?","o":["Parol","Ma’lumotni chop etish va ko‘rsatish uchun tayyorlangan hujjat","Dastur o‘chirish buyrug‘i","Jadvaldagi kalit maydon"],"a":1,"e":"Hisobot natijani tartibli ko‘rsatadi."},{"q":"Hisobot qaysi asosda yaratiladi?","o":["Faqat ovoz asosida","Hech narsa asosida emas","Jadval yoki so‘rov asosida","Faqat rasm asosida"],"a":2,"e":"Ma’lumot manbai kerak."},{"q":"Hisobotning asosiy vazifasi nima?","o":["Ma’lumotni ko‘rsatish va chop etish","Jadvalni o‘chirish","Yozuvlarni tahrirlash","Parolni o‘zgartirish"],"a":0,"e":"Hisobot ko‘rsatishga mo‘ljallangan."},{"q":"Hisobotning yakuniy qismida odatda nima bo‘ladi?","o":["Jami va o‘rtacha qiymatlar","Yangi jadval","Parol","Rasm kaliti"],"a":0,"e":"Yakuniy qism umumiy natijani beradi."},{"q":"Eksport nima?","o":["Ma’lumotni o‘chirish","Ma’lumotni boshqa formatga o‘tkazib saqlash","Jadvalni yashirish","Parolni tiklash"],"a":1,"e":"Eksport boshqa dasturga mos fayl beradi."},{"q":"Baza ma’lumotlarini elektron jadvalga o‘tkazish uchun nima qilinadi?","o":["Kalit almashtiriladi","Parol o‘rnatiladi","Eksport qilinadi","Jadval o‘chiriladi"],"a":2,"e":"Eksport formatni o‘zgartiradi."},{"q":"Hisobotda sana va sahifa raqami nima uchun qo‘shiladi?","o":["Eksportni taqiqlash uchun","Ma’lumotni o‘chirish uchun","Kalit yaratish uchun","Hujjatni tartibli va aniq qilish uchun"],"a":3,"e":"Bu chop etishga qulaylik beradi."},{"q":"Qaysi variant eksportga misol?","o":["Ma’lumotni matn fayliga saqlash","Maydon turini o‘zgartirish","So‘rovni o‘chirish","Yangi kalit belgilash"],"a":0,"e":"Boshqa formatda saqlash eksportdir."},{"q":"Hisobotda ma’lumotlarni guruhlash mumkinmi?","o":["Faqat o‘chirilganlar uchun","Ha, masalan sinf bo‘yicha","Yo‘q, mumkin emas","Faqat rasm uchun"],"a":1,"e":"Guruhlash hisobotda keng qo‘llanadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Eksport faqat rasm uchun","Eksport qilingan ma’lumotni boshqa dasturda ochish mumkin","Eksport ma’lumotni bazadan o‘chiradi","Hisobot yangi jadval yaratadi"],"a":1,"e":"Maqsad — boshqa dasturda foydalanish."}]},{"t":"64-dars. Formni normallashtirish. Ma‘lumotlar bazasini 3NFga normallashtirish.","lesson":"<p>Normallashtirish — ma’lumotlar bazasi jadvallarini ortiqcha takrorlanish va anomaliyalardan xoli qilib qayta tuzish jarayoni. Natijada ma’lumot bir joyda saqlanadi va uni yangilash oson bo‘ladi.</p>\n<h4>Normal formalar</h4>\n<ul><li><b>1NF</b> — har bir katakda bitta (bo‘linmas) qiymat bo‘ladi, takrorlanuvchi guruhlar yo‘q.</li><li><b>2NF</b> — 1NF bajarilgan va kalit bo‘lmagan har bir maydon butun kalitga bog‘liq. Bu qism-bog‘liqlikni yo‘qotadi.</li><li><b>3NF</b> — 2NF bajarilgan va kalit bo‘lmagan maydonlar boshqa kalit bo‘lmagan maydonlarga bog‘liq emas. Bu tranzitiv bog‘liqlikni yo‘qotadi.</li></ul>\n<h4>Nima uchun kerak?</h4>\n<ul><li>Takrorlanishni kamaytiradi.</li><li>Yangilash va o‘chirish xatolarini oldini oladi.</li><li>Xotirani tejaydi.</li><li>Ma’lumotlar izchilligini saqlaydi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Buyurtmalar jadvalida mijoz nomi va manzili har buyurtmada takrorlansa, uni alohida “Mijozlar” jadvaliga ajratib, buyurtmada faqat mijoz kodi qoldiriladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>1NF: katakda bitta qiymat.</li><li>2NF: butun kalitga bog‘liqlik.</li><li>3NF: tranzitiv bog‘liqlik yo‘q.</li></ul>","quiz":[{"q":"Normallashtirishning asosiy maqsadi nima?","o":["Yozuvlar sonini ko‘paytirish","Ortiqcha takrorlanishni kamaytirish","Kalitni o‘chirish","Hajmni oshirish"],"a":1,"e":"Normallashtirish takrorni yo‘qotadi."},{"q":"1NF talabi qaysi?","o":["Kalit bo‘lmasligi","Har katakda bitta bo‘linmas qiymat bo‘lishi","Hamma maydon bir xil bo‘lishi","Jadval bo‘sh bo‘lishi"],"a":1,"e":"1NF atomar qiymat talab qiladi."},{"q":"2NF nimani yo‘qotadi?","o":["Maydon nomlarini","Birlamchi kalitni","Barcha jadvallarni","Qism-bog‘liqlikni"],"a":3,"e":"Maydon butun kalitga bog‘liq bo‘ladi."},{"q":"3NF nimani yo‘qotadi?","o":["Jadval nomini","Birinchi yozuvni","Tashqi kalitni","Tranzitiv bog‘liqlikni"],"a":3,"e":"Kalit bo‘lmagan maydonlar o‘zaro bog‘liq bo‘lmaydi."},{"q":"Normal formalarning to‘g‘ri tartibi qaysi?","o":["1NF, 2NF, 3NF","3NF, 2NF, 1NF","1NF, 3NF, 2NF","2NF, 3NF, 1NF"],"a":0,"e":"Har keyingi forma oldingisini talab qiladi."},{"q":"Buyurtmalar jadvalida mijoz manzili har safar takrorlansa nima qilinadi?","o":["Manzil rasm qilinadi","Jadval o‘chiriladi","Alohida Mijozlar jadvaliga ajratiladi","Manzillar doim takrorlanadi"],"a":2,"e":"Takrorlanuvchi ma’lumot alohida jadvalga chiqariladi."},{"q":"Takrorlanish bo‘lgan jadvalda manzil o‘zgarsa qanday xavf bor?","o":["Jadval tezlashishi","Hech qanday xavf yo‘q","Kalit paydo bo‘lishi","Ba’zi yozuvlarda eski manzil qolib ketishi"],"a":3,"e":"Yangilash anomaliyasi."},{"q":"Bitta katakda “Ali, Vali, Sami” kabi bir nechta ism yozilgan bo‘lsa, qaysi forma buzilgan?","o":["Hech qaysi","3NF","2NF","1NF"],"a":3,"e":"Katak bo‘linadigan qiymatlarni saqlayapti."},{"q":"Normallashtirish natijasida odatda nima o‘zgaradi?","o":["Dastur o‘chadi","Barcha yozuvlar yo‘qoladi","Faqat bitta maydon qoladi","Jadvallar soni ko‘payishi mumkin"],"a":3,"e":"Ma’lumot mantiqiy jadvallarga ajratiladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["3NF dagi jadval 2NF talabini ham bajaradi","2NF dan oldin 3NF bajariladi","Normallashtirish takrorni oshiradi","3NF 1NF ni inkor qiladi"],"a":0,"e":"Formalar ketma-ket kuchayadi."}]},{"t":"65-dars. Ma‘lumotlar lug‘ati. Ma‘lumot turlari. Fayl va ma‘lumotlarni boshqarish.","lesson":"<p>Ma’lumotlar lug‘ati — bazadagi barcha ma’lumotlarning tavsifi saqlanadigan joy. Unda jadvallar, maydonlar, ularning turlari, hajmi va ma’nosi yoziladi. Shu sababli lug‘atni “ma’lumot haqidagi ma’lumot” deb ham atashadi.</p>\n<h4>Lug‘atda nimalar bo‘ladi?</h4>\n<ul><li>Jadval va maydon nomlari.</li><li>Ma’lumot turi va maydon hajmi.</li><li>Kalitlar va bog‘lanishlar.</li><li>Maydonning qisqa izohi va ruxsat etilgan qiymatlar.</li></ul>\n<h4>Ma’lumot turlari</h4>\n<p>Matn, son, sana, mantiqiy va boshqa turlar bazada qiymatlarni to‘g‘ri saqlash va tekshirish uchun belgilanadi.</p>\n<h4>Fayl va ma’lumotlarni boshqarish</h4>\n<ul><li>Baza fayli nusxasi (zaxira) muntazam saqlanadi.</li><li>Foydalanuvchilarga ruxsatlar beriladi: kimdir faqat o‘qiydi, kimdir tahrirlaydi.</li><li>Eskirgan yoki keraksiz yozuvlar tartibli tarzda arxivlanadi yoki o‘chiriladi.</li><li>Fayllar tushunarli nomlar bilan saqlanadi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Lug‘atda “Tug‘ilgan_sana” maydoni: tur — sana, izoh — o‘quvchining tug‘ilgan kuni, kelajak sana kiritilmaydi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Lug‘at baza tuzilmasini tavsiflaydi.</li><li>Zaxira nusxa ma’lumotni yo‘qolishdan saqlaydi.</li></ul>","quiz":[{"q":"Ma’lumotlar lug‘ati nima?","o":["Rasm to‘plami","Parollar ro‘yxati","Bazadagi ma’lumotlar tavsifi saqlanadigan joy","Bazadagi eng katta jadval"],"a":2,"e":"Lug‘at tuzilmani tavsiflaydi."},{"q":"Lug‘atda odatda nimalar tavsiflanadi?","o":["Faqat foydalanuvchi rasmi","Faqat dastur narxi","Faqat ekran rangi","Maydonlar, turlar, hajm va bog‘lanishlar"],"a":3,"e":"Bu baza tuzilmasi haqida ma’lumot."},{"q":"Lug‘at nima uchun “ma’lumot haqidagi ma’lumot” deyiladi?","o":["U faqat nusxa bo‘ladi","U faqat sonlarni saqlaydi","U bo‘sh bo‘ladi","U ma’lumotlarning o‘zi emas, ularning tavsifini saqlaydi"],"a":3,"e":"Tavsif metama’lumot."},{"q":"Zaxira nusxa nima uchun kerak?","o":["Jadvalni sekinlashtirish uchun","Ma’lumot yo‘qolsa tiklash uchun","Rasm qo‘shish uchun","Kalitni o‘chirish uchun"],"a":1,"e":"Zaxira yo‘qotishdan himoyalaydi."},{"q":"Foydalanuvchilarga ruxsat berishdan maqsad nima?","o":["Hammaga hammasini ruxsat etish","Bazani o‘chirish","Eksportni taqiqlash","Kim nimani qila olishini cheklash"],"a":3,"e":"Ruxsatlar xavfsizlikni beradi."},{"q":"Maydon turi lug‘atda nima uchun yoziladi?","o":["Qiymatni to‘g‘ri saqlash va tekshirish uchun","Chop etish uchun","Fayl nomi uchun","Rang tanlash uchun"],"a":0,"e":"Tur qiymat xarakterini belgilaydi."},{"q":"Qaysi biri fayllarni boshqarishning yaxshi odati?","o":["Fayllarni tushunarli nom bilan saqlash","Hammaga parolni aytish","Zaxira nusxa olmaslik","Barcha fayllarni nomsiz saqlash"],"a":0,"e":"Tushunarli nom topishni osonlashtiradi."},{"q":"“Tug‘ilgan_sana” maydoni uchun lug‘atda qaysi tur yoziladi?","o":["Sana","Avtonomer","Rasm","Mantiqiy"],"a":0,"e":"Sana uchun mos tur."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Lug‘at yozuvlarni tahrirlaydi","Lug‘at faqat parol saqlaydi","Lug‘atda kalitlar va bog‘lanishlar ham tavsiflanadi","Lug‘at bazadan alohida bo‘lmaydi"],"a":2,"e":"Kalit va bog‘lanishlar tuzilmaning bir qismi."},{"q":"Eskirgan keraksiz yozuvlar bilan nima qilish mumkin?","o":["Kalitga aylantirish","Tartibli arxivlash yoki o‘chirish","Parolsiz qoldirish","Hammasini ko‘paytirish"],"a":1,"e":"Bu bazani toza saqlaydi."}]},{"t":"66-dars. Bevosita fayldan foydalanish. Boshqaruv axborot tizimlari.","lesson":"<p>Ma’lumotlar bilan ishlashning ikki yo‘li bor: faylga bevosita murojaat qilish va ma’lumotlar bazasini boshqarish tizimi orqali ishlash. Boshqaruv axborot tizimlari esa tashkilotni boshqarishda yordam beradi.</p>\n<h4>Bevosita fayldan foydalanish</h4>\n<ul><li>Dastur ma’lumotni to‘g‘ridan-to‘g‘ri fayldan o‘qiydi va unga yozadi.</li><li>Oddiy va kichik hajmli ma’lumot uchun qulay.</li><li>Qidirish, bog‘lash va himoya qilishni dasturchi o‘zi tashkil qilishi kerak.</li><li>Bir vaqtda ko‘p foydalanuvchi ishlaganda ma’lumot buzilishi xavfi bor.</li></ul>\n<h4>Boshqaruv axborot tizimlari (BAT)</h4>\n<p>BAT tashkilot faoliyati haqidagi ma’lumotlarni yig‘adi, qayta ishlaydi va rahbarlarga qaror qabul qilish uchun hisobot shaklida taqdim etadi. Ular odatda ma’lumotlar bazasiga tayanadi.</p>\n<ul><li>Maktabda: o‘quvchilar, baholar va davomat tizimi.</li><li>Do‘konda: tovar qoldig‘i va savdo hisobi.</li><li>Korxonada: xodimlar va ish haqi hisobi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab tizimi sinf bo‘yicha o‘rtacha bahoni hisoblab, direktorga hisobot sifatida ko‘rsatadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Fayl bilan bevosita ishlash sodda, lekin cheklangan.</li><li>BAT qaror qabul qilishga yordam beradi.</li></ul>","quiz":[{"q":"Bevosita fayldan foydalanishda dastur ma’lumotni qanday oladi?","o":["Ma’lumotdan foydalanmaydi","To‘g‘ridan-to‘g‘ri fayldan o‘qiydi","Faqat internetdan yuklaydi","Faqat rasmdan oladi"],"a":1,"e":"Bevosita — to‘g‘ridan-to‘g‘ri."},{"q":"Bevosita fayl usulining kamchiligi qaysi?","o":["Ma’lumot hech qachon yozilmasligi","Faqat rasm bilan ishlashi","Juda ko‘p tayyor vositalar bo‘lishi","Qidirish va himoyani dasturchi o‘zi tashkil qilishi kerak"],"a":3,"e":"Tayyor boshqaruv vositalari yo‘q."},{"q":"Qaysi holatda oddiy fayl bilan ishlash yetarli bo‘lishi mumkin?","o":["Katta bank tizimida","Kichik hajmli oddiy ma’lumotda","Millionlab yozuv va ko‘p foydalanuvchi bo‘lganda","Murakkab bog‘lanishlarda"],"a":1,"e":"Kichik ish uchun fayl yetarli."},{"q":"BAT nima?","o":["Tashkilot ma’lumotlarini qayta ishlab, qaror qabul qilishga yordam beruvchi tizim","Faqat o‘yin dasturi","Rasm tahrirlagich","Antivirus"],"a":0,"e":"BAT boshqaruv uchun axborot beradi."},{"q":"BAT natijalari rahbarga odatda qanday shaklda beriladi?","o":["Faqat tovush shaklida","Hisobot shaklida","Ko‘rsatilmaydi","Parol shaklida"],"a":1,"e":"Hisobotlar qaror uchun asos."},{"q":"Qaysi biri BATga misol?","o":["Oddiy kalkulyator","Matn muharriri","Rangli rasm","Maktabdagi o‘quvchilar va baholar tizimi"],"a":3,"e":"Bu tashkilot ma’lumotini yuritadi."},{"q":"Ko‘p foydalanuvchi bir faylga bir vaqtda yozsa nima xavfi bor?","o":["Ma’lumot buzilishi mumkin","Ma’lumot yaxshilanadi","Hech xavf yo‘q","Fayl kichrayadi"],"a":0,"e":"Boshqaruvsiz parallel yozish muammo."},{"q":"BAT odatda nimaga tayanadi?","o":["Faqat qog‘ozga","Ma’lumotlar bazasiga","Hech narsaga","Faqat o‘yinlarga"],"a":1,"e":"Ma’lumot bazada saqlanadi."},{"q":"Do‘konda tovar qoldig‘ini hisoblash tizimi nima deb qaraladi?","o":["Brauzer","Operatsion tizim","Faqat grafik muharrir","Axborot tizimiga misol"],"a":3,"e":"U ma’lumot yuritadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["BAT faqat o‘yin uchun","BAT hisobot chiqara olmaydi","BAT ma’lumot saqlamaydi","BAT rahbarga qaror qabul qilishda yordam beradi"],"a":3,"e":"BATning maqsadi shu."}]},{"t":"67-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 8</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ma‘lumotlarni saralash. Ma‘lumot kiritish formalari.</li><li>Hisobotlar. Ma‘lumotlarni eksport qilish.</li><li>Formni normallashtirish. Ma‘lumotlar bazasini 3NFga normallashtirish.</li><li>Ma‘lumotlar lug‘ati. Ma‘lumot turlari. Fayl va ma‘lumotlarni boshqarish.</li><li>Bevosita fayldan foydalanish. Boshqaruv axborot tizimlari.</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Buyurtmalar jadvalida mijoz manzili har safar takrorlansa nima qilinadi?","o":["Manzil rasm qilinadi","Jadval o‘chiriladi","Alohida Mijozlar jadvaliga ajratiladi","Manzillar doim takrorlanadi"],"a":2,"e":"Takrorlanuvchi ma’lumot alohida jadvalga chiqariladi."},{"q":"Qaysi holatda oddiy fayl bilan ishlash yetarli bo‘lishi mumkin?","o":["Katta bank tizimida","Kichik hajmli oddiy ma’lumotda","Millionlab yozuv va ko‘p foydalanuvchi bo‘lganda","Murakkab bog‘lanishlarda"],"a":1,"e":"Kichik ish uchun fayl yetarli."},{"q":"Foydalanuvchilarga ruxsat berishdan maqsad nima?","o":["Hammaga hammasini ruxsat etish","Bazani o‘chirish","Eksportni taqiqlash","Kim nimani qila olishini cheklash"],"a":3,"e":"Ruxsatlar xavfsizlikni beradi."},{"q":"“Tug‘ilgan_sana” maydoni uchun lug‘atda qaysi tur yoziladi?","o":["Sana","Avtonomer","Rasm","Mantiqiy"],"a":0,"e":"Sana uchun mos tur."},{"q":"Familiyalarni A dan Z gacha joylashtirish qaysi tartib?","o":["Kamayish tartibi","Teskari kalit","O‘sish tartibi","Tasodifiy tartib"],"a":2,"e":"A dan Z gacha o‘sish tartibi."},{"q":"Forma nima uchun kerak?","o":["Parolni yashirish uchun","Ma’lumotni qulay kiritish va ko‘rish uchun","Faylni siqish uchun","Ma’lumotni o‘chirish uchun"],"a":1,"e":"Forma kiritishni osonlashtiradi."},{"q":"Lug‘at nima uchun “ma’lumot haqidagi ma’lumot” deyiladi?","o":["U faqat nusxa bo‘ladi","U faqat sonlarni saqlaydi","U bo‘sh bo‘ladi","U ma’lumotlarning o‘zi emas, ularning tavsifini saqlaydi"],"a":3,"e":"Tavsif metama’lumot."},{"q":"Eskirgan keraksiz yozuvlar bilan nima qilish mumkin?","o":["Kalitga aylantirish","Tartibli arxivlash yoki o‘chirish","Parolsiz qoldirish","Hammasini ko‘paytirish"],"a":1,"e":"Bu bazani toza saqlaydi."},{"q":"Hisobot qaysi asosda yaratiladi?","o":["Faqat ovoz asosida","Hech narsa asosida emas","Jadval yoki so‘rov asosida","Faqat rasm asosida"],"a":2,"e":"Ma’lumot manbai kerak."},{"q":"3NF nimani yo‘qotadi?","o":["Jadval nomini","Birinchi yozuvni","Tashqi kalitni","Tranzitiv bog‘liqlikni"],"a":3,"e":"Kalit bo‘lmagan maydonlar o‘zaro bog‘liq bo‘lmaydi."},{"q":"Qaysi variant eksportga misol?","o":["Ma’lumotni matn fayliga saqlash","Maydon turini o‘zgartirish","So‘rovni o‘chirish","Yangi kalit belgilash"],"a":0,"e":"Boshqa formatda saqlash eksportdir."},{"q":"Ko‘p foydalanuvchi bir faylga bir vaqtda yozsa nima xavfi bor?","o":["Ma’lumot buzilishi mumkin","Ma’lumot yaxshilanadi","Hech xavf yo‘q","Fayl kichrayadi"],"a":0,"e":"Boshqaruvsiz parallel yozish muammo."},{"q":"Forma qanday asosda yaratiladi?","o":["Hech narsa asosida emas","Faqat rasm asosida","Jadval yoki so‘rov asosida","Faqat tovush asosida"],"a":2,"e":"Forma ma’lumot manbaiga bog‘lanadi."},{"q":"BAT natijalari rahbarga odatda qanday shaklda beriladi?","o":["Faqat tovush shaklida","Hisobot shaklida","Ko‘rsatilmaydi","Parol shaklida"],"a":1,"e":"Hisobotlar qaror uchun asos."},{"q":"Normallashtirishning asosiy maqsadi nima?","o":["Yozuvlar sonini ko‘paytirish","Ortiqcha takrorlanishni kamaytirish","Kalitni o‘chirish","Hajmni oshirish"],"a":1,"e":"Normallashtirish takrorni yo‘qotadi."},{"q":"BAT nima?","o":["Tashkilot ma’lumotlarini qayta ishlab, qaror qabul qilishga yordam beruvchi tizim","Faqat o‘yin dasturi","Rasm tahrirlagich","Antivirus"],"a":0,"e":"BAT boshqaruv uchun axborot beradi."},{"q":"Normallashtirish natijasida odatda nima o‘zgaradi?","o":["Dastur o‘chadi","Barcha yozuvlar yo‘qoladi","Faqat bitta maydon qoladi","Jadvallar soni ko‘payishi mumkin"],"a":3,"e":"Ma’lumot mantiqiy jadvallarga ajratiladi."},{"q":"Hisobotda ma’lumotlarni guruhlash mumkinmi?","o":["Faqat o‘chirilganlar uchun","Ha, masalan sinf bo‘yicha","Yo‘q, mumkin emas","Faqat rasm uchun"],"a":1,"e":"Guruhlash hisobotda keng qo‘llanadi."},{"q":"Hisobot nima?","o":["Parol","Ma’lumotni chop etish va ko‘rsatish uchun tayyorlangan hujjat","Dastur o‘chirish buyrug‘i","Jadvaldagi kalit maydon"],"a":1,"e":"Hisobot natijani tartibli ko‘rsatadi."},{"q":"Forma odatda nechta yozuvni birdaniga ko‘rsatishi mumkin?","o":["Faqat o‘chirilganlarni","Hech birini","Barcha yozuvni doim","Bittasini"],"a":3,"e":"Bir vaqtda bitta yozuv."}]},{"t":"68-dars. Takrorlash","lesson":"<p><b>Takrorlash</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ma‘lumot, axborot va bilimlar bazasi. Ma‘lumot manbasi. Bevosita va bilvosita manbalardan ma‘lumot to‘plashning afzallik hamda kamchiliklari. Axborotning sifati</li><li>Kod berish, kodlash va shifrlash. Ma‘lumotlarni kodlashning afzallik va kamchiliklari. Simmetrik va asimmetrik shifrlash usullari.</li><li>Ma‘lumotlarning to‘g‘riligini tekshirish.</li><li>Vizual tekshirish va ma‘lumotlanri ikki marta kiritish.</li><li>Apparat ta‘minot. Ichki va tashqi qurilmalar</li><li>Xotira qurilmalari. Tizimli dasturiy ta‘minot. Drayverlar.</li><li>Amaliy dasturiy ta‘minot. Fotosuratni tahrirlash dasturiy ta‘minoti</li><li>Video tahrirlash dasturiy ta‘minoti. Veb sahifa ishlab chiqish dasturiy ta‘minoti</li><li>Foydalanuvchi interfeysi dizaynidagi boshqaruv elementlari. Utilit dasturlar. Buyurtma yoki tayyor dasturiy ta‘minot.</li><li>Loyiha (amaliy) ishi</li><li>Sensorlar. Harakat va bosim sensorlari, Namlik, harorat va yorug‘lik sensorlari</li><li>Elektron xavfsizlik tushunchasi.</li><li>Phishing, Pharming, Vishing, Troyan, Worm, Spyware, Rootkit, Adware, Ransomware tushunchalari va xavfsizlikni ta‘minlash.</li><li>Salomatlik va xavfsizlik.</li><li>Raqamli tengsizlik tushunchasi va sabablari, Sanoati rivojlangan va rivojlanmagan hududlar, Ijtimoiy-iqtisodiy guruhlar.</li><li>Samarasi yuqori va past bo‘lgan texnologiyalar. Turli davlatlardagi holatlarni o‘rganish</li><li>Tarmoq kompyuterlari. Lokal hududiy (Local area networks) va global hududiy tarmoq (Wide area networks).</li><li>Kliyent-server va peer-to-peer tarmoqlari.</li><li>Virtual shaxsiy tarmoq (VPN)</li><li>Intranet va ekstranet. Internet va uning xususiyatlari</li><li>Internetda muloqot qilish. Mobil tarmoqlar</li><li>Video va veb konferensiya. Videokonferensiyaning jamiyatga ta‘siri</li><li>Ekspert tizim haqida</li><li>Bilimlar bazasi va yakunlovchi mexanizm</li><li>Foydalanuvchi interfeysi</li><li>Ekspert tizimlardan foydalanish</li><li>Ma‘lumotlarni qayta ishlash tizimlari</li><li>Real vaqt rejimida qayta ishlash tizimi</li><li>Elektron jadval yaratish. Qatorlar va ustunlarni boshqarish</li><li>Elektron jadval xavfsizligi</li><li>Panel va oynalarni interfeysga mahkamlash</li><li>Elektron jadvalni formatlash. Shartli formatlash</li><li>Formula va funksiyalarni yaratish. Katakka absolyut va nisbiy murojaat</li><li>Nomlangan katak va diapazon</li><li>Yaxlitlash funksiyalari</li><li>Sana va vaqtga oid funksiyalar. Shartli funksiyalar. Qidirish funksiyalari</li><li>INDEX va MATCH funksiyalari</li><li>Shartli statistik funksiyalar</li><li>Validatsiya qoidalari</li><li>Elektron jadvalga qo‘llanadigan validatsiya</li><li>Ma‘lumotlar kiritilishini tekshirish</li><li>Ma‘lumotlarni filtrlash va saralash</li><li>Jamlovchi jadvallar va diagrammalar</li><li>Ma‘lumotlarni import va eksport qilish</li><li>Grafik va diagrammalar. Modellashtirish. Simulyatorlar</li><li>Ma‘lumotlar bazasini yaratish. Ma‘lumot turlari va katak hajmlari. Uch tomonlama bog‘lanish.</li><li>Birga-bir va birga-ko‘p bog‘lanish. Ko‘pga-ko‘p bog‘lanish. Bog‘lanishlar yaratish va foydalanish</li><li>Oddiy yozuvli va relyatsion ma‘lumotlar bazasi o‘rtasidagi farq</li><li>Ma‘lumotlarni import qilish. Relyatsion ma‘lumotlar bazasini yaratish.</li><li>Kalitlar. Murakkab kalit. Tashqi kalit.</li><li>Bog‘lanishlar yaxlitligi. Ma‘lumotlar validatsiyasi va verifikatsiyasi</li><li>Qidirish amallari. Murakkab querylar. Ichki va jamlanma querylar.</li><li>Statik va dinamik parametrlar. Ma‘lumotlar bazasi doirasida hisoblashlarni amalga oshirish.</li><li>Ma‘lumotlarni saralash. Ma‘lumot kiritish formalari.</li><li>Hisobotlar. Ma‘lumotlarni eksport qilish.</li><li>Formni normallashtirish. Ma‘lumotlar bazasini 3NFga normallashtirish.</li><li>Ma‘lumotlar lug‘ati. Ma‘lumot turlari. Fayl va ma‘lumotlarni boshqarish.</li><li>Bevosita fayldan foydalanish. Boshqaruv axborot tizimlari.</li></ul><p>Test <b>10 ta aralash savoldan</b> iborat. Qiynalgan mavzuingizning darsini qayta o‘qib chiqing.</p>","quiz":[{"q":"Ma’lumotlar markazlashgan holda qaysi tarmoqda saqlanadi?","o":["P2P","Faqat Bluetooth","Kliyent-server","Hech qaysida"],"a":2,"e":"Ma’lumotlar serverda saqlanadi."},{"q":"1NF talabi qaysi?","o":["Kalit bo‘lmasligi","Har katakda bitta bo‘linmas qiymat bo‘lishi","Hamma maydon bir xil bo‘lishi","Jadval bo‘sh bo‘lishi"],"a":1,"e":"1NF atomar qiymat talab qiladi."},{"q":"Veb sahifaning ko‘rinishini bezash uchun nima ishlatiladi?","o":["RAM","Drayver","SSD","CSS"],"a":3,"e":"CSS ranglar va joylashuvni boshqaradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["BAT faqat o‘yin uchun","BAT hisobot chiqara olmaydi","BAT ma’lumot saqlamaydi","BAT rahbarga qaror qabul qilishda yordam beradi"],"a":3,"e":"BATning maqsadi shu."},{"q":"Nomlangan diapazon funksiyada qanday ishlatiladi?","o":["Argument sifatida: =SUM(Sotuv)","Faqat diagrammada","Faqat chop etishda","Faqat sarlavhada"],"a":0,"e":"Nom manzil o‘rnida yoziladi."},{"q":"Murakkab kalit qachon kerak bo‘ladi?","o":["Faqat rasm saqlanganda","Bitta maydon yagonalikni ta’minlamaganda","Jadval bo‘sh bo‘lganda","Hech qachon"],"a":1,"e":"Yagonalikni maydonlar birikmasi beradi."},{"q":"Ransomware bilan zarar ko‘rmaslikning eng yaxshi choralaridan biri qaysi?","o":["Parolni oshkor qilish","Zaxira nusxa saqlash","Antivirusni o‘chirish","Barcha xatlarni ochish"],"a":1,"e":"Zaxira bo‘lsa, ma’lumot tiklanadi."},{"q":"Panelni yig‘ish (yashirish) nimaga yordam beradi?","o":["Dasturni tezlashtirishga","Parolni almashtirishga","Faylni saqlashga","Ish maydonini kengaytirishga"],"a":3,"e":"Yashirilgan panel joy bo‘shatadi, kerak bo‘lganda qayta ochiladi."},{"q":"Summa = narx * miqdor qanday maydonga misol?","o":["Rasm maydoni","Birlamchi kalit","Hisoblanadigan maydon","Tashqi kalit"],"a":2,"e":"Qiymat formuladan topiladi."},{"q":"Vaziyat: korxonaning ichki hisobotlari faqat xodimlarga ko‘rinishi kerak. Nima mos?","o":["Ijtimoiy tarmoq e’lon","Ochiq internet sayti","Intranet","Hech qaysi"],"a":2,"e":"Ichki ma’lumot uchun intranet mos."}]}];
